(window.TNQ=window.TNQ||[]).push({"terms":{"법률우위":{"d":"행정작용은 법률에 위반되어서는 안 된다는 원칙.","r":["법률유보"]},"법률유보":{"d":"국민의 권리를 제한하거나 의무를 지우는 행정작용은 법률의 근거가 있어야 한다는 원칙.","r":["법률우위"]},"신뢰보호원칙":{"d":"행정에 대한 국민의 정당하고 합리적인 신뢰는 보호되어야 한다는 원칙.","r":["부당결부금지"]},"부당결부금지":{"d":"행정작용과 실질적 관련이 없는 의무를 상대방에게 부과해서는 안 된다는 원칙.","r":["신뢰보호원칙"]},"자기구속":{"d":"행정관행이 형성되면 행정청이 그 관행에 스스로 구속되어 상대방에게 같은 기준을 적용해야 하는 법리.","r":["재량준칙"]},"재량준칙":{"d":"행정청이 재량권을 행사하는 기준을 정해 둔 행정규칙이다.","r":[]},"행정규칙":{"d":"행정조직 내부에서 상급기관이 하급기관에 정하는 규범으로 원칙적으로 대외적 구속력이 없다.","r":[]},"법규명령":{"d":"행정기관이 제정하여 국민과 법원을 구속하는 대외적 효력이 있는 법규범이다.","r":[]},"위임명령":{"d":"법률의 위임을 받아 새로운 입법사항을 정하는 법규명령.","r":["법규명령","집행명령"]},"집행명령":{"d":"상위 법령을 집행하기 위해 필요한 세부 사항을 정하는 명령으로 새로운 국민의 권리와 의무를 정할 수 없다.","r":[]},"법령보충적 행정규칙":{"d":"법령이 위임하여 법령의 내용을 보충하는 행정규칙으로 상위법령과 결합하여 대외적 구속력을 갖는다.","r":[]},"행정행위":{"d":"행정청이 구체적 사실에 관하여 법을 집행하는 공권력 행사로서 국민의 권리의무에 영향을 주는 행위.","r":["특허","인가"]},"특허":{"d":"특정인에게 새로운 권리나 능력 또는 포괄적 법률관계를 설정하는 형성적 행정행위.","r":["인가"]},"인가":{"d":"제3자의 법률행위를 보충하여 그 효력을 완성시켜 주는 강학상 행정행위이다.","r":[]},"공증":{"d":"특정 사실이나 법률관계의 존재를 공적으로 증명하는 준법률행위적 행정행위.","r":["수리"]},"수리":{"d":"행정청이 타인의 행위를 적법한 것으로 받아들이는 준법률행위적 행정행위.","r":["공증"]},"기속행위":{"d":"법규에 요건이 충족되면 행정청이 법이 정한 효과를 반드시 따라야 하는 행위이다.","r":[]},"재량행위":{"d":"행정청에게 법규가 선택의 여지를 주어 판단할 수 있게 한 행위이다.","r":[]},"부관":{"d":"행정행위의 효과를 제한하거나 의무를 부과하기 위해 주된 의사표시에 붙이는 종된 의사표시이다.","r":[]},"공정력":{"d":"행정행위가 하자가 있어도 권한 있는 기관이 취소하기 전까지는 유효한 것으로 통용되는 효력이다.","r":[]},"불가쟁력":{"d":"쟁송기간이 지나면 상대방이 더 이상 행정행위의 효력을 다툴 수 없게 되는 효력이다.","r":[]},"불가변력":{"d":"행정청 스스로도 행정행위를 직권으로 취소하거나 변경할 수 없게 되는 효력이다.","r":[]},"인허가의제":{"d":"주된 인허가를 받으면 관련 법률의 다른 인허가도 함께 받은 것으로 보는 제도이다.","r":[]},"직권취소":{"d":"행정청이 직권으로 위법 또는 부당한 행정행위를 취소하는 것이다.","r":[]},"철회":{"d":"하자 없이 성립한 행정행위의 효력을 후발적 사정을 이유로 장래에 향하여 소멸시키는 것이다.","r":[]},"이의신청":{"d":"행정청의 처분에 대하여 그 처분을 한 행정청에 다시 심사를 요청하는 불복 절차이다.","r":[]},"행정계획":{"d":"특정한 행정목표를 달성하기 위해 서로 관련되는 행정수단을 종합, 조정하여 장래의 목표를 제시하는 것이다.","r":[]},"형량명령":{"d":"계획을 세울 때 관련된 이익을 빠짐없이 정당하게 비교해야 한다는 요청으로 어기면 위법하다.","r":["행정계획"]},"공법상 계약":{"d":"공법적 효과의 발생을 목적으로 대등한 당사자 간 의사의 합치로 성립하는 계약이다.","r":[]},"행정지도":{"d":"행정기관이 일정한 행정목적을 실현하기 위해 상대방의 임의적 협력을 구하는 비권력적 사실행위이다.","r":[]},"확약":{"d":"행정청이 장래에 일정한 행정행위를 하거나 하지 않겠다고 약속하는 의사표시이다.","r":[]},"행정대집행":{"d":"대체적 작위의무를 이행하지 않을 때 행정청이 직접 하거나 제삼자로 하여금 하게 하고 비용을 징수하는 수단.","r":["이행강제금","직접강제"]},"대체적 작위의무":{"d":"타인이 대신 이행하여도 같은 결과를 얻을 수 있는 작위 의무이다.","r":[]},"이행강제금":{"d":"의무를 이행하지 않는 자에게 이행할 때까지 반복해서 부과하는 금전적 제재로 의무 이행을 간접적으로 강제한다.","r":[]},"직접강제":{"d":"의무자가 의무를 이행하지 않을 때 행정청이 의무자의 신체나 재산에 직접 실력을 행사하여 의무 이행 상태를 실현하는 강제수단이다.","r":[]},"즉시강제":{"d":"급박한 장해를 제거하려고 미리 의무를 명할 틈 없이 곧바로 실력을 행사하는 수단.","r":["직접강제"]},"강제징수":{"d":"금전급부의무를 이행하지 않는 사람의 재산에 실력을 행사해 의무가 이행된 상태를 만드는 수단.","r":[]},"행정형벌":{"d":"행정법상 의무 위반에 대하여 형법상 형벌을 과하는 제재.","r":["과징금"]},"과징금":{"d":"의무를 위반한 자에게 그로 인한 경제적 이익을 환수하거나 영업정지를 갈음하여 부과하는 금전적 제재이다.","r":[]},"질서위반행위":{"d":"법률상 의무를 위반하여 과태료를 부과하는 행위이다.","r":[]},"국가배상":{"d":"공무원의 위법한 직무행위나 영조물의 하자로 생긴 손해를 국가나 지방자치단체가 배상하는 제도.","r":["영조물","손실보상"]},"영조물":{"d":"국가나 지방자치단체가 행정 목적을 위해 제공한 인적, 물적 시설의 종합체이다.","r":[]},"손실보상":{"d":"적법한 공권력 행사로 생긴 특별한 희생에 대하여 국가가 해 주는 보상.","r":["국가배상"]},"사업인정":{"d":"공익사업을 수행하기 위해 토지등을 수용할 권리를 사업시행자에게 설정하여 주는 처분이다.","r":[]},"수용재결":{"d":"토지수용위원회가 사업시행자의 신청에 따라 토지의 수용 여부와 보상 등을 결정하는 처분이다.","r":[]},"이주대책":{"d":"공익사업으로 생활 근거를 잃게 되는 자에게 이주 정착지 등을 제공하는 사업시행자의 대책이다.","r":[]},"행정심판":{"d":"행정청의 처분이나 부작위에 대한 불복을 행정기관이 심리하고 재결하는 절차.","r":["사정재결"]},"사정재결":{"d":"심판청구가 이유 있어도 처분을 취소하는 것이 공공복리에 크게 반하면 행정심판위원회가 청구를 기각하는 재결이다.","r":[]},"사정판결":{"d":"처분이 위법해도 취소가 공공복리에 크게 반하면 법원이 원고의 청구를 기각하는 판결이다.","r":[]},"간접강제":{"d":"거부처분 취소판결 등의 취지에 따른 처분을 하지 않을 때 일정 기간 안에 이행하지 않으면 배상금을 부과하여 이행을 강제하는 제도이다.","r":[]},"항고소송":{"d":"행정청의 처분이나 부작위에 대한 불복 소송으로 취소소송, 무효등확인소송, 부작위위법확인소송이 있다.","r":[]},"당사자소송":{"d":"공법상 법률관계에 관한 소송으로 행정청이 아닌 권리주체를 피고로 한다.","r":[]},"민중소송":{"d":"선거나 국민투표의 위법 등 법규의 적정한 적용을 위해 일반 국민이 제기하는 객관소송이다.","r":[]},"기관소송":{"d":"국가나 공공단체의 기관 상호간의 권한 존부나 행사에 관한 다툼으로 제기하는 소송이다.","r":[]},"원처분주의":{"d":"취소소송의 대상을 원래의 처분으로 하고 재결은 고유한 위법이 있을 때만 대상으로 하는 입법 태도.","r":[]},"경업자소송":{"d":"경쟁 관계에 있는 사업자가 상대방에게 주어진 인허가를 다투는 소송.","r":[]},"집행정지":{"d":"처분의 효력이나 집행 또는 절차의 속행을 잠정적으로 정지시켜 회복하기 어려운 손해를 예방하는 제도이다.","r":[]},"내부위임":{"d":"권한을 대외적으로 이전하지 않고 내부적으로만 수임자에게 맡겨 위임자의 명의로 처분하게 하는 것이다.","r":[]},"훈령":{"d":"상급관청이 하급관청의 권한행사를 지휘하기 위해 발하는 명령이다.","r":[]},"주관쟁의결정권":{"d":"하급관청 사이에 권한 다툼이 있을 때 상급관청이 이를 해결하는 권한이다.","r":[]},"주민소송":{"d":"지방자치단체의 위법한 재무회계 행위에 대해 주민이 감사청구를 거쳐 법원에 제기하는 소송이다.","r":[]},"선결처분":{"d":"의회를 소집할 시간이 없을 때 지방자치단체장이 먼저 하는 긴급 처분.","r":[]},"소청심사위원회":{"d":"공무원이 징계처분 등에 불복할 때 이를 심사하는 합의제 기관이다.","r":[]},"직위해제":{"d":"공무원에게 직위를 부여하지 않는 처분으로 징계처분과는 다른 임시 조치이다.","r":[]},"당연퇴직":{"d":"공무원이 법정 사유에 해당하면 별도 행위 없이 퇴직되는 것이다.","r":[]},"징계부가금":{"d":"금품 수수나 횡령 등에 대하여 징계 외에 이득의 몇 배까지 추가로 부과하는 금전.","r":[]},"상태책임":{"d":"물건을 현실적으로 지배하는 사람이 그 물건에서 생긴 위험에 지는 경찰책임.","r":[]},"긴급 경찰권":{"d":"경찰책임이 없는 사람에게도 예외적으로 발동하는 경찰권.","r":[]},"행정재산":{"d":"국가가 직접 공용, 공공용, 기업용 또는 보존용으로 사용하는 재산으로 사권 설정이 제한된다.","r":[]},"일반재산":{"d":"행정재산 외의 국유재산으로 대부와 매각 등이 가능하며 시효취득의 대상이 된다.","r":[]},"변상금":{"d":"허가나 계약 없이 국유재산을 쓴 사람에게 사용료의 100분의 120을 물리는 금액.","r":["행정재산"]},"예비비":{"d":"예측할 수 없는 예산 외의 지출이나 예산 초과 지출에 충당하기 위해 세출예산에 계상하는 금액이다.","r":[]},"계속비":{"d":"완성에 수년이 필요한 사업에서 경비 총액과 연부액을 미리 의결받아 수년도에 걸쳐 지출하는 경비이다.","r":[]},"명시이월비":{"d":"연도 내 지출 완료가 어려운 경비를 국회 승인을 받아 다음 연도로 넘기는 경비.","r":["계속비"]},"국고채무부담행위":{"d":"예산으로 국회 의결을 얻어 국가가 미리 채무를 지는 행위.","r":[]},"정보공개":{"d":"공공기관이 보유, 관리하는 정보를 국민의 청구에 따라 공개하는 제도이다.","r":[]},"가명정보":{"d":"추가 정보 없이는 특정 개인을 알아볼 수 없도록 가명처리한 개인정보.","r":["정보주체"]},"정보주체":{"d":"처리되는 정보에 의하여 알아볼 수 있는 사람으로 그 정보의 주체가 되는 사람이다.","r":[]},"신뢰보호의 원칙":{"d":"행정청의 공적 견해표명을 믿은 국민의 정당한 신뢰는 보호되어야 한다는 원칙으로 귀책사유 없는 상대방이 보호 대상이다.","r":[]},"공적 견해표명":{"d":"신뢰보호의 원칙이 적용되려면 필요한 요건으로, 행정청이 개인에게 신뢰를 주는 언동을 하는 것이다.","r":[]},"행정의 자기구속의 원칙":{"d":"행정청이 동종 사안에서 같은 결정을 되풀이하여 행정관행이 생기면 합리적 이유 없이 이를 따르지 않을 수 없게 되는 원칙이다.","r":[]},"행정관행":{"d":"행정기관이 같은 사안에서 같은 방식으로 되풀이하여 처리함으로써 생긴 관행이다.","r":[]},"구체적 규범통제":{"d":"재판에서 법령의 위헌 또는 위법 여부가 재판의 전제가 될 때 법원이 그 법령을 심사하는 제도이다.","r":[]},"재판의 전제성":{"d":"법령의 위헌 여부가 재판의 결과에 영향을 미치는 관계에 있는 것이다.","r":[]},"위임입법":{"d":"국회가 법률로 정할 사항 중 일부를 행정부에 위임하여 정하게 하는 것이다.","r":[]},"행정입법":{"d":"행정기관이 법조문의 형식으로 일반적, 추상적 규범을 정립하는 것이다.","r":[]},"부령":{"d":"행정각부의 장이 법률이나 대통령령의 위임 또는 직권으로 발하는 명령이다.","r":[]},"총리령":{"d":"국무총리가 소관 사무에 관하여 법률이나 대통령령의 위임 또는 직권으로 발하는 명령이다.","r":[]},"재량권 일탈·남용":{"d":"재량권의 한계를 벗어나거나 그 목적에 어긋나게 행사하여 재량행위가 위법하게 되는 것이다.","r":[]},"집행력":{"d":"행정행위로 부과된 의무를 행정청이 스스로 실현시킬 수 있는 효력이다.","r":[]},"당연무효":{"d":"하자가 중대하고 명백하여 처음부터 행정행위의 효력이 없는 것이다.","r":[]},"선결문제":{"d":"민사나 형사 재판에서 본안 판단의 전제로 행정처분의 효력이나 위법 여부가 문제되는 것이다.","r":[]},"부담":{"d":"행정행위의 주된 내용에 붙이는 부관으로 상대방에게 작위, 부작위, 급부, 수인 의무를 부과하는 것이다.","r":[]},"부담부 행정행위":{"d":"부담이 붙은 행정행위로 부담을 이행하지 않아도 주된 행정행위의 효력은 당연히 소멸하지 않는다.","r":[]},"기부채납":{"d":"사인이 재산을 국가나 지방자치단체에 증여하고 국가나 지방자치단체가 이를 받아들이는 것이다.","r":[]},"수익적 처분":{"d":"상대방에게 권리나 이익을 부여하는 처분이다.","r":[]},"사전통지":{"d":"행정청이 의무를 부과하거나 권익을 제한하는 처분을 하기 전에 당사자에게 알리는 절차이다.","r":[]},"계획존속청구권":{"d":"행정계획이 변경되거나 폐지되지 않고 존속하도록 요구할 수 있는 권리이다.","r":[]},"행정사법작용":{"d":"행정주체가 행정 목적을 위해 사법 형식으로 하는 작용이다.","r":[]},"사실행위":{"d":"행정청이 법적 효과를 목적으로 하지 않고 일정한 사실상 결과를 발생시키는 행위이다.","r":[]},"사전결정":{"d":"종국적 행정행위를 하기 전에 그 요건 중 일부에 대하여 미리 내리는 종국적 규율이다.","r":[]},"부분허가":{"d":"하나의 사업의 일부에 대해 먼저 종국적으로 내리는 허가이다.","r":[]},"공법상 당사자소송":{"d":"공법상 법률관계에 관한 소송으로 권리주체 간에 직접 다투는 행정소송이다.","r":[]},"형성의 자유":{"d":"행정계획을 입안, 결정하는 행정주체가 가지는 폭넓은 재량이다.","r":[]},"도시관리계획":{"d":"특별시, 광역시, 시, 군의 개발, 정비, 보전을 위해 수립하는 토지 이용, 기반시설 등에 관한 계획이다.","r":[]},"도시기본계획":{"d":"도시의 장기 발전 방향을 제시하는 종합계획으로 일반 국민에 대한 직접적 구속력은 없다.","r":[]},"청문":{"d":"행정청이 처분을 하기 전에 당사자의 의견을 직접 들고 증거를 조사하는 절차이다.","r":[]},"공청회":{"d":"행정청이 공개적인 토론을 통해 전문가와 이해관계인 등으로부터 의견을 듣는 절차이다.","r":[]},"의견제출":{"d":"당사자등이 처분에 관하여 의견을 제출하는 절차로 청문, 공청회 이외의 방법이다.","r":[]},"행정응원":{"d":"행정청이 다른 행정청에 업무 수행에 필요한 협조를 요청하는 것이다.","r":[]},"송달":{"d":"행정청이 서류를 법에 정한 방법으로 상대방에게 전달하여 알게 하는 행위이다.","r":[]},"처분기준":{"d":"행정청이 처분을 하기 위해 미리 정하여 공표해야 하는 구체적 기준이다.","r":[]},"행정예고":{"d":"행정청이 정책이나 제도를 시행하기 전에 미리 국민에게 알리는 제도이다.","r":[]},"비공개대상정보":{"d":"공공기관의 정보공개에 관한 법률이 공개하지 않을 수 있다고 정한 정보이다.","r":[]},"개인정보처리자":{"d":"업무를 목적으로 개인정보 파일을 운용하기 위해 개인정보를 처리하는 공공기관, 법인, 단체, 개인이다.","r":[]},"가명":{"d":"추가 정보 없이는 특정 개인을 알아볼 수 없도록 처리한 이름 등이다.","r":[]},"대집행":{"d":"대체적 작위의무를 이행하지 않을 때 행정청이 스스로 이행하거나 제3자로 하여금 하게 하고 비용을 의무자에게 징수하는 강제집행이다.","r":[]},"계고처분":{"d":"대집행을 하기 전에 상당한 이행기간을 정하여 이행하지 않으면 대집행한다는 뜻을 문서로 알리는 절차이다.","r":[]},"일신전속적":{"d":"권리나 의무가 특정인에게만 속하여 다른 사람에게 이전, 상속되지 않는 성질이다.","r":[]},"행정권한의 위임":{"d":"행정기관이 법령에 따라 자기 권한의 일부를 다른 기관에 이전하여 수임기관의 이름과 책임으로 행사하게 하는 것이다.","r":[]},"권한의 대리":{"d":"대리기관이 피대리 행정청을 대신하여 그 이름으로 행사하고 그 효과가 피대리 행정청에 귀속되는 것이다.","r":[]},"재위임":{"d":"위임받은 사무의 일부를 다시 하급기관에 위임하는 것이다.","r":[]},"기관위임":{"d":"국가사무를 지방자치단체의 장에게 위임하여 처리하게 하는 것이다.","r":[]},"행정청":{"d":"행정에 관한 의사를 결정하여 표시하는 국가 또는 지방자치단체의 기관이다.","r":[]},"합의제행정기관":{"d":"여러 사람의 합의로 의사를 결정하는 행정위원회 같은 행정기관이다.","r":[]},"의결기관":{"d":"행정기관의 의사를 결정하지만 대외적으로 표시하지 못하는 기관이다.","r":[]},"자치사무":{"d":"지방자치단체가 그 존립 목적을 달성하기 위해 자기 책임 아래 처리하는 사무이다.","r":[]},"조례":{"d":"지방의회가 법령의 범위에서 자치사무 등에 관하여 제정하는 자치법규이다.","r":[]},"기관위임사무":{"d":"국가사무가 지방자치단체의 장에게 위임되어 그 장이 국가기관의 지위에서 처리하는 사무로 조례 제정 대상이 아니다.","r":[]},"거부처분":{"d":"국민의 신청에 대해 행정청이 이를 받아들이지 않겠다고 하는 처분으로 신청권이 있어야 성립한다.","r":[]},"신청권":{"d":"국민이 행정청에 일정한 행위를 해 달라고 요구할 수 있는 법규상 또는 조리상의 권리이다.","r":[]},"의무이행소송":{"d":"행정청이 일정한 처분을 하도록 법원이 명하도록 구하는 소송이다.","r":[]},"의무이행심판":{"d":"당사자의 신청에 대한 행정청의 거부처분이나 부작위에 대해 일정한 처분을 하도록 하는 행정심판이다.","r":[]},"취소소송":{"d":"행정청의 위법한 처분을 취소하거나 변경하는 소송이다.","r":[]},"무효등 확인소송":{"d":"처분등의 효력 유무 또는 존재 여부의 확인을 구하는 소송이다.","r":[]},"부작위위법확인소송":{"d":"행정청이 상당한 기간에 처분을 해야 할 법률상 의무가 있는데도 하지 않는 것의 위법 확인을 구하는 소송이다.","r":[]},"객관소송":{"d":"개인의 권리나 이익 보호가 아닌 법규의 적정한 적용을 목적으로 하는 소송이다.","r":[]},"원고적격":{"d":"소송에서 원고가 될 수 있는 자격으로 취소소송은 처분등의 취소를 구할 법률상 이익이 있는 자에게 인정된다.","r":[]},"피고적격":{"d":"소송에서 피고가 될 수 있는 자격으로 취소소송에서는 처분등을 한 행정청이 해당한다.","r":[]},"제소기간":{"d":"소송을 제기할 수 있는 법정 기간으로 이를 지나면 소가 부적법하다.","r":[]},"법률상 이익":{"d":"법률에 의하여 보호되는 직접적이고 구체적인 이익이다.","r":[]},"처분사유의 추가ㆍ변경":{"d":"처분 당시의 사유 외의 새로운 사유를 소송 중에 주장하는 것으로 기본적 사실관계의 동일성이 있는 범위에서 허용된다.","r":[]},"임시처분":{"d":"행정심판에서 처분이나 부작위 때문에 당사자가 입을 수 있는 중대한 불이익이나 급박한 위험을 막기 위해 임시로 지위를 정하는 제도이다.","r":[]},"행정심판위원회":{"d":"행정심판 청구를 심리하고 재결하는 합의제 행정기관이다.","r":[]},"재결":{"d":"행정심판위원회가 심판청구에 대해 심리를 거쳐 내리는 최종 판단이다.","r":[]},"처분명령재결":{"d":"의무이행심판에서 청구가 이유 있을 때 행정심판위원회가 행정청에 처분을 하도록 명하는 재결이다.","r":[]},"구술심리":{"d":"행정심판에서 당사자가 말로 주장과 증거를 진술하게 하는 심리 방식이다.","r":[]},"당사자심판":{"d":"행정심판의 종류 중 처분등에 관한 당사자 사이의 다툼을 다루는 심판으로 행정심판법에 규정되어 있지 않다.","r":[]},"보상금증감청구소송":{"d":"수용재결에서 정한 보상금의 증액 또는 감액을 구하는 소송이다.","r":[]},"잔여지수용청구":{"d":"토지의 일부가 수용되어 남은 토지를 종래의 목적에 사용하기 곤란할 때 그 토지의 수용을 청구하는 것이다.","r":[]},"영업손실":{"d":"공익사업 때문에 영업을 폐지하거나 휴업하여 입는 손실이다.","r":[]},"이중배상":{"d":"군인 등이 직무 중 상해를 입은 경우 국가배상법상 배상과 별도 보상을 중복해서 받는 것으로 국가배상법이 금지한다.","r":[]},"기판력":{"d":"확정판결의 내용이 후소에서 당사자와 법원을 구속하는 효력이다.","r":[]},"설치·관리상의 하자":{"d":"영조물이 통상 갖추어야 할 안전성이 결여된 것으로 국가배상법 제5조의 배상책임 요건이다.","r":[]},"사용자 면책조항":{"d":"민법상 사용자가 피용자의 선임, 감독에 상당한 주의를 한 경우 배상책임을 면하는 규정이다.","r":[]},"주민감사청구":{"d":"주민이 지방자치단체의 사무처리가 법령에 위반되거나 공익을 현저히 해친다고 판단할 때 감사를 청구하는 제도이다.","r":[]},"주민투표":{"d":"지방자치단체의 주요 결정 사항에 대하여 주민이 투표로 결정하는 제도이다.","r":[]},"일사부재리":{"d":"동일한 사유에 대해 거듭 처분이나 처벌을 하지 않는다는 원칙이다.","r":[]},"공무원임용결격사유":{"d":"공무원으로 임용될 수 없는 사유로 이에 해당하는 자를 임용하면 당연무효이다.","r":[]},"특정직공무원":{"d":"법관, 검사, 외무공무원, 경찰공무원 등 담당 업무가 특수하여 특별법이 적용되는 공무원이다.","r":[]},"정무직공무원":{"d":"선거로 취임하거나 임명에 국회 동의가 필요한 공무원 등 정치적 성격의 공무원이다.","r":[]},"일반직공무원":{"d":"기술, 연구 또는 행정 일반에 대한 업무를 담당하는 공무원이다.","r":[]},"경력직공무원":{"d":"실적과 자격에 따라 임용되고 신분이 보장되는 공무원으로 일반직과 특정직이 있다.","r":[]},"강임":{"d":"같은 직렬 안에서 현재보다 낮은 직급으로 임명하는 것이다.","r":[]},"보존용재산":{"d":"법령이나 그 밖의 필요에 따라 국가가 보존하는 재산이다.","r":[]},"공용재산":{"d":"국가가 직접 사무용, 사업용 또는 공무원의 주거용으로 사용하는 행정재산이다.","r":[]},"기업용재산":{"d":"정부기업이 직접 사무용, 사업용 또는 주거용으로 사용하는 행정재산이다.","r":[]},"사용허가":{"d":"행정재산을 일정 기간 사용하거나 수익하는 것을 허용하는 처분이다.","r":[]},"공공용물":{"d":"도로, 공원처럼 일반 공중의 사용에 직접 제공된 공물이다.","r":[]},"공물":{"d":"국가나 지방자치단체가 직접 행정 목적에 제공한 유체물이다.","r":[]},"자유공물":{"d":"공물의 관리주체와 귀속주체가 같은 공물이다.","r":[]},"공용폐지":{"d":"공물이 공용에 제공되지 않도록 그 용도를 폐지하는 것이다.","r":[]},"시효취득":{"d":"타인의 물건을 일정 기간 점유하는 등으로 소유권을 취득하는 제도이다.","r":[]},"경찰책임":{"d":"경찰권 발동의 대상이 되는 자가 지는 책임으로 행위책임, 상태책임 등이 있다.","r":[]},"행위책임":{"d":"자기 또는 자기 보호 아래 있는 자의 행위로 위해가 생긴 경우 지는 경찰책임이다.","r":[]},"불심검문":{"d":"경찰관이 수상한 행동을 하는 사람을 정지시켜 질문하는 것이다.","r":[]},"예산총칙":{"d":"예산의 내용 중 세입세출예산 등의 총괄적인 규정을 둔 부분이다.","r":[]},"세입세출예산":{"d":"한 회계연도의 모든 수입과 지출을 계상한 예산이다.","r":[]},"회계연도":{"d":"수입과 지출의 계산 기준으로 삼는 일정한 기간이다.","r":[]},"과태료":{"d":"행정질서벌로서 행정법상 질서를 위반한 자에게 부과하는 금전적 제재로 형벌이 아니다.","r":[]},"이중처벌금지":{"d":"동일한 행위에 대해 거듭 처벌하지 못한다는 헌법상 원칙이다.","r":[]},"수리를 요하지 않는 신고":{"d":"신고서가 접수기관에 도달하면 신고의 효력이 발생하고 행정청의 수리를 필요로 하지 않는 신고이다.","r":[]}},"notes":{"14세가 되지 아니한 자의 질서위반행위는 다른 법률에 특별한 규정이 있는 경우를 제외하고는 과태료를 부과하지 아니한다.":"14세가 되지 않은 사람은 책임능력이 부족하므로 특별한 규정이 없는 한 과태료를 부과하지 않습니다.","18세 이상의 주민이 시·도는 300명, 인구 50만 이상 대도시는 200명, 그 밖의 시·군 및 자치구는 150명 이내에서 조례로 정하는 수 이상 연대 서명하여 사무처리가 법령에 위반되거나 공익을 현저히 해친다고 인정되면 시·도는 주무부장관에게, 시·군 및 자치구는 시·도지사에게 감사를 청구할 수 있다.":"18세 이상 주민이 지역별 일정 수 이상 연대 서명하면 시도는 주무부장관에게 시군구는 시도지사에게 감사를 청구할 수 있습니다.","2인 이상이 질서위반행위에 가담한 때에는 각자가 질서위반행위를 한 것으로 본다. 신분에 의하여 성립하는 질서위반행위에 신분이 없는 자가 가담한 때에도 신분이 없는 자에 대하여 질서위반행위가 성립한다. 신분에 의하여 과태료를 감경·가중하거나 부과하지 않는 경우 그 신분의 효과는 신분이 없는 자에게 미치지 않는다.":"여럿이 가담하면 각자 위반한 것으로 보고 신분 없는 자도 위반이 성립하나 신분에 따른 감경과 가중은 신분 없는 자에게 미치지 않습니다.","「건축법」 제14조 제1항에 따른 건축신고.":"일반적인 건축신고는 신고서가 닿으면 효력이 생기는 수리를 요하지 않는 신고의 예입니다.","「국가를 당사자로 하는 계약에 관한 법률」에 따라 국가가 당사자가 되는 공공계약은 사법상 계약이다. 공법상 계약이 아니다.":"국가가 당사자인 공공계약은 사인 사이의 계약과 같은 성질이라서 사법상 계약으로 분류됩니다.","「주택법」상 입주자는 건축물의 하자를 이유로 그 건축물에 대한 사용검사처분의 취소를 구할 법률상 이익이 없다.":"입주자는 건축물 하자를 이유로 사용검사처분의 취소를 구할 법률상 이익이 인정되지 않습니다.","「하천법」상 하천부지 점용허가는 재량행위이므로 부관을 붙일 수 있다.":"하천부지 점용허가는 행정청에 재량이 있는 행위여서 부관을 붙이는 것이 허용됩니다.","가해행위인 처분에 대해 취소판결이 확정되더라도 기판력에 의해 국가배상책임이 인정되는 것은 아니다. 처분이 항고소송에서 취소되었다고 공무원의 고의·과실 여부와 관계없이 곧바로 불법행위를 구성하지 않는다.":"처분이 취소되었다고 국가배상이 자동으로 인정되지 않고 공무원의 고의나 과실 등 별도의 요건을 따로 증명해야 합니다.","각 중앙관서의 장은 세출예산이 정한 목적 외에 경비를 사용할 수 없다. 세항·목 사이의 전용은 기획예산처장관의 승인을 얻어야 한다.":"세출예산에서 정한 목적 밖으로는 경비를 쓸 수 없고 세항과 목 사이의 전용은 기획예산처장관의 승인을 받아야 합니다.","간접강제 결정서 정본은 소송제기와 관계없이 「민사집행법」에 따른 강제집행에서 집행권원과 같은 효력을 가진다. 간접강제 결정에 기초한 강제집행에 관하여 특별한 규정이 없는 사항은 「민사집행법」을 준용한다.":"간접강제 결정서 정본은 소송을 내도 민사집행법상 강제집행의 집행권원과 같은 효력이 있어 바로 집행할 수 있습니다.","감사·감독·검사·시험·규제·입찰계약·기술개발·인사관리에 관한 사항이나 의사결정 과정 또는 내부검토 과정에 있는 사항 등으로서 공개될 경우 업무의 공정한 수행이나 연구·개발에 현저한 지장을 초래한다고 인정할 만한 상당한 이유가 있는 정보.":"감사와 입찰과 인사 관련 사항이나 내부 검토 중인 사항으로 공개 시 업무 수행에 현저한 지장이 있으면 비공개합니다.","감사 결과에 따라 기간을 정하여 해당 지방자치단체의 장에게 필요한 조치를 요구할 수 있다.":"감사 결과 문제가 확인되면 기간을 정해 해당 단체장에게 필요한 조치를 하라고 요구할 수 있습니다.","감사원, 국가정보원장, 국회사무총장·법원행정처장·헌법재판소사무처장·중앙선거관리위원회사무총장, 국가인권위원회 등 독립성이 인정되는 행정청의 처분에 대한 심판청구는 그 행정청에 두는 행정심판위원회에서 심리·재결한다.":"독립성이 인정되는 행정청의 처분은 중앙이나 시도 위원회가 아니라 그 행정청 안의 행정심판위원회가 심리하고 재결합니다.","감사원이 감사위원회의의 결정을 거쳐 행하는 사항.":"감사원이 감사위원회의 결정을 거쳐 하는 사항은 이미 합의 절차가 있어 행정절차법에서 제외됩니다.","감사청구는 사무처리가 있었던 날이나 끝난 날부터 3년이 지나면 제기할 수 없다.":"사무처리가 있었던 날이나 끝난 날로부터 3년이 지난 뒤의 청구는 받아 주지 않습니다.","감사 청구를 수리한 날부터 60일이 지나도 감사를 끝내지 아니한 경우, 감사 결과 또는 조치 요구에 불복하는 경우, 조치 요구를 지방자치단체의 장이 이행하지 아니한 경우, 지방자치단체의 장의 이행 조치에 불복하는 경우.":"감사가 60일 안에 끝나지 않거나 결과와 조치 요구에 불복하거나 단체장이 이행하지 않거나 이행에 불복하면 주민소송을 낼 수 있습니다.","강등: 1계급 아래로 직급을 내리고 신분은 보유하나 3개월간 직무에 종사하지 못하며 그 기간 중 보수는 전액을 감한다. 정직: 1개월 이상 3개월 이하이며 보수는 전액을 감한다. 감봉: 1개월 이상 3개월 이하이며 보수의 3분의 1을 감한다. 견책: 전과에 대하여 훈계하고 회개하게 한다.":"강등은 직급을 한 계급 내리고 3개월간 직무를 정지하며 정직은 보수 전액을, 감봉은 보수의 3분의 1을 줄이고 견책은 훈계입니다.","강행법규에 의한 의무 부과, 사익보호성(법률상 이익), 청구(의사)력.":"개인적 공권이 생기려면 행정에 의무를 지우는 강행법규와 사익 보호 목적과 청구할 수 있는 힘이 모두 필요합니다.","같은 행정목적을 실현하기 위하여 많은 상대방에게 행정지도를 하려는 경우에는 특별한 사정이 없으면 행정지도에 공통적인 내용이 되는 사항을 공표하여야 한다.":"같은 목적으로 많은 사람에게 행정지도를 하려면 특별한 사정이 없는 한 공통되는 내용을 미리 공표해야 합니다.","개인정보를 익명 또는 가명으로 처리하여도 수집목적을 달성할 수 있는 경우, 익명처리가 가능하면 익명으로, 익명으로 목적을 달성할 수 없으면 가명으로 처리될 수 있도록 하여야 한다.":"익명이나 가명으로도 수집 목적을 이룰 수 있으면 익명을 우선하고 안 되면 가명으로 처리하도록 해야 합니다.","개인정보 유출등을 알게 되었을 때 지체 없이 정보주체에게 유출된 항목, 시점과 경위, 피해 최소화 방법, 대응조치 및 피해 구제절차, 신고 접수 담당부서 및 연락처 등을 알려야 하며, 보호위원회 또는 전문기관에 신고하여야 한다.":"유출을 알면 곧바로 정보주체에게 유출 항목과 경위와 대응 방법과 연락처를 알리고 보호위원회나 전문기관에 신고해야 합니다.","개인정보의 일부를 삭제하거나 일부 또는 전부를 대체하는 등의 방법으로 추가 정보가 없이는 특정 개인을 알아볼 수 없도록 처리하는 것.":"가명처리는 이름 같은 일부를 지우거나 바꿔서 추가 정보 없이는 특정인을 알 수 없게 만드는 것입니다.","개인정보 처리 업무를 위탁하는 경우 위탁업무 수행 목적 외 처리 금지, 기술적·관리적 보호조치 등을 포함한 문서로 하여야 하며, 위탁자는 수탁자를 교육하고 감독하여야 한다. 수탁자가 재위탁하려면 위탁자의 동의를 받아야 한다.":"처리 업무를 맡길 때는 목적 외 처리 금지와 보호조치를 담은 문서로 하고 위탁자가 수탁자를 교육하고 감독하며 재위탁은 동의가 필요합니다.","개인정보처리자는 개인정보의 처리 목적을 명확하게 하고 그 목적에 필요한 범위에서 최소한의 개인정보만을 적법하고 정당하게 수집하여야 한다. 처리 목적에 필요한 범위에서 적합하게 개인정보를 처리하여야 하며, 그 목적 외의 용도로 활용하여서는 아니 된다. 처리 목적에 필요한 범위에서 개인정보의 정확성, 완전성 및 최신성이 보장되도록 하여야 한다. 처리방법 및 종류 등에 따라 정보주체의 권리가 침해받을 가능성과 위험 정도를 고려하여 개인정보를 안전하게 관리하여야 한다. 개인정보 처리방침 등 처리에 관한 사항을 공개하여야 하며, 열람청구권 등 정보주체의 권리를 보장하여야 한다. 정보주체의 사생활 침해를 최소화하는 방법으로 개인정보를 처리하여야 한다.":"처리자는 목적을 밝히고 필요한 최소한만 수집하며 목적 외 사용을 하지 않고 정확성과 안전을 지키고 방침을 공개합니다.","개인정보처리자의 가명정보 처리에 동의할 권리는 정보주체의 권리로 규정되어 있지 않다.":"가명정보는 동의 없이 처리할 수 있어서 법이 정한 정보주체의 권리 목록에는 가명정보 동의권이 없습니다.","거부처분 무효확인소송을 제기한 경우 무효인 사유를 주장·증명할 책임은 원고에게 있다. 취소소송의 사정판결 규정은 준용되지 않는다.":"무효확인소송에서는 무효 사유를 원고가 주장하고 증명해야 하며 취소소송의 사정판결 규정은 준용되지 않습니다.","거부처분에 대하여는 집행정지를 구할 이익이 없어 집행정지가 허용되지 않는다.":"거부처분의 집행을 정지해도 신청한 처분을 해 주게 되는 것이 아니라서 집행정지를 구할 이익이 없습니다.","거부처분은 당사자의 권익을 제한하는 처분이 아니므로 행정절차법상 사전통지의 대상이 아니다.":"거부는 이미 가진 권익을 줄이는 것이 아니라서 사전통지 대상이 아닙니다.","거부처분이 성립하려면 신청인에게 그 행위발동을 요구할 수 있는 법규상 또는 조리상 신청권이 있어야 한다.":"신청권이 있는 사람이 한 신청을 거부한 경우에 비로소 거부처분이 성립하므로 법규상이나 조리상의 신청권이 필요합니다.","거부처분취소판결에 따른 재처분을 하지 않으면 제1심 수소법원은 당사자의 신청에 의하여 상당한 기간을 정하고, 그 기간 내에 이행하지 않으면 지연기간에 따라 일정한 배상을 할 것을 명하거나 즉시 손해배상을 할 것을 명할 수 있다(간접강제).":"재처분을 하지 않으면 법원이 기한을 정하고 지연 기간에 따른 배상이나 즉시 배상을 명해 이행을 압박하는 간접강제입니다.","거부처분취소판결의 취지에 따라 행정청이 처분을 하지 않는 경우 당사자는 제1심 수소법원에 간접강제를 신청할 수 있다. 직접강제를 신청할 수 없다.":"취소판결 후에도 행정청이 처분하지 않으면 제1심 수소법원에 간접강제를 신청하며 법원이 직접 처분하게 할 수는 없습니다.","거짓·부정한 방법, 무단 전대, 보존 게을리·사용목적 위배, 사용료 미납, 승인 없이 원래 상태 변경.":"거짓이나 부정한 방법으로 허가받았거나 무단 전대하거나 사용 목적을 어기거나 사용료를 내지 않으면 허가를 취소하거나 철회할 수 있습니다.","거짓이나 그 밖의 부정한 방법으로 인허가를 받거나 신고한 경우, 당사자가 위법성을 알았거나 중대한 과실로 알지 못한 경우, 정당한 사유 없이 조사·출입·검사를 기피·방해·거부하여 기간이 지난 경우, 제재처분을 하지 아니하면 국민의 안전·생명 또는 환경을 심각하게 해치거나 해칠 우려가 있는 경우.":"속임수나 조사 방해나 안전 위협처럼 비난 가능성이 큰 사유는 제척기간이 지나도 제재할 수 있습니다.","거짓이나 그 밖의 부정한 방법으로 처분을 받은 경우, 당사자가 처분의 위법성을 알고 있었거나 중대한 과실로 알지 못한 경우.":"당사자가 속임수로 처분을 받았거나 위법을 알았거나 중대한 과실로 몰랐다면 신뢰 보호가 약해 이익형량 없이 취소할 수 있습니다.","건축물등은 이전에 필요한 비용(이전비)으로 보상한다. 이전이 어렵거나 종래 목적대로 사용할 수 없게 된 경우, 이전비가 물건 가격을 넘는 경우, 사업시행자가 공익사업에 직접 사용할 목적으로 취득하는 경우에는 물건의 가격으로 보상한다.":"건물은 옮기는 비용으로 보상하되 이전이 어렵거나 이전비가 물건 값을 넘거나 직접 사용할 목적이면 물건 가격으로 보상합니다.","건축법상 이행강제금의 납부의무는 상속인에게 승계될 수 없는 일신전속적인 성질의 것이다.":"이행강제금은 의무자 본인에게 이행을 압박하는 것이라 일신전속적이어서 상속인에게 납부의무가 넘어가지 않습니다.","건축법시행규칙(부령), 서울특별시 성동구 조례(자치법규), 헌법재판소규칙, 대한민국헌법은 모두 행정법의 법원이다.":"부령, 자치법규, 헌법재판소규칙, 헌법은 모두 성문법원이라 행정법의 재판 기준이 됩니다.","건축신고 반려행위는 항고소송의 대상이 되는 처분이다.":"건축신고를 받아 주지 않고 돌려보내는 반려는 국민의 법적 지위에 영향을 주어 처분으로 다툴 수 있습니다.","게을리한 사실의 위법 확인을 요구하는 소송. 공금의 부과·징수 업무를 게을리한 사실의 위법 확인을 요구하는 주민소송은 인정된다.":"업무를 게을리한 사실이 위법하다는 확인을 구하는 유형이며 부과와 징수를 게을리한 경우에도 인정됩니다.","결산과 관련한 검사위원 선임, 지방의회의원 자격상실에 대한 의결(재적의원 3분의 2 이상 찬성), 기금의 설치·운용에 관한 의결, 청원의 수리와 처리에 관한 의결.":"지방의회는 결산 검사위원 선임과 의원 자격상실 의결과 기금과 청원에 관한 의결 권한을 가집니다.","경비의 성질상 연도 내에 지출을 끝내지 못할 것이 예측되는 경우 그 취지를 명시하여 국회의 승인을 얻은 후 다음 연도로 이월한다.":"한 해 안에 쓰지 못할 것이 예측되는 경비는 그 취지를 명시하고 국회 승인을 받아 다음 연도로 넘기는 것이 명시이월비입니다.","경찰견은 동산공물(인공공물, 공용물)에 해당한다.":"경찰견은 움직일 수 있는 동산이면서 사람이 만든 공용물에 속하는 공물로 분류됩니다.","경찰관서의 장은 직무 수행에 필요한 상당한 이유가 있을 때 국가기관이나 공사 단체 등에 사실을 조회할 수 있다. 경찰관은 출석 요구서를 보내 경찰관서에 출석할 것을 요구할 수 있다.":"경찰관서의 장은 상당한 이유가 있으면 기관과 단체에 사실을 조회할 수 있고 출석 요구서를 보내 출석을 요구할 수도 있습니다.","경찰관은 질문을 할 때 그 사람이 흉기를 가지고 있는지를 조사할 수 있다.":"경찰관은 질문하면서 안전을 위해 상대방이 흉기를 소지했는지 조사할 수 있습니다.","경찰관의 적법한 직무집행으로 손실을 입은 자는 손실발생의 원인에 대하여 책임이 없는 경우 정당한 보상을 받고, 책임이 있는 자는 자신의 책임에 상응하는 정도를 초과하는 손실에 대해서만 보상을 받는다.":"적법한 경찰 직무로 손실을 입은 사람은 책임이 없으면 정당한 보상을 받고 책임이 있으면 자기 책임을 넘는 부분만 보상받습니다.","경찰관의 직권은 직무 수행에 필요한 최소한도에서 행사되어야 하며 남용되어서는 아니 된다.":"경찰관은 직무 수행에 필요한 최소한의 범위에서만 직권을 행사해야 하고 이를 남용해서는 안 됩니다.","경찰관이 범죄수사를 함에 있어 법규상 또는 조리상의 한계를 위반하였다면 이는 법령을 위반한 경우에 해당한다.":"법령 위반에는 명문 규정 위반뿐 아니라 법규나 조리상의 한계를 넘는 경우도 포함됩니다.","경찰책임자에 대한 경찰권의 발동이 어려운 경우에는 예외적으로 경찰책임이 없는 자에게도 경찰권이 발동될 수 있다(긴급 경찰권).":"책임자에게 경찰권을 쓰기 어려운 급박한 상황에서는 예외적으로 책임 없는 제삼자에게도 발동할 수 있는 긴급 경찰권입니다.","계고에서 정한 기한까지 이행하지 않은 경우 이행강제금의 부과 금액·사유·시기를 문서로 명확하게 적어 통지하여야 한다.":"계고 기한이 지나도 이행하지 않으면 부과 금액과 사유와 시기를 문서에 분명히 적어 통지해야 합니다.","계고처분의 후속절차인 대집행에 위법이 있더라도 그 후속절차의 위법을 이유로 선행절차인 계고처분이 부적법하다고 할 수 없다. 후행처분인 대집행영장발부통보처분의 취소소송에서 선행처분인 계고처분의 위법을 이유로 대집행영장발부통보처분이 위법하다는 주장을 할 수 있다(하자의 승계).":"뒤 절차의 위법이 앞 계고를 위법하게 만들지는 않지만 앞 계고의 위법은 뒤 영장통보 처분의 소송에서 주장할 수 있습니다.","계고 후에도 이행하지 않으면 대집행영장으로 대집행을 할 시기, 집행책임자의 성명, 대집행에 요하는 비용의 개산에 의한 견적액을 의무자에게 통지한다.":"계고 뒤에도 이행하지 않으면 대집행 시기와 집행책임자와 예상 비용을 적은 영장으로 의무자에게 통지합니다.","계약직공무원에 대한 채용계약해지를 함에 있어서는 「행정절차법」에 의하여 그 근거와 이유를 제시할 필요가 없다.":"계약직공무원의 채용계약 해지는 행정절차법이 요구하는 근거와 이유 제시의 대상이 아닙니다.","고시가 다른 집행행위 없이 그 자체로 국민의 구체적인 권리의무를 규율하는 성격이면 처분이다. 보건복지부 고시인 약제급여·비급여목록 및 급여상한금액표는 취소소송으로 다툴 수 있다.":"고시가 집행행위 없이 곧바로 구체적 권리의무를 정하면 처분이어서 약제 상한금액표도 취소소송으로 다툴 수 있습니다.","고시가 다른 집행행위의 매개 없이 그 자체로서 직접 국민의 구체적인 권리의무나 법률관계를 규율하는 성격을 가질 때에는 항고소송의 대상이 되는 행정처분이다.":"고시가 별도의 집행행위 없이 곧바로 국민의 권리와 의무를 정한다면 행정처분으로서 소송 대상이 됩니다.","고의 또는 과실이 없는 질서위반행위는 과태료를 부과하지 아니한다.":"과태료도 책임이 있어야 부과하므로 고의나 과실이 없는 위반행위에는 부과하지 않습니다.","고정형 영상정보처리기기운영자는 설치 목적 및 장소, 촬영 범위 및 시간, 관리책임자 연락처 등이 포함된 안내판을 설치하여야 하고, 설치 목적과 다른 목적으로 임의 조작하거나 다른 곳을 비춰서는 아니 되며, 녹음기능은 사용할 수 없다.":"운영자는 설치 목적과 촬영 범위와 연락처를 안내판으로 알려야 하고 목적 외 조작이나 녹음은 할 수 없습니다.","공개된 장소에 설치·운영할 수 있는 경우: 법령에서 구체적으로 허용하고 있는 경우, 범죄의 예방 및 수사를 위하여 필요한 경우, 시설의 안전 및 관리·화재 예방을 위하여 정당한 권한을 가진 자가 설치·운영하는 경우, 교통단속을 위하여 정당한 권한을 가진 자가 설치·운영하는 경우, 교통정보의 수집·분석 및 제공을 위하여 정당한 권한을 가진 자가 설치·운영하는 경우, 촬영된 영상정보를 저장하지 아니하는 경우로서 대통령령으로 정하는 경우(출입자 수·성별·연령대 등 통계값 산출을 위한 일시 처리 등).":"공개된 장소의 고정형 카메라는 법령 허용이나 범죄 예방, 시설 안전, 교통단속처럼 정당한 목적일 때만 설치할 수 있습니다.","공개될 경우 국민의 생명·신체 및 재산의 보호에 현저한 지장을 초래할 우려가 있다고 인정되는 정보.":"공개되면 국민의 생명과 신체와 재산을 보호하는 데 큰 지장을 줄 우려가 있는 정보는 비공개 대상입니다.","공개될 경우 부동산 투기, 매점매석 등으로 특정인에게 이익 또는 불이익을 줄 우려가 있다고 인정되는 정보.":"공개되면 부동산 투기나 매점매석으로 특정인이 이득을 보거나 손해를 입을 우려가 있는 정보는 비공개입니다.","공개 청구된 정보의 전부 또는 일부가 제3자와 관련이 있다고 인정할 때 공공기관은 그 사실을 제3자에게 지체 없이 통지하여야 하며, 필요한 경우 의견을 들을 수 있다.":"청구된 정보가 제삼자와 관련되면 공공기관은 그 사실을 곧바로 제삼자에게 알리고 필요하면 의견을 들을 수 있습니다.","공개 청구한 정보가 비공개 대상 부분과 공개 가능한 부분이 혼합되어 있고 청구 취지에 어긋나지 않는 범위에서 분리할 수 있으면 비공개 부분을 제외하고 공개하여야 한다(부분 공개).":"정보에 비공개 부분과 공개 가능한 부분이 섞여 있고 분리할 수 있으면 비공개 부분만 빼고 나머지를 공개합니다.","공공기관은 공개를 결정한 경우 공개의 일시 및 장소 등을 밝혀 통지하고, 청구인이 사본 또는 복제물의 교부를 원하는 때에는 이를 교부하여야 한다.":"공개하기로 하면 일시와 장소 등을 알리고 청구인이 사본이나 복제물을 원하면 내줘야 합니다.","공공기관은 국가기관등에 정보공개심의회를 설치·운영하며, 심의회는 위원장 1명을 포함하여 5명 이상 7명 이하의 위원으로 구성하고 위원 중 3분의 2는 외부 전문가로 위촉한다.":"정보공개심의회는 5명 이상 7명 이하로 구성하며 3분의 2를 외부 전문가로 채워 공개 여부를 객관적으로 심의합니다.","공공기관은 이의신청을 받은 날부터 7일 이내에 결정하고 결과를 지체 없이 문서로 통지하여야 한다. 부득이한 사유가 있으면 7일의 범위에서 연장할 수 있다.":"이의신청에 대해 7일 안에 결정하여 서면으로 알려야 하고 부득이하면 7일 범위에서 연장할 수 있습니다.","공공기관은 정보공개 청구를 받은 날부터 10일 이내에 공개 여부를 결정하여야 한다. 부득이한 사유가 있으면 기간이 끝나는 날의 다음 날부터 기산하여 10일의 범위에서 연장할 수 있고, 연장 사실과 사유를 청구인에게 지체 없이 문서로 통지한다.":"청구를 받은 날부터 10일 안에 공개 여부를 정하고 부득이하면 10일 범위에서 연장하며 사실과 사유를 문서로 알립니다.","공공기관의 장이 고정형 영상정보처리기기를 설치·운영하려면 공청회·설명회의 개최 등 대통령령으로 정하는 절차를 거쳐 관계 전문가 및 이해관계인의 의견을 수렴하여야 한다.":"공공기관이 고정형 카메라를 설치하려면 공청회나 설명회로 전문가와 이해관계인의 의견을 먼저 들어야 합니다.","공공기관이 정보공개를 요구받고 공개를 거부하는 경우에는 비공개사유에 해당하는지를 주장·입증하지 아니한 채 개괄적인 사유만을 들어 공개를 거부할 수 없다.":"공개를 거부하려면 구체적으로 어느 비공개 사유에 해당하는지 주장하고 입증해야 하며 막연한 이유만으로는 안 됩니다.","공공기관이 직무상 작성 또는 취득하여 관리하고 있는 문서(전자문서 포함) 및 전자매체를 비롯한 모든 형태의 매체 등에 기록된 사항. 공개 청구의 대상은 공공기관이 보유·관리하고 있는 정보에 한정된다.":"정보는 공공기관이 직무상 만들거나 받아 관리하는 모든 형태의 기록이며 공개 청구는 그 보유 정보만 대상입니다.","공공용물: 일반공중의 공동사용에 직접 제공된 공물. 공용물: 행정주체 자신의 사용에 제공된 공물. 보존공물: 공적 목적을 위해 보존되는 공물.":"공공용물은 일반 공중이 함께 쓰는 공물이고 공용물은 행정주체가 직접 쓰는 공물이며 보존공물은 공적 목적으로 보존하는 공물입니다.","공공용물의 일반사용은 원칙적으로 무료다. 사용료를 납부하지 않는다.":"공공용물을 누구나 평등하게 쓰는 일반사용은 원칙적으로 대가 없이 누리므로 사용료를 내지 않습니다.","공공의 안전 또는 복리를 위하여 긴급히 처분을 할 필요가 있는 경우, 법령등에서 요구된 자격이 없거나 없어지게 되면 반드시 일정한 처분을 하여야 하는 경우에 그 사실이 법원의 재판 등에 의하여 객관적으로 증명된 경우, 처분의 성질상 의견청취가 현저히 곤란하거나 명백히 불필요하다고 인정될 만한 상당한 이유가 있는 경우.":"긴급한 경우, 자격 상실 사실이 재판 등으로 증명된 경우, 의견청취가 곤란하거나 불필요한 경우에는 사전통지를 생략합니다.","공공의 영조물에는 행정주체가 적법한 권한에 기하여 관리하고 있는 공물뿐 아니라 사실상 관리하고 있는 공물도 포함된다.":"공공 영조물은 법적 권한으로 관리하는 시설뿐 아니라 사실상 관리하고 있는 시설도 포함합니다.","공공필요에 의한 재산권의 수용·사용 또는 제한 및 그에 대한 보상은 법률로써 하되, 정당한 보상을 지급하여야 한다. 정당한 보상은 완전보상을 의미한다(판례).":"공공필요로 재산권을 수용하거나 제한할 때는 법률에 근거하고 완전보상에 해당하는 정당한 보상을 해야 합니다.","공금의 지출, 재산의 취득·관리·처분, 계약의 체결·이행, 지방세·사용료·수수료·과태료 등 공금의 부과·징수를 게을리한 사항에 관해 주민감사청구를 한 주민이 제기할 수 있다. 주민소송을 제기하기 전에 주민감사청구를 거쳐야 한다.":"공금 지출과 재산과 계약과 부과 징수 해태에 관해 감사청구를 한 주민만 소송할 수 있어 감사청구를 먼저 거쳐야 합니다.","공무를 위탁받은 사인의 직무집행행위에 대해서도 국가배상책임이 성립할 수 있다.":"공무원이 아니어도 공무를 위탁받아 수행하는 사인이 손해를 입히면 국가배상책임이 성립할 수 있습니다.","공무원에 대하여 징계처분 등을 할 때나 강임·휴직·직위해제 또는 면직처분을 할 때에는 처분사유를 적은 설명서를 교부하여야 한다. 본인의 원에 따른 강임·휴직 또는 면직처분은 설명서를 교부하지 않아도 된다.":"징계나 직위해제나 면직을 할 때는 처분 사유를 적은 설명서를 줘야 하고 본인이 원해서 하는 강임과 휴직과 면직은 주지 않아도 됩니다.","공무원의 선임·감독 또는 영조물의 설치·관리를 맡은 자와 비용을 부담하는 자가 다르면 비용부담자도 배상책임을 진다. 손해를 배상한 자는 내부관계에서 책임 있는 자에게 구상할 수 있다.":"선임과 감독을 맡은 자와 비용을 부담하는 자가 다르면 둘 다 배상책임이 있고 배상한 쪽은 책임 있는 쪽에 구상합니다.","공무원의 신분과 지위의 특수성상 공무원에 대해서는 일반 국민에 비해 보다 넓고 강한 기본권 제한이 가능하다.":"공무원은 신분과 지위가 특수해서 일반 국민보다 더 넓고 강하게 기본권을 제한할 수 있습니다.","공무원의 정년은 60세다. 정년에 이른 날이 1월부터 6월 사이에 있으면 6월 30일에, 7월부터 12월 사이에 있으면 12월 31일에 각각 당연히 퇴직된다.":"정년은 60세이며 정년이 되는 날이 상반기면 6월 30일에 하반기면 12월 31일에 당연히 퇴직합니다.","공무원이 대외적 구속력이 없는 훈령에 위반한 경우에도 그 행위가 위법하게 되는 것은 아니며, 징계책임이 부과될 수 있을 뿐이다.":"훈령은 대외적 구속력이 없어 위반해도 행위가 위법해지지는 않고 공무원 내부의 징계 문제만 생길 수 있습니다.","공무원이 직무 수행에서 소속 상관의 명백한 위법 내지 불법한 명령에 따라야 할 의무는 없다.":"상관의 명령이라도 명백히 위법하거나 불법이라면 공무원은 그에 복종할 의무가 없습니다.","공무원 인사 관계 법령에 따른 징계 등 처분, 국가인권위원회의 진정 결정, 노동위원회의 의결 사항, 형사·행형·보안처분, 외국인의 출입국·난민인정·귀화·국적회복, 과태료 부과 및 징수.":"징계, 인권위 진정 결정, 노동위 의결, 형사 관련 처분, 출입국 관련 처분, 과태료는 이의신청 제도 적용에서 빠집니다.","공무원임용결격사유가 있는지의 여부는 임용 당시의 법률을 기준으로 판단한다.":"결격사유가 있는지는 나중에 바뀐 법이 아니라 임용 당시의 법률을 기준으로 판단합니다.","공물의 인접주민에게 고양된 일반사용권이 인정되려면 공물을 실제로 사용하는 등의 요건이 필요하고, 구체적으로 사용하지 않는 경우에는 인정되지 않는다.":"인접 주민의 고양된 일반사용권은 실제로 그 공물을 쓰는 사정이 있어야 하므로 구체적으로 사용하지 않으면 인정되지 않습니다.","공법관계에서 법률상 원인 없이 이득을 얻은 경우 인정되며, 원칙적으로 공법상 당사자소송으로 다툰다.":"공법 관계에서 정당한 이유 없이 이익을 얻은 경우 돌려받는 청구는 공법상 당사자소송으로 합니다.","공법상 계약에는 법률우위의 원칙이 적용된다.":"공법상 계약도 법률에 어긋나게 맺을 수 없으며 법률이 정한 내용이 계약보다 앞섭니다.","공법상 계약에 따른 권리·의무의 확인 소송은 공법상 당사자소송에 의한다.":"공법상 계약에서 생긴 권리와 의무의 확인은 처분에 대한 소송이 아니라 공법상 당사자소송으로 다툽니다.","공법상 당사자소송으로 다투는 것: 서울시립무용단 단원의 해촉, 공익사업으로 이주하는 세입자의 주거이전비 보상 소송, 공법상 근무관계에 관한 소송.":"시립무용단 해촉과 세입자 주거이전비 보상과 공법상 근무관계는 처분이 아닌 공법상 법률관계라서 당사자소송으로 다툽니다.","공유수면매립면허: 특허. 보세구역의 설영특허: 특허.":"바다를 메우는 면허와 보세구역을 운영하는 특허는 새 권리를 설정해 주는 특허에 속합니다.","공익사업시행지구 밖에 있는 토지등이 공익사업의 시행으로 본래의 기능을 다할 수 없게 되는 경우에도 일정한 요건 하에 그 손실(영업손실 등)을 보상받을 수 있다.":"사업지구 밖의 토지라도 사업 시행으로 본래 기능을 못 하게 되면 일정한 요건이 있을 때 손실을 보상받을 수 있습니다.","공익사업으로 이주하게 된 주거용 건축물 세입자의 주거이전비 보상을 둘러싼 소송은 공법관계(공법상 당사자소송)다.":"공익사업으로 이주하는 세입자의 주거이전비 보상은 공법상 권리여서 공법상 당사자소송 대상입니다.","공익사업으로 인한 손실은 사업시행자가 보상하여야 한다. 사업시행자는 공사에 착수하기 이전에 토지소유자와 관계인에게 보상액 전액을 지급하여야 한다(사전보상).":"공사에 들어가기 전에 보상액 전액을 지급하는 것이 원칙인 사전보상으로 소유자의 생활 기반을 먼저 보호합니다.","공청회 개최 14일 전까지 제목, 일시 및 장소, 주요 내용, 발표자에 관한 사항, 발표신청 방법 및 신청기한, 정보통신망을 통한 의견제출, 그 밖에 필요한 사항을 당사자등에게 통지하고 관보·공보·인터넷 홈페이지·일간신문 등에 공고하여야 한다. 예정대로 개최하지 못해 새로 정한 경우에는 7일 전까지 알려야 한다.":"공청회는 14일 전까지 제목과 일시와 장소 등을 통지하고 공고하며 연기해 새로 정한 경우에는 7일 전까지 알려야 합니다.","공청회의 주재자는 공정하게 진행하여야 하며, 발표자는 공청회의 내용과 직접 관련된 사항에 대하여만 발표한다. 발표자 상호간 질의·답변을 할 수 있게 하고 방청인에게도 의견을 제시할 기회를 주어야 한다.":"주재자가 공정하게 진행하고 발표자는 직접 관련된 내용만 발표하며 발표자끼리 질의답변을 하고 방청인도 의견을 낼 수 있습니다.","공포한 날부터 일정 기간이 경과한 날부터 시행하는 경우 공포한 날을 첫날에 산입하지 아니한다.":"공포 후 일정 기간이 지난 날부터 시행하는 법령은 공포한 날을 빼고 기간을 셉니다.","과징금 부과처분에서 법령상 감경사유가 있는 경우 이를 전혀 고려하지 않으면 위법하다.":"법령에 감경 사유가 있는데 전혀 따져 보지 않고 과징금을 매겼다면 처분이 위법합니다.","과징금은 국가의 형벌권을 실행하는 과벌이 아니다.":"과징금은 행정상 제재일 뿐 국가가 형벌권을 행사하는 처벌이 아니라서 형사 절차와 구분됩니다.","과징금은 한꺼번에 납부하는 것이 원칙이다. 재해 등으로 재산에 현저한 손실을 입은 경우, 사업 여건 악화로 사업이 중대한 위기에 처한 경우, 한꺼번에 내면 자금 사정에 현저한 어려움이 예상되는 경우, 그 밖에 이에 준하는 경우 납부기한을 연기하거나 분할 납부하게 할 수 있고, 필요하면 담보를 제공하게 할 수 있다.":"과징금은 일시 납부가 원칙이나 재해나 경영 위기처럼 어려운 사정이 있으면 기한 연기와 분할 납부가 가능합니다.","과태료는 부과처분이나 재판이 확정된 후 5년간 징수하지 아니하거나 집행하지 아니하면 시효로 소멸한다.":"과태료는 확정 후 5년 동안 징수하거나 집행하지 않으면 시효로 소멸해 더는 받을 수 없습니다.","과태료를 부과하려는 때에는 미리 당사자에게 통지하고, 10일 이상의 기간을 정하여 의견을 제출할 기회를 주어야 한다. 기일까지 의견 제출이 없으면 의견이 없는 것으로 본다.":"과태료를 매기기 전에 당사자에게 알리고 10일 이상 의견을 낼 기간을 주며 기한까지 없으면 의견이 없는 것으로 봅니다.","과태료 사건은 당사자의 주소지의 지방법원 또는 그 지원의 관할로 한다.":"과태료 재판은 당사자 주소지를 관할하는 지방법원이나 그 지원에서 맡습니다.","과태료 재판은 검사의 명령으로써 집행한다.":"과태료 재판은 법원이 아닌 검사의 명령으로 집행한다는 점이 특징입니다.","과태료 처분이나 재판이 확정된 후 법률이 변경되어 질서위반행위에 해당하지 아니하게 된 때에는 특별한 규정이 없는 한 과태료의 징수 또는 집행을 면제한다.":"처분이 확정된 뒤 법이 바뀌어 더는 위반이 아니게 되면 특별 규정이 없는 한 과태료를 거두거나 집행하지 않습니다.","관련 인허가에 필요한 심의, 의견 청취 등 절차는 법률에 인허가의제 시에도 해당 절차를 거친다는 명시적 규정이 있는 경우에만 거친다.":"관련 인허가의 심의나 의견 청취 절차는 의제의 경우에도 법률이 명시했을 때만 밟습니다.","관련 인허가 행정청은 관련 인허가의 처분기준을 주된 인허가 행정청에 제출하고, 주된 인허가 행정청은 통합하여 공표한다.":"관련 인허가의 처분기준은 주된 행정청에 모아 통합 공표하게 해 국민이 한곳에서 기준을 알 수 있게 합니다.","관련 인허가 행정청은 협의를 요청받은 날부터 20일 이내에 의견을 제출하여야 한다. 그 기간 내에 의견을 제출하지 아니하면 협의가 된 것으로 본다.":"관련 행정청이 협의 요청을 받고 20일 안에 의견을 내지 않으면 협의가 된 것으로 간주됩니다.","관습법, 판례법, 조리(행정법의 일반원칙).":"문서로 쓰이지 않은 불문법원에는 관습법과 판례법과 조리가 있고 조리가 행정법의 일반원칙에 해당합니다.","관습법은 법원이다. 사실인 관습은 법원이 아니다. 반복된 관행에 법적 확신이 더해져 법규범으로 승인된 것이다.":"관습법은 반복된 관행에 법적 확신이 더해져 법으로 인정된 것이라 법원이지만 사실인 관습은 아닙니다.","관허사업의 제한, 공급 거부, 시정명령 등도 행정의 실효성 확보 수단으로 사용된다. 법률의 근거가 있어야 한다.":"관허사업 제한이나 공급 거부 같은 수단도 의무 이행을 확보하는 데 쓰이며 국민의 권익을 제한하므로 법률 근거가 필요합니다.","광업권·어업권·양식업권 및 물 등의 사용에 관한 권리는 투자비용, 예상 수익 및 거래가격 등을 고려한 적정가격으로 보상한다.":"광업권과 어업권 같은 권리는 투자비용과 예상 수익과 거래가격을 고려해 적정한 가격으로 보상합니다.","교육에 관한 조례의 무효확인소송은 그 조례의 공포권이 있는 시·도 교육감을 피고로 하여야 한다.":"교육 조례를 공포하는 권한이 교육감에게 있으므로 그 무효확인 소송의 상대방도 시도 교육감입니다.","교환가액 또는 수리비, 수리기간 중 손실액의 휴업배상.":"물건 피해는 물건의 교환가액이나 수리비와 수리 기간 동안의 영업 손실을 휴업배상으로 계산합니다.","구 「원자력법」에 따른 원자로 시설의 부지사전승인처분은 그 자체로서 독립한 행정처분이다.":"부지사전승인은 본허가의 준비 단계 같지만 그 자체로 법적 효과가 있어 독립한 처분으로 다툴 수 있습니다.","구 국유재산법에 의한 국유재산의 무단점유 등에 대한 변상금부과는 기속행위다. 재량행위가 아니다.":"무단 점유에 변상금을 부과하는 것은 요건이 되면 반드시 해야 하는 기속행위이고 재량이 없습니다.","구 도시계획법상 개발제한구역 내의 건축허가: 예외적 허가.":"개발제한구역에서는 건축이 원칙적으로 금지되므로 그곳의 건축허가는 예외적 허가로 분류됩니다.","구 도시계획법상 도시기본계획은 행정청에 대한 지침일 뿐 일반 국민에 대한 직접적인 구속력이 없다.":"도시기본계획은 행정청이 따를 방향을 제시하는 지침에 그쳐서 국민의 권리와 의무를 직접 정하지 않습니다.","구 자동차관리법상 자동차정비조합설립인가: 인가. 「부동산 거래신고 등에 관한 법률」상 외국인등의 토지거래 허가: 인가(강학상).":"조합 설립을 인가하는 것과 토지거래허가는 법적 이름은 허가여도 성질은 학문상 인가에 해당합니다.","구 출입국관리법상 체류자격변경허가, 구 농지법에 따른 농지전용행위를 수반하는 건축허가, 구 공유수면 관리 및 매립에 관한 법률상 공유수면 점용허가. 국토계획법에 의하여 지정된 도시지역 안에서 토지의 형질변경행위를 수반하는 건축허가는 재량행위다. 공유수면 점용허가는 재량행위다.":"체류자격 변경, 농지전용을 수반한 건축허가, 공유수면 점용허가 등은 행정청에 재량이 인정되는 재량행위입니다.","구호대상자를 경찰관서에서 보호하는 기간은 24시간을 초과할 수 없고, 휴대한 무기·흉기를 임시 영치하는 기간은 10일을 초과할 수 없다.":"구호대상자는 경찰관서에서 24시간을 넘겨 보호할 수 없고 무기나 흉기를 임시로 보관하는 기간도 10일을 넘을 수 없습니다.","국가가 배상책임을 이행한 경우 공무원에게 고의 또는 중대한 과실이 있으면 그 공무원에게 구상할 수 있다. 경과실에는 구상할 수 없다.":"국가가 배상한 뒤 공무원에게 고의나 중과실이 있을 때만 구상할 수 있고 경과실에는 구상하지 못합니다.","국가가 직접 공공용으로 사용하거나 대통령령으로 정하는 기한까지 사용하기로 결정한 재산.":"공공용재산은 국가가 공중이 쓰는 용도로 직접 사용하거나 기한까지 사용하기로 정한 재산입니다.","국가가 직접 사무용·사업용 또는 공무원의 주거용으로 사용하거나 대통령령으로 정하는 기한까지 사용하기로 결정한 재산.":"공용재산은 국가가 직접 사무용이나 사업용이나 공무원 주거용으로 쓰거나 기한까지 쓰기로 정한 재산입니다.","국가공무원 면직처분에 대한 불복은 징계위원회 재심사청구가 아니라 소청심사위원회에 소청을 제기한다.":"국가공무원이 면직을 다툴 때에는 징계위원회가 아니라 소청심사위원회에 소청을 제기합니다.","국가공무원법 및 명령 위반, 직무상 의무 위반 또는 직무 태만, 직무의 내외를 불문하고 체면 또는 위신을 손상하는 행위.":"법령과 명령을 어기거나 직무 의무를 위반하거나 태만하거나 직무 안팎에서 공무원의 체면을 손상하는 행위가 징계 사유입니다.","국가공무원법상의 직위해제처분에는 의견청취에 관한 행정절차법 규정이 적용되지 않는다.":"국가공무원법상 직위해제는 별도 절차를 두고 있어 행정절차법의 의견청취 규정이 적용되지 않습니다.","국가공무원은 경력직공무원과 특수경력직공무원으로 구분한다.":"국가공무원은 평생 근무를 전제로 하는 경력직과 그렇지 않은 특수경력직의 두 갈래로 구분됩니다.","국가기관(국회·법원·헌법재판소·중앙선거관리위원회, 중앙행정기관 및 소속 기관, 행정기관 소속 위원회), 지방자치단체, 공공기관의 운영에 관한 법률 제2조의 공공기관, 지방공사 및 지방공단, 그 밖에 대통령령으로 정하는 기관.":"정보공개 의무가 있는 공공기관은 국가기관과 지방자치단체와 공공기관 운영법상 공공기관과 지방공사 등입니다.","국가기관도 취소소송의 당사자가 될 수 있다.":"국가기관이라도 법률상 이익이 있다면 일반 국민처럼 취소소송을 제기할 수 있습니다.","국가기관등은 이의신청이 있으면 심의회를 개최하여야 한다. 이미 심의를 거친 사항, 단순·반복적인 청구, 법령에 따라 비밀로 규정된 정보에 대한 청구는 개최하지 않을 수 있다.":"이의신청이 있으면 심의회를 열어야 하지만 이미 심의했거나 단순 반복이거나 법령상 비밀인 정보는 열지 않아도 됩니다.","국가기관의 장은 소속 공무원을 임용할 때 합리적인 이유 없이 사회적 신분을 이유로 차별해서는 아니 된다.":"임용할 때 합리적 이유 없이 사회적 신분을 이유로 차별하는 것은 금지됩니다.","국가나 지방자치단체는 공무원 또는 공무를 위탁받은 사인이 직무를 집행하면서 고의 또는 과실로 법령을 위반하여 타인에게 손해를 입히거나 자동차손해배상 보장법에 따라 손해배상의 책임이 있을 때 이 법에 따라 배상하여야 한다.":"공무원이 직무를 하면서 고의나 과실로 법령을 어겨 남에게 손해를 입히면 국가나 지자체가 이 법에 따라 배상합니다.","국가나 지방자치단체의 손해배상책임에 관하여 국가배상법에 규정된 사항 외에는 민법에 따른다. 민법 외의 법률에 다른 규정이 있으면 그 규정에 따른다.":"국가배상법에 없는 사항은 민법을 따르되 민법 외의 법률에 특별 규정이 있으면 그 규정이 우선합니다.","국가는 경찰관의 적법한 직무집행으로 손실발생의 원인에 책임이 없는 자가 입은 손실, 책임이 있는 자가 자신의 책임에 상응하는 정도를 초과하여 입은 손실에 대해 정당한 보상을 하여야 한다. 청구권은 손실이 있음을 안 날부터 3년, 손실이 발생한 날부터 5년이 지나면 시효로 소멸한다.":"적법한 직무집행으로 손실을 입은 책임 없는 사람과 책임을 넘어 입은 사람은 보상받고 청구권은 3년과 5년의 시효가 있습니다.","국가 또는 공공단체의 기관 상호간에 권한의 존부 또는 그 행사에 관한 다툼이 있을 때 제기하는 소송. 헌법재판소의 관장사항은 제외.":"기관소송은 국가나 공공단체의 기관끼리 권한이 있는지나 행사 방법을 두고 다툴 때 제기하며 헌법재판소 관장사항은 제외됩니다.","국가 또는 공공단체의 기관이 법률에 위반되는 행위를 한 때 직접 자기의 법률상 이익과 관계없이 그 시정을 구하기 위하여 제기하는 소송.":"민중소송은 자기의 법률상 이익과 무관하게 국가나 공공단체 기관의 위법 행위를 바로잡으려고 제기하는 소송입니다.","국가배상법은 민법 제756조 제1항 단서의 사용자 면책조항에 상응하는 규정을 두고 있지 않다.":"민법과 달리 선임과 감독에 주의했다는 이유로 책임을 면하는 사용자 면책 규정이 국가배상법에는 없습니다.","국가배상법의 배상청구 요건인 공무원의 직무에는 행정지도와 같은 비권력적 작용도 포함된다.":"국가배상에서 말하는 공무원의 직무에는 권력 작용뿐 아니라 행정지도 같은 비권력 작용도 들어갑니다.","국가배상법 제2조의 직무행위에는 입법작용과 사법작용이 포함된다.":"국가배상의 직무행위에는 행정작용뿐 아니라 입법작용과 사법작용도 들어가 모든 국가 작용이 대상이 됩니다.","국가사무가 도지사에게 기관위임된 경우 도지사가 이를 군수에게 재위임하려면 도 조례가 아니라 위임기관의 승인을 받아 규칙으로 하여야 한다. 국가사무가 지방자치단체의 장에게 위임된 기관위임사무는 원칙적으로 자치조례의 제정 범위에 속하지 않는다.":"기관위임된 국가사무를 군수에게 재위임하려면 조례가 아니라 위임기관 승인을 받은 규칙으로 하고 자치조례의 범위에는 들지 않습니다.","국가안전보장·국방·외교 또는 통일에 관한 사항 중 행정절차를 거칠 경우 국가의 중대한 이익을 현저히 해칠 우려가 있는 사항.":"국가안보나 외교 사항이라도 절차를 거치면 국가에 중대한 해가 될 우려가 있는 경우에 한정해 제외됩니다.","국가안전보장·국방·통일·외교관계 등에 관한 사항으로서 공개될 경우 국가의 중대한 이익을 현저히 해칠 우려가 있다고 인정되는 정보.":"안보와 국방과 외교 정보 중 공개하면 국가의 중대한 이익을 현저히 해칠 우려가 있는 것이 비공개 대상입니다.","국가에 대한 금전채권은 다른 법률에 규정이 없는 한 5년간 행사하지 아니하면 시효로 소멸한다.":"국가를 상대로 한 돈 청구권은 다른 법이 없으면 5년 동안 행사하지 않을 때 시효로 소멸합니다.","국가의 회계는 일반회계와 특별회계로 구분한다. 통상회계·임시회계가 아니다.":"국가의 회계는 일반회계와 특별회계로 나뉘며 통상회계와 임시회계라는 구분은 쓰지 않습니다.","국가의 회계연도는 매년 1월 1일에 시작하여 12월 31일에 종료한다. 각 회계연도의 경비는 그 연도의 세입 또는 수입으로 충당하여야 한다(회계연도 독립의 원칙).":"회계연도는 1월 1일부터 12월 31일까지이며 한 해의 경비는 그 해의 세입으로 충당하는 회계연도 독립의 원칙을 따릅니다.","국내에 일정한 주소를 두고 거주하거나 학술·연구를 위하여 일시적으로 체류하는 사람, 국내에 사무소를 두고 있는 법인 또는 단체.":"외국인 중에는 국내에 주소를 두고 사는 사람이나 학술과 연구로 체류하는 사람과 국내 사무소가 있는 단체가 청구할 수 있습니다.","국민의 권리를 제한하거나 의무를 부과하는 경우와 그 밖에 국민생활에 중요한 영향을 미치는 경우에는 법률에 근거하여야 한다(법률유보). 법률우위와 법률유보의 ‘법률’은 법령이 아니라 형식적 의미의 법률이다.":"법률유보는 국민 권리를 제한하는 행정에 법률 근거를 요구하며 여기서 법률은 국회가 만든 법만 뜻합니다.","국민의 권리 제한 또는 의무 부과와 직접 관련되는 법률·대통령령·총리령·부령은 긴급히 시행하여야 할 특별한 사유가 있는 경우를 제외하고는 공포일부터 적어도 30일이 경과한 날부터 시행되도록 하여야 한다.":"국민에게 부담을 주는 법령은 국민이 대비할 수 있도록 긴급한 사유가 없으면 공포 후 30일 이상 지나 시행합니다.","국민의 기본권 실현에 관련된 본질적이고 중요한 사항은 국회가 법률로 스스로 정하여야 한다. 헌법재판소와 대법원이 취하는 입장이다.":"기본권과 관련된 중요한 결정은 행정에 맡기지 않고 국회가 직접 정해야 한다는 판례의 입장입니다.","국민의 생명·신체 및 재산의 보호, 범죄의 예방·진압 및 수사, 범죄피해자 보호, 경비·주요 인사(人士) 경호 및 대간첩·대테러 작전 수행, 공공안녕에 대한 위험의 예방과 대응을 위한 정보의 수집·작성 및 배포, 교통 단속과 교통 위해의 방지, 외국 정부기관 및 국제기구와의 국제협력, 그 밖에 공공의 안녕과 질서 유지.":"경찰관의 직무는 생명과 재산의 보호, 범죄의 예방과 수사, 경비와 경호, 교통 단속, 국제협력 등 공공의 안녕과 질서 유지입니다.","국방·군사, 철도·도로 등 허가·인가·승인·지정을 받은 공익사업, 국가·지방자치단체가 설치하는 공공용 시설, 학교·도서관·박물관·미술관 건립, 공공기관 등이 임대·양도 목적으로 시행하는 주택 건설·택지·산업단지 조성, 부속시설 사업, 이주단지 조성, 별표 법률의 사업.":"국방과 철도와 도로 같은 허가받은 공익사업, 공공시설, 학교와 박물관, 공공기관의 주택과 산업단지 조성 등이 수용할 수 있는 사업입니다.","국세부과처분에 대한 국세청장에의 심사청구(특별행정심판), 지방토지수용위원회의 수용재결에 대한 중앙토지수용위원회에의 이의신청.":"국세청장에 대한 심사청구와 중앙토지수용위원회에 대한 이의신청은 특별한 행정심판 절차에 해당합니다.","국세청은 재정경제부장관 소속이다. 특허청(현 지식재산처)·통계청(현 국가데이터처)은 현재 국무총리 소속 처로 개편되었다. 2023 기출 당시 정답은 법제처였다.":"국세청은 국무총리 소속이 아니라 재정경제부장관 소속이며 특허청과 통계청은 총리 소속 처로 개편되었습니다.","국유공물·공유공물·사유공물은 소유권 귀속 주체에 따른 분류다. 국가 또는 지방자치단체가 소유권자인 공물을 모두 국유공물이라 하는 것이 아니다.":"국유와 공유와 사유 공물은 소유자가 누구인지에 따른 분류이며 지자체 소유 공물까지 국유공물이라 부르지는 않습니다.","국유재산에는 사권을 설정하지 못한다. 다만 일반재산에 대하여 대통령령으로 정하는 경우에는 예외다. 행정재산에는 사권을 설정하지 못한다. 사권이 설정된 재산은 그 사권이 소멸된 후가 아니면 국유재산으로 취득하지 못한다. 판결에 따라 취득하는 경우에는 예외다.":"국유재산에는 원칙적으로 사권을 설정할 수 없고 사권이 붙은 재산은 사권이 사라진 뒤에야 국유재산으로 취득할 수 있습니다.","국유재산은 그 용도에 따라 행정재산과 일반재산으로 구분한다. 행정재산은 공용재산, 공공용재산, 기업용재산, 보존용재산이다.":"국유재산은 용도에 따라 행정재산과 일반재산으로 나뉘고 행정재산에는 공용과 공공용과 기업용과 보존용재산이 있습니다.","국유재산 중 행정재산의 사용허가는 행정처분이다. 일반재산의 대부계약(사법상 계약)은 사법관계다.":"행정재산 사용허가는 처분이지만 일반재산을 빌려주는 대부계약은 사법상 계약이어서 사법관계입니다.","국토교통부장관은 사업인정을 하려면 관계 중앙행정기관의 장, 시·도지사 및 중앙토지수용위원회와 협의하고 사업인정에 이해관계가 있는 자의 의견을 들어야 한다.":"사업인정을 하기 전에 관계 중앙행정기관과 시도지사와 중앙토지수용위원회와 협의하고 이해관계인의 의견도 들어야 합니다.","국토교통부장관은 사업인정을 하였을 때 지체 없이 사업시행자, 토지소유자 및 관계인, 관계 시·도지사에게 통지하고 사업시행자의 성명이나 명칭, 사업의 종류, 사업지역 및 수용·사용할 토지의 세목을 관보에 고시하여야 한다.":"사업인정을 했으면 곧바로 사업시행자와 토지소유자 등에게 통지하고 사업 종류와 지역과 토지 세목을 관보에 고시합니다.","국회 또는 지방의회의 의결을 거치거나 동의 또는 승인을 받아 행하는 사항.":"국회나 지방의회의 의결과 동의를 거치는 사항은 이미 의회 절차가 있어 행정절차법 적용에서 빠집니다.","권력적 사실행위는 항고소송의 대상인 처분이다. 비권력적 사실행위는 처분이 아니다.":"권력적 사실행위는 국민에게 수인을 강제하므로 처분으로 다투지만 비권력적 사실행위는 처분이 아닙니다.","권리나 이익을 부여하는 처분(수익적 처분)을 취소하려는 경우에는 취소로 인하여 당사자가 입게 될 불이익을 취소로 달성되는 공익과 비교·형량하여야 한다.":"이익을 준 처분을 거두려면 당사자가 입는 불이익과 취소로 얻을 공익을 견주어 판단해야 합니다.","권익을 제한하거나 의무를 부과하는 경우 그 권익 제한·의무 지속 기간의 계산: 일·주·월·연으로 정한 때 기간의 첫날을 산입한다. 기간의 말일이 토요일 또는 공휴일이어도 그 날로 만료한다. 국민에게 불리한 경우는 예외다.":"국민에게 의무를 지우는 기간은 첫날을 넣어 세고 마지막 날이 휴일이어도 그날 끝나지만 불리하면 예외입니다.","권한의 위임은 위임기관의 권한의 일부에 한하여 인정된다. 위임은 권한의 법적 귀속을 변경하므로 법률이 위임을 허용하고 있는 경우에 한하여 인정된다.":"위임은 권한의 일부만 대상이고 법적 귀속이 바뀌는 만큼 법률이 허용한 경우에만 할 수 있습니다.","그 기간의 말일이 토요일 또는 공휴일인 때에는 그 말일로 기간이 만료한다.":"시행일을 정하는 기간의 마지막 날이 휴일이어도 휴일 다음 날로 미루지 않고 그날 만료합니다.","그 밖의 국가행정기관의 장 또는 소속 행정청, 시·도지사 또는 시·도의 의회, 지방자치단체조합 등의 처분에 대한 심판청구는 국민권익위원회에 두는 중앙행정심판위원회에서 심리·재결한다.":"일반 국가행정기관과 시도지사 등의 처분은 국민권익위원회에 두는 중앙행정심판위원회가 심리하고 재결합니다.","금품·향응 등 취득·제공이나 예산·기금·국유재산 횡령 등의 경우 해당 이득의 5배 내의 징계부가금 부과 의결을 요구하여야 한다.":"금품과 향응을 받거나 공금을 횡령한 경우에는 징계 외에 그 이득의 5배 안에서 징계부가금을 물리도록 의결을 요구해야 합니다.","기부금품모집규제법상 기부금품모집허가: 허가.":"기부금품 모집은 원칙적으로 자유이나 규제로 막아 둔 것을 풀어 주는 것이어서 보통의 허가입니다.","기부채납의 부관이 당연무효이거나 취소되지 아니한 이상, 부관으로 인한 증여계약의 중요부분의 착오를 이유로 증여계약을 취소할 수 없다.":"기부채납 부관이 무효나 취소가 되지 않았다면 그에 따른 증여계약을 착오를 이유로 취소할 수는 없습니다.","기존의 시외버스운송사업자는 동일노선을 운행하는 다른 회사에 대한 시외버스운송사업계획변경인가 처분으로 수익감소가 예상되는 경우 그 처분의 취소를 구할 법률상 이익이 있다(경업자소송).":"같은 노선 경쟁 업체에 대한 인가로 수익이 줄 우려가 있는 기존 사업자는 그 인가 취소를 구할 이익이 있는 경업자입니다.","긴급구호를 요청받은 보건의료기관이나 공공구호기관은 정당한 이유 없이 거절할 수 없다.":"경찰이 긴급구호를 요청하면 보건의료기관과 공공구호기관은 정당한 이유 없이 거절하지 못합니다.","긴급한 사유로 예고가 현저히 곤란한 경우, 법령등의 단순한 집행을 위한 경우, 국민의 권리·의무 또는 일상생활과 관련이 없는 경우, 예고가 공공의 안전 또는 복리를 현저히 해칠 우려가 상당한 경우.":"긴급하거나 단순 집행이거나 국민 생활과 무관하거나 예고가 공공의 안전을 해칠 우려가 크면 행정예고를 생략할 수 있습니다.","납부기한까지 과태료를 납부하지 아니한 때 납부기한을 경과한 날부터 체납된 과태료의 100분의 3에 상당하는 가산금을 징수하고, 매 1개월이 경과할 때마다 1천분의 12에 상당하는 중가산금을 가산하며 중가산금은 60개월을 초과하지 못한다.":"기한을 넘기면 체납액의 100분의 3 가산금에 더해 매달 1천분의 12 중가산금이 붙고 중가산금은 60개월까지만 붙습니다.","내부위임에 따라 수임관청이 자신의 이름으로 처분을 한 경우 그 처분에 대한 항고소송(무효확인소송 포함)의 피고는 수임관청이다. 위임관청이 아니다.":"내부위임을 받은 기관이 자기 명의로 처분했다면 항고소송의 피고는 위임관청이 아니라 그 수임관청입니다.","내부위임의 경우 수임관청이 자기 이름으로 처분을 하면 수임관청이 피고다.":"내부위임에서는 수임관청이 자기 명의로 처분했다면 위임관청이 아니라 수임관청이 피고입니다.","누구든지 예고된 입법안에 의견을 제출할 수 있고, 행정청은 특별한 사유가 없으면 존중하여 처리하여야 하며 처리결과를 통지하여야 한다.":"누구나 예고된 입법안에 의견을 낼 수 있고 행정청은 특별한 사유가 없으면 존중해 처리하고 결과를 알려야 합니다.","누구든지 의견제출 또는 청문을 통하여 알게 된 사생활이나 경영상 또는 거래상의 비밀을 정당한 이유 없이 누설하거나 다른 목적으로 사용하여서는 아니 된다.":"의견제출이나 청문에서 알게 된 사생활과 영업 비밀은 정당한 이유 없이 퍼뜨리거나 다른 목적에 쓰면 안 됩니다.","다른 공공기관이 보유·관리하는 정보의 공개 청구를 받았을 때에는 지체 없이 소관 기관으로 이송하고 청구인에게 문서로 통지한다.":"자기 기관이 가진 정보가 아니면 지체 없이 소관 기관으로 넘기고 청구인에게 서면으로 알립니다.","다른 법령등에서 공청회를 개최하도록 규정한 경우, 해당 처분의 영향이 광범위하여 널리 의견을 수렴할 필요가 있다고 행정청이 인정하는 경우, 국민생활에 큰 영향을 미치는 처분으로서 대통령령으로 정하는 처분에 대하여 대통령령으로 정하는 수 이상의 당사자등이 개최를 요구하는 경우.":"법령이 정했거나 영향이 광범위해 널리 의견을 들어야 하거나 일정 수 이상 당사자가 요구하면 공청회를 엽니다.","다른 법령등에서 청문을 하도록 규정한 경우, 행정청이 필요하다고 인정하는 경우, 인허가 등의 취소·신분 또는 자격의 박탈·법인이나 조합 등의 설립허가의 취소 처분을 하는 경우.":"법령이 청문을 정했거나 행정청이 필요하다고 보거나 인허가 취소와 자격 박탈처럼 중한 처분을 할 때 청문을 합니다.","다른 법률 또는 법률에서 위임한 명령(국회규칙·대법원규칙·헌법재판소규칙·중앙선거관리위원회규칙·대통령령 및 조례로 한정)에 따라 비밀이나 비공개 사항으로 규정된 정보.":"다른 법률이나 위임받은 명령으로 비밀이나 비공개로 정해진 정보는 이 법에서도 공개하지 않는 대상입니다.","다른 법률에 의한 인·허가의제 효과를 수반하는 건축신고, 「수산업법」상 어업의 신고, 「노인장기요양보험법」상 장기요양기관의 폐업신고, 「식품위생법」상 영업양도에 따른 지위승계 신고.":"인허가의제 효과가 있는 건축신고와 어업신고, 폐업신고, 지위승계 신고는 수리를 거쳐야 효력이 생기는 신고입니다.","다른 행정청과의 협의 등의 절차를 거쳐야 하는 처분에 대하여 확약을 하려면 확약을 하기 전에 그 절차를 거쳐야 한다.":"다른 행정청과 협의해야 하는 처분이라면 확약을 하기 전에 먼저 그 협의 절차를 마쳐야 합니다.","다른 행정청이 보다 능률적이거나 경제적으로 응원할 수 있는 명백한 이유가 있는 경우, 행정응원으로 인하여 고유의 직무 수행이 현저히 지장받을 것으로 인정되는 명백한 이유가 있는 경우. 응원을 거부하는 경우 그 사유를 응원을 요청한 행정청에 통지하여야 한다.":"다른 곳이 더 잘 응원할 수 있거나 자기 업무에 큰 지장이 명백하면 거부할 수 있고 거부 사유를 요청한 행정청에 알립니다.","다수의 당사자등이 공동으로 행정절차에 관한 행위를 할 때에는 대표자를 선정할 수 있다. 행정청은 대표자가 선정되지 않거나 너무 많아 절차가 지연될 우려가 있으면 상당한 기간 내에 3인 이내의 대표자를 선정할 것을 요청할 수 있고, 따르지 않으면 직접 선정할 수 있다.":"당사자가 많으면 대표자를 두고 지연될 우려가 있으면 행정청이 3인 이내 선정을 요청하며 따르지 않으면 직접 정합니다.","다수의 행정청이 관여하는 처분을 구하는 신청을 접수한 경우 관계 행정청과의 신속한 협조를 통하여 처분이 지연되지 아니하도록 하여야 한다.":"여러 행정청이 얽힌 신청은 관계 행정청과 빨리 협조해 처분이 늦어지지 않도록 해야 합니다.","당사자등은 공표된 처분기준이 명확하지 아니한 경우 해당 행정청에 해석 또는 설명을 요청할 수 있고, 행정청은 특별한 사정이 없으면 요청에 따라야 한다.":"공표된 기준이 불분명하면 당사자가 해석이나 설명을 요청할 수 있고 행정청은 특별한 사정이 없으면 응해야 합니다.","당사자등은 의견제출의 경우 사전 통지가 있는 날부터 의견제출기한까지, 청문의 경우 통지가 있는 날부터 청문이 끝날 때까지 조사결과 문서의 열람 또는 복사를 요청할 수 있다. 행정청은 다른 법령에 따라 공개가 제한되는 경우를 제외하고 거부할 수 없다.":"당사자는 의견제출이나 청문 기간 동안 조사결과 문서를 열람하고 복사할 수 있고 법령상 제한이 없다면 거부할 수 없습니다.","당사자등은 처분 전에 서면이나 말 또는 정보통신망을 이용하여 의견제출을 할 수 있고 증거자료를 첨부할 수 있다. 정당한 이유 없이 의견제출기한까지 의견제출을 하지 않으면 의견이 없는 것으로 본다.":"처분 전에 서면과 말과 전자적 방법으로 의견과 증거를 낼 수 있고 정당한 이유 없이 기한을 넘기면 의견이 없는 것으로 봅니다.","당사자등의 배우자·직계 존속·비속·형제자매, 법인등의 임원 또는 직원, 변호사, 행정청 또는 청문 주재자(청문의 경우)의 허가를 받은 자, 법령등에 따라 대리인이 될 수 있는 자.":"가족과 법인의 임직원과 변호사 등 일정한 사람이 당사자를 대신해 절차에 참여하는 대리인이 될 수 있습니다.","당사자등이 사망한 경우의 상속인과 법령에 따라 권리·이익을 승계한 자, 합병 후 존속하거나 새로 설립된 법인등은 당사자등의 지위를 승계하고 행정청에 그 사실을 통지하여야 한다. 처분에 관한 권리·이익을 사실상 양수한 자는 행정청의 승인을 받아 지위를 승계할 수 있다.":"상속인이나 합병 후 법인은 당연히 지위를 이어받아 통지하고 사실상 양수한 사람은 행정청 승인을 받아야 이어받습니다.","당사자등이 정당한 사유로 청문기일에 출석하지 못하면 10일 이상의 기간을 정하여 의견진술 및 증거제출을 요구하여야 하며, 기간이 지난 후 청문을 마칠 수 있다.":"정당한 사유로 불출석하면 10일 이상 기간을 주어 진술과 증거 제출을 요구한 뒤 그 기간이 지나야 청문을 마칠 수 있습니다.","당사자소송에 관하여 법령에 제소기간이 정하여져 있는 때에는 그 기간은 불변기간으로 한다.":"당사자소송에 법령상 제소기간이 있다면 그 기간은 법원이 늘릴 수 없는 불변기간입니다.","당사자소송에는 피고경정(제14조), 공동소송(제15조), 제3자의 소송참가(제16조), 행정청의 소송참가(제17조), 처분변경으로 인한 소의 변경(제22조), 행정심판기록 제출명령(제25조), 직권심리(제26조), 취소판결의 기속력 일부(제30조 제1항), 소송비용 부담·재판의 효력(제32조·제33조)이 준용된다. 집행정지와 사정판결은 준용되지 않는다.":"당사자소송에는 피고경정과 소송참가와 직권심리 같은 취소소송 규정이 준용되지만 집행정지와 사정판결은 준용되지 않습니다.","당사자소송은 국가·공공단체 그 밖의 권리주체를 피고로 한다. 행정청이 피고가 아니다.":"당사자소송의 피고는 처분을 한 행정청이 아니라 법률관계의 주체인 국가나 공공단체 등입니다.","당사자소송의 재판관할에는 제9조를 준용한다. 국가 또는 공공단체가 피고인 경우 관계행정청의 소재지를 피고의 소재지로 본다.":"당사자소송의 관할은 취소소송 규정을 준용하고 국가나 공공단체가 피고이면 관계 행정청 소재지를 피고 소재지로 봅니다.","당사자의 동의가 있는 경우.":"사후부관은 당사자가 동의하면 가능하므로 상대방의 의사가 허용 사유가 됩니다.","당사자의 신뢰를 보호할 가치가 있는 등 정당한 사유가 있는 경우에는 장래를 향하여 취소할 수 있다.":"당사자의 신뢰를 보호할 사정이 있다면 소급하지 않고 앞으로만 효력을 없애는 취소를 할 수 있습니다.","당연퇴직 사유: 결격사유(임용 후 발생) 등. 공무원이 당연퇴직 사유에 해당하면 법률상 당연히 퇴직되며, 당연퇴직 인사발령은 관념의 통지로서 항고소송의 대상이 되는 처분이 아니다.":"당연퇴직은 사유가 생기면 법률상 당연히 퇴직하는 것이며 인사발령은 이미 생긴 사실을 알리는 관념의 통지라 처분이 아닙니다.","대리권을 수여받은 데 불과하여 그 자신의 명의로 행정처분을 할 권한이 없는 행정청이 대리관계를 밝힘이 없이 자신의 명의로 처분을 하였다면 처분명의자인 해당 행정청이 피고가 되는 것이 원칙이다.":"대리 권한만 있는 행정청이 대리관계를 밝히지 않고 자기 명의로 처분했다면 그 행정청이 피고가 됩니다.","대리권을 수여받은 데 불과하여 자신의 명의로는 행정처분을 할 권한이 없는 행정청이 대리관계를 밝힘이 없이 그 자신의 명의로 처분을 하였다면 처분명의자인 해당 행정청이 항고소송의 피고가 된다.":"대리인으로서 권한만 있는 행정청이 대리관계를 밝히지 않고 자기 명의로 처분하면 그 행정청이 피고가 됩니다.","대집행에 대하여는 행정심판을 제기할 수 있다. 이는 법원에 대한 출소의 권리를 방해하지 아니한다.":"대집행에 불복해 행정심판을 낼 수 있고 그렇다고 법원에 소송할 권리가 제한되지는 않습니다.","대집행에 요한 비용에 대하여 행정청은 사무비의 소속에 따라 국세에 다음가는 순위의 선취득권을 가진다.":"대집행 비용에 대해 행정청은 국세 다음 순위로 먼저 변제받을 수 있는 선취득권을 가집니다.","대집행영장에 의한 통지는 취소소송의 대상이 된다.":"대집행영장 통지는 의무자의 법적 지위에 영향을 주는 처분이어서 취소소송으로 다툴 수 있습니다.","대집행의 주체는 행정청이다. 행정청은 스스로 하거나 제3자로 하여금 하게 할 수 있다. 처분청 스스로만 하여야 하는 것이 아니다.":"대집행은 행정청이 주체이지만 반드시 직접 할 필요는 없고 제삼자에게 시켜 실행하게 할 수 있습니다.","대통령경호처는 대통령 소속(경호)이다. 국무총리 소속이 아니다.":"대통령경호처는 국무총리가 아니라 대통령 소속으로 경호 업무를 맡는 기관입니다.","대통령령은 법률에서 구체적으로 범위를 정하여 위임받은 사항과 법률을 집행하기 위하여 필요한 사항에 관하여 발한다(포괄위임 금지).":"대통령령은 법률이 범위를 구체적으로 정해 맡긴 사항과 법률 집행에 필요한 사항만 정할 수 있고 포괄 위임은 금지됩니다.","대통령령·총리령·부령은 특별한 규정이 없으면 공포한 날부터 20일이 경과함으로써 효력을 발생한다. 법률은 특별한 규정이 없으면 공포한 날부터 20일이 경과함으로써 효력을 발생한다.":"법률과 대통령령, 총리령, 부령은 특별한 규정이 없으면 공포일부터 20일이 지나야 효력이 생깁니다.","대통령은 정부의 수반으로서 법령에 따라 모든 중앙행정기관의 장을 지휘·감독하며, 국무총리와 중앙행정기관의 장의 위법·부당한 명령이나 처분을 중지 또는 취소할 수 있다. 국무총리는 대통령의 명을 받아 중앙행정기관의 장을 지휘·감독하며 대통령의 승인을 받아 중지·취소할 수 있다.":"대통령은 모든 중앙행정기관의 장을 지휘하고 위법한 처분을 중지하거나 취소할 수 있으며 총리는 대통령의 승인을 받아 같은 일을 합니다.","대통령의 처분 또는 부작위에 대하여는 다른 법률에서 행정심판을 청구할 수 있도록 정한 경우 외에는 행정심판을 청구할 수 없다.":"대통령의 처분이나 부작위는 다른 법률이 허용한 경우를 제외하고는 행정심판 대상이 아닙니다.","대표자나 관리인이 정하여져 있는 경우 그 사단이나 재단의 이름으로 심판청구를 할 수 있다.":"법인이 아니어도 대표자나 관리인이 정해진 사단과 재단은 단체의 이름으로 심판을 청구할 수 있습니다.","대한민국 영역 안에서 질서위반행위를 한 자, 영역 밖에서 질서위반행위를 한 대한민국 국민, 영역 밖에 있는 대한민국의 선박 또는 항공기 안에서 질서위반행위를 한 외국인에게 적용한다.":"질서위반행위규제법은 국내에서 위반한 사람과 국외에서 위반한 내국민과 우리 선박이나 항공기 안의 외국인에게 적용됩니다.","도로·하천, 그 밖의 공공의 영조물의 설치나 관리에 하자가 있기 때문에 타인에게 손해를 발생하게 하였을 때 국가나 지방자치단체는 그 손해를 배상하여야 한다.":"도로나 하천 같은 공공시설의 설치나 관리에 하자가 있어 남에게 손해가 생기면 국가나 지자체가 배상합니다.","동일 소유자의 일단의 토지 일부를 취득하거나 사용하는 경우 잔여지 가치 상승 등 이익을 취득·사용으로 인한 손실과 상계할 수 없다.":"일부 토지를 취득할 때 남은 땅 값이 올랐다고 해서 그 이익을 취득으로 생긴 손실과 서로 맞바꿔 줄일 수는 없습니다.","동행한 사람의 가족이나 친지 등에게 신분·장소·목적·이유를 알리거나 즉시 연락할 기회를 주어야 하며, 변호인의 도움을 받을 권리가 있음을 알려야 한다. 6시간을 초과하여 경찰관서에 머물게 할 수 없다.":"동행한 사람에게 가족에게 알리거나 연락할 기회를 주고 변호인의 도움을 받을 권리를 알려야 하며 6시간을 넘겨 머물게 할 수 없습니다.","만 14세 미만 아동의 법정대리인은 개인정보처리자에게 그 아동의 개인정보 열람 등 요구를 할 수 있다.":"만 14세 미만 아동은 스스로 권리를 행사하기 어려워 법정대리인이 대신 열람 등을 요구할 수 있습니다.","매 회계연도의 세출예산은 다음 연도에 이월하여 사용할 수 없다. 명시이월비, 연도 내 지출원인행위를 하고 불가피한 사유로 지출하지 못한 경비 등은 예외다.":"세출예산은 다음 연도로 넘겨 쓸 수 없지만 명시이월비와 불가피하게 지출하지 못한 경우 등은 예외입니다.","명령·규칙의 위헌·위법 여부가 재판의 전제가 된 경우 대법원이 최종적으로 심사한다(구체적 규범통제).":"재판 중에 명령이나 규칙의 위헌 위법이 쟁점이 되면 대법원이 최종 판단하는 구체적 규범통제입니다.","모든 공무원은 법령을 준수하며 성실히 직무를 수행하여야 한다.":"성실 의무는 공무원이 법령을 지키면서 맡은 직무를 성실하게 수행해야 한다는 가장 기본적인 의무입니다.","무단점유자에 대하여 사용료나 대부료의 100분의 120에 상당하는 금액을 징수한다.":"국유재산을 무단으로 쓴 사람에게는 정상 사용료나 대부료의 100분의 120을 변상금으로 거둡니다.","무효와 취소의 구별 기준: 중대명백설(판례). 하자가 중대하고 명백하면 무효, 그에 미달하면 취소사유다.":"판례는 하자가 중대하고 명백할 때만 무효로 보고 그에 못 미치면 취소 사유로 다룹니다.","무효인 처분에 대하여는 무효확인소송뿐 아니라 무효선언을 구하는 의미의 취소소송도 제기할 수 있다. 취소소송의 형식을 취하면 제소기간 등 취소소송 요건을 갖추어야 한다.":"무효인 처분도 취소소송 형식으로 다툴 수 있지만 그렇게 하면 제소기간 같은 취소소송의 요건을 갖춰야 합니다.","무효인 처분은 처음부터 효력이 발생하지 아니하므로 공정력이 없다.":"무효는 하자가 중대하고 명백해서 처음부터 효력이 없으므로 일단 유효로 통용되는 공정력도 생기지 않습니다.","무효인 처분은 처음부터 효력이 발생하지 아니한다.":"무효인 처분은 취소를 기다릴 것 없이 처음부터 법적 효과가 없습니다.","무효확인소송에는 제소기간의 제한이 없다. 취소소송은 제소기간 내에 제기하여야 한다.":"무효 확인은 언제든 구할 수 있지만 취소소송은 제소기간 안에 내야 하므로 둘의 큰 차이입니다.","물건에 대한 권원의 유무와 관계없이 물건을 현실적으로 지배하고 있는 자에게도 상태책임이 인정된다.":"상태책임은 소유권 같은 권원이 없어도 위험한 물건을 실제로 지배하고 있다면 그 사람에게도 인정됩니다.","미아를 인수할 보호자 확인, 유실물을 인수할 권리자 확인, 사고로 인한 사상자 확인, 행정처분을 위한 교통사고 조사에 필요한 사실 확인. 긴급구호를 요청받은 보건의료기관에 대한 요청사실의 확인은 포함되지 않는다.":"출석 요구는 미아의 보호자와 유실물의 권리자와 사상자와 교통사고 조사에 필요한 사실 확인에 한하며 긴급구호 요청 확인은 포함되지 않습니다.","민사소송에서 어느 행정처분의 당연무효 여부가 선결문제로 되는 때에는 민사법원은 이를 판단하여 당연무효임을 전제로 판결할 수 있다. 처분등의 효력 유무 또는 존재 여부가 민사소송의 선결문제로 되어 수소법원이 심리·판단하는 경우, 수소법원은 그 처분등을 행한 행정청에게 선결문제로 된 사실을 통지하여야 한다.":"민사재판에서 처분의 당연무효가 선결문제이면 민사법원이 직접 판단할 수 있고 이때 처분 행정청에 사실을 통지합니다.","민중소송 및 기관소송은 법률이 정한 경우에 법률에 정한 자에 한하여 제기할 수 있다.":"객관소송인 민중소송과 기관소송은 법률이 정한 경우에 정해진 사람만 제기할 수 있습니다.","범죄행위가 목전에 행하여지려고 한다고 인정될 때 관계인에게 필요한 경고를 하고, 생명·신체의 위해 또는 재산에 중대한 손해를 끼칠 우려가 있는 긴급한 경우 제지할 수 있다.":"범죄가 눈앞에 닥쳤다고 인정되면 먼저 경고하고 생명이나 재산에 중대한 위해가 우려되는 긴급한 경우에는 제지할 수 있습니다.","법관, 검사, 외무공무원은 특정직공무원이다. 일반직공무원이 아니다. 검사는 특정직공무원에 해당한다.":"법관과 검사와 외무공무원은 일반직이 아니라 특정직공무원에 속합니다.","법규가 공익만을 목적으로 하여 간접적·사실상 얻는 이익으로, 침해되어도 소송으로 다툴 법률상 이익이 아니다.":"공익을 위한 법규의 부수 효과로 얻는 이익은 침해되어도 소송으로 다툴 수 없는 사실상의 이익입니다.","법규명령은 위임명령(법률의 위임에 의한 새로운 입법사항 규정 가능)과 집행명령(상위 법령의 집행을 위한 세부사항만 규정)으로 나뉜다.":"위임명령은 위임을 받아 새로운 사항을 정할 수 있고 집행명령은 상위 법령을 시행할 세부 사항만 정합니다.","법규명령 자체가 직접 국민의 권리·의무를 규율하여 집행행위 없이 법적 효과를 발생하면 처분으로서 항고소송의 대상이 된다.":"법규명령이 따로 집행행위 없이 곧바로 국민의 권리와 의무를 정하면 처분처럼 취급되어 소송 대상이 됩니다.","법령등에서 당사자가 신청할 수 있는 처분을 규정하고 있는 경우, 행정청이 당사자의 신청에 따라 장래에 어떤 처분을 하거나 하지 아니할 것을 내용으로 하는 의사표시.":"확약은 신청할 수 있는 처분에 대해 행정청이 앞으로 그 처분을 하거나 하지 않겠다고 미리 약속하는 의사표시입니다.","법령등에 특별한 규정이 있거나 처분 당시의 법령등을 적용하기 곤란한 특별한 사정이 있는 경우를 제외하고는 처분 당시의 법령등에 따른다. 신청 당시가 아니다.":"신청에 따른 처분은 신청한 때가 아니라 처분을 하는 시점의 법령을 기준으로 처리합니다.","법령등에 특별한 규정이 있는 경우를 제외하고는 법령등을 위반한 행위 당시의 법령등에 따른다. 처분 당시가 아니다.":"위반 행위에 대한 제재는 처분 시점이 아니라 위반한 당시의 법령으로 판단합니다.","법령등 위반행위가 종료된 날부터 5년이 지나면 제재처분(인허가의 정지·취소·철회, 등록 말소, 영업소 폐쇄와 정지를 갈음하는 과징금 부과)을 할 수 없다.":"위반이 끝난 날부터 5년이 지나면 인허가 취소나 정지 같은 제재처분을 더는 할 수 없습니다.","법령등을 공포한 날부터 시행하는 경우에는 공포한 날을 시행일로 한다.":"공포한 날부터 시행한다고 정한 법령은 공포일이 곧 시행일이 됩니다.","법령등을 제정·개정 또는 폐지하려는 경우 입법안을 마련한 행정청은 입법예고하여야 한다. 예고하지 않을 수 있는 경우: 입법이 긴급을 요하는 경우, 상위 법령등의 단순한 집행을 위한 경우, 국민의 권리·의무 또는 일상생활과 관련이 없는 경우, 단순한 표현·자구 변경 등 예고의 필요가 없거나 곤란한 경우, 예고함이 공공의 안전 또는 복리를 현저히 해칠 우려가 있는 경우.":"법령을 만들거나 고치거나 없앨 때는 입법예고가 원칙이며 긴급하거나 단순 집행이거나 국민과 무관하면 하지 않을 수 있습니다.","법령등의 변경이나 사정변경으로 처분을 더 이상 존속시킬 필요가 없게 된 경우.":"법령이 바뀌거나 사정이 달라져 처분을 계속 유지할 이유가 사라졌을 때도 철회할 수 있습니다.","법령등의 이유로 독자적인 직무 수행이 어려운 경우, 인원·장비의 부족 등 사실상의 이유로 독자적인 직무 수행이 어려운 경우, 다른 행정청에 소속되어 있는 전문기관의 협조가 필요한 경우, 다른 행정청이 관리하고 있는 문서·통계 등 행정자료가 직무 수행을 위하여 필요한 경우, 다른 행정청의 응원을 받아 처리하는 것이 보다 능률적이고 경제적인 경우의 5가지.":"혼자 직무를 하기 어렵거나 전문기관과 행정자료가 필요하거나 응원이 능률적일 때 다른 행정청에 응원을 요청합니다.","법령등의 해석 또는 행정청의 관행이 일반적으로 국민들에게 받아들여졌을 때에는, 공익 또는 제3자의 정당한 이익을 현저히 해칠 우려가 있는 경우를 제외하고는 새로운 해석 또는 관행에 따라 소급하여 불리하게 처리하여서는 아니 된다.":"받아들여진 해석이나 관행이 바뀌었다고 지난 일에 불리하게 소급 적용할 수 없고 공익을 해칠 때만 예외입니다.","법령상 감경사유가 있는 경우 이를 전혀 고려하지 않은 과징금 부과처분은 위법하다.":"법령에 감경 사유가 있는데도 전혀 따져 보지 않고 과징금을 매겼다면 처분이 위법합니다.","법령에서 조례로 정하도록 위임한 사항은 그 법령의 하위 법령에서 위임의 내용과 범위를 제한하거나 직접 규정할 수 없다.":"조례로 정하라고 맡긴 사항을 하위 법령이 대신 정하거나 위임 범위를 좁히면 위임 취지에 어긋납니다.","법령에 의한 일반적·상대적 금지를 특정한 경우에 해제하여 적법하게 할 수 있게 하는 행위. 원칙적으로 기속행위다.":"허가는 일반적으로 금지된 행위를 특정한 경우에 풀어 주는 행위이며 원칙적으로 기속행위입니다.","법령으로 정한 ‘과징금을 부과하는 위반행위와 과징금의 금액’에 열거되지 않은 위반행위에 대해 사업정지처분을 갈음하여 과징금을 부과할 수 없다.":"법령에 열거된 위반행위가 아니라면 사업정지를 대신하는 과징금을 마음대로 부과할 수 없습니다.","법령의 규정에 따라 공고하거나 고시한 처분이 재결로써 취소되거나 변경되면 처분을 한 행정청은 지체 없이 그 취소 또는 변경 사실을 공고·고시하여야 한다.":"공고나 고시로 한 처분이 재결로 취소되거나 변경되면 처분청이 같은 방식으로 그 사실을 지체 없이 알려야 합니다.","법령의 위임이 없음에도 법령에 규정된 처분 요건 사항을 부령에서 변경하여 규정한 경우, 그 부령의 규정은 대외적 구속력이 없다.":"위임 없이 부령에서 처분 요건을 바꿔 정했다면 그 부령은 법규명령의 효력이 없어 대외적으로 구속하지 않습니다.","법령의 입법안은 관보 및 법제처장이 구축·제공하는 정보시스템을 통해, 자치법규의 입법안은 공보를 통해 공고한다. 대통령령을 입법예고하는 경우 국회 소관 상임위원회에 제출하여야 한다.":"법령안은 관보와 법제처 시스템으로, 자치법규안은 공보로 공고하고 대통령령은 국회 소관 상임위원회에도 제출합니다.","법률(지방자치단체의 조례 포함)상의 의무를 위반하여 과태료를 부과하는 행위. 대통령령으로 정하는 사법상·소송법상 의무 위반이나 징계사유에 해당하는 행위는 제외.":"법률이나 조례상 의무를 어겨 과태료를 부과하는 행위를 말하며 사법상 의무 위반과 징계사유는 포함되지 않습니다.","법률 또는 법률에 의거한 행정청의 명령에 의한 의무로서 타인이 대신하여 행할 수 있는 행위(대체적 작위의무)를 이행하지 아니하고, 다른 수단으로 이행 확보가 곤란하며, 불이행을 방치함이 심히 공익을 해칠 것으로 인정될 때.":"대집행은 대체적 작위의무를 이행하지 않고 다른 수단으로는 곤란하며 방치하면 공익을 심히 해칠 때 할 수 있습니다.","법률로 정하는 바에 따라 의무를 위반한 자의 성명·법인명, 위반사실 등을 일반에게 공표하는 수단이다. 공표 전에 증거와 근거를 확인하고 당사자에게 통지하여 의견제출 기회를 주어야 한다.":"의무 위반자의 이름과 위반 사실을 널리 알려 의무 이행을 압박하는 수단이며 공표 전에 증거 확인과 의견제출 기회가 필요합니다.","법률에 규정된 행정기관의 사무 중 일부를 지방자치단체가 아닌 법인·단체 또는 그 기관이나 개인에게 맡겨 그의 명의로 그의 책임 아래 행사하도록 하는 것. 조사·검사·검정·관리 사무 등 국민의 권리·의무와 직접 관계되지 않는 사무를 위탁할 수 있다.":"민간위탁은 지자체가 아닌 법인이나 개인에게 사무 일부를 맡기는 것이며 국민의 권리의무와 직접 관계없는 조사나 검사 사무가 대상입니다.","법률에 규정된 행정기관의 장의 권한 중 일부를 다른 행정기관의 장에게 맡겨 그의 권한과 책임 아래 행사하도록 하는 것.":"위탁은 상하 관계가 아닌 다른 행정기관의 장에게 권한 일부를 맡겨 수탁자의 책임으로 행사하게 하는 것입니다.","법률에 규정된 행정기관의 장의 권한 중 일부를 보조기관 또는 하급행정기관의 장이나 지방자치단체의 장에게 맡겨 그의 권한과 책임 아래 행사하도록 하는 것.":"위임은 법에 정해진 권한 일부를 하급기관이나 지자체장에게 맡겨 수임자의 권한과 책임으로 행사하게 하는 것입니다.","법률에 따르지 아니하고는 어떤 행위도 질서위반행위로 과태료를 부과하지 아니한다(법정주의).":"법률에 근거가 없으면 어떤 행위도 과태료 부과 대상이 될 수 없다는 법정주의입니다.","법률에 따른 것과 세출예산금액 또는 계속비의 총액 범위 안의 것 외에 채무를 부담하는 행위를 하려면 미리 예산으로써 국회의 의결을 얻어야 한다.":"법률이나 예산 범위 밖으로 채무를 질 때는 미리 예산 형식으로 국회의 의결을 얻어야 합니다.","법률에 신고의 수리가 필요하다고 명시되어 있는 경우(행정기관의 내부 업무 처리 절차로서 수리를 규정한 경우는 제외)에는 행정청이 수리하여야 효력이 발생한다.":"법률이 수리를 필요하다고 분명히 적어 둔 신고는 행정청이 수리해야 효력이 생기고 내부 절차 규정은 제외됩니다.","법률이 위임을 허용하고 있지 아니한 경우에도 행정관청의 내부적인 사무처리의 편의를 도모하기 위하여 그의 보조기관 또는 하급행정관청으로 하여금 그의 권한을 사실상 행사하게 하는 것. 법적 근거가 필요 없다.":"내부위임은 법률이 허용하지 않아도 내부 사무 편의를 위해 보조기관에게 권한을 사실상 행사하게 하는 것이며 법적 근거가 필요 없습니다.","법률행위적 행정행위: 명령적 행위(하명·허가·면제)와 형성적 행위(특허·인가·대리). 준법률행위적 행정행위: 확인·공증·통지·수리.":"행정행위는 의사표시를 요소로 하는 법률행위적 행위와 법이 효과를 붙이는 준법률행위적 행위로 크게 나눕니다.","법무부에 본부심의회, 국방부에 군인·군무원 손해에 대한 특별심의회, 지구심의회를 둔다. 지구심의회는 배상신청을 받으면 4주일 이내에 배상결정을 하고, 결정을 한 날부터 1주일 이내에 결정정본을 신청인에게 송달한다.":"배상심의회는 본부와 특별과 지구로 구성되고 지구심의회는 신청을 받아 4주일 안에 결정하고 1주일 안에 정본을 보냅니다.","법원 또는 군사법원의 재판에 의하거나 그 집행으로 행하는 사항, 헌법재판소의 심판을 거쳐 행하는 사항, 각급 선거관리위원회의 의결을 거쳐 행하는 사항.":"재판과 그 집행, 헌법재판소 심판, 선거관리위원회 의결을 거치는 사항은 별도 절차가 있어 제외됩니다.","법원은 소송의 결과에 따라 권리 또는 이익의 침해를 받을 제3자가 있는 경우 당사자 또는 제3자의 신청 또는 직권에 의하여 그 제3자를 소송에 참가시킬 수 있다. 다른 행정청을 참가시킬 필요가 있다고 인정할 때에도 같다.":"소송 결과로 권익이 침해될 제삼자와 필요한 다른 행정청은 신청이나 직권으로 소송에 참가시킬 수 있습니다.","법원은 처분의 변경이 있는 경우 원고의 신청에 의하여 청구의 취지 또는 원인의 변경을 허가할 수 있다. 신청은 처분의 변경이 있음을 안 날부터 60일 이내에 하여야 한다.":"소송 중 처분이 바뀌면 원고가 변경된 처분에 맞게 청구를 바꾸도록 허가받을 수 있고 신청은 안 날부터 60일 안에 해야 합니다.","법원은 취소소송을 당사자소송 또는 취소소송 외의 항고소송으로 변경하는 것이 상당하다고 인정할 때 청구의 기초에 변경이 없는 한 사실심 변론종결시까지 원고의 신청에 의하여 허가할 수 있다.":"소송 종류를 잘못 골랐다면 청구의 기초가 같은 한 변론종결 때까지 원고의 신청으로 다른 종류의 소송으로 바꿀 수 있습니다.","법원은 필요하다고 인정할 때 직권으로 증거조사를 할 수 있고, 당사자가 주장하지 아니한 사실에 대하여도 판단할 수 있다.":"법원은 필요하면 직권으로 증거를 조사하고 당사자가 주장하지 않은 사실도 판단할 수 있는 직권심리를 합니다.","법원이 구체적 규범통제를 통해 위헌·위법으로 선언할 심판대상은 원칙적으로 재판의 전제성이 인정되는 조항에 한정된다. 해당 규정 전체가 아니다.":"법원이 위헌 위법을 판단하는 대상은 재판의 전제가 되는 그 조항이지 규정 전체가 아닙니다.","법인·단체 또는 개인의 경영상·영업상 비밀에 관한 사항으로서 공개될 경우 정당한 이익을 현저히 해칠 우려가 있는 정보. 위해로부터 사람의 생명·신체·건강을 보호하기 위해 공개할 필요가 있는 정보, 위법·부당한 사업활동으로부터 국민의 재산 또는 생활을 보호하기 위해 공개할 필요가 있는 정보는 제외.":"경영상 영업상 비밀로 공개하면 정당한 이익을 해치는 정보는 비공개이나 생명과 건강 또는 재산을 지키기 위해 필요하면 공개합니다.","법인의 대표자, 법인 또는 개인의 대리인·사용인 및 그 밖의 종업원이 업무에 관하여 법률상의 의무를 위반한 때에는 법인 또는 그 개인에게 과태료를 부과한다.":"법인의 대표자나 종업원이 업무 중 의무를 위반하면 그 법인이나 개인에게 과태료를 부과합니다.","법인의 대표자·대리인·사용인·종업원이 업무에 관하여 위반행위를 한 경우 행위자 외에 법인 또는 개인에게도 벌금형을 과하는 규정이다.":"양벌규정은 법인의 직원이 업무 중 위반하면 행위자 본인뿐 아니라 법인이나 사업주에게도 벌금을 물리는 규정입니다.","법인이 거래하는 금융기관의 계좌번호에 관한 정보는 법인의 영업상 비밀에 관한 사항으로서 비공개 대상 정보에 해당한다.":"법인의 거래 금융기관 계좌번호는 영업상 비밀에 해당해 비공개 대상 정보로 분류됩니다.","법정사실의 발생으로 법상 당연히 대리관계가 성립하는 것(협의의 법정대리), 또는 일정한 자가 대리자를 지정하는 지정대리가 있다.":"법정대리는 일정한 사실이 생기면 당연히 대리가 성립하는 협의의 법정대리와 일정한 자가 대리자를 지정하는 지정대리로 나뉩니다.","법정사실이 발생하여 당연히 특정한 자에게 대리권이 부여되는 것은 협의의 법정대리이고, 지정대리는 법정사실 발생 시 일정한 자가 대리자를 지정하는 것이다.":"사실이 생기면 자동으로 대리권이 정해지는 것이 협의의 법정대리이고 대리자를 따로 지정하는 것이 지정대리입니다.","법제처는 국무총리 소속 행정기관이다. 국무총리 소속 기관(현행 정부조직법): 기획예산처, 인사혁신처, 법제처, 식품의약품안전처, 국가데이터처, 지식재산처 (국무조정실, 국무총리비서실 포함).":"법제처는 국무총리 소속이며 총리 아래에는 인사혁신처와 식품의약품안전처 등이 함께 설치되어 있습니다.","병무청장이 병역법에 따라 병역의무 기피자의 인적사항을 인터넷 홈페이지에 공개하는 결정은 항고소송의 대상이 되는 행정처분이다.":"병역의무 기피자의 인적사항을 공개하는 결정은 당사자의 권익에 직접 영향을 주어 항고소송의 대상인 처분입니다.","병역법상 공익근무요원은 군인에 해당하지 아니하여 이중배상이 금지되는 자에 속하지 않는다.":"공익근무요원은 군인이 아니라서 이중배상 금지 대상에서 빠지므로 국가배상을 청구할 수 있습니다.","병역법에 따른 징집·소집, 외국인의 출입국·난민인정·귀화, 공무원 인사 관계 법령에 따른 징계와 그 밖의 처분, 이해 조정을 목적으로 하는 법령에 따른 알선·조정·중재·재정 또는 그 밖의 처분 등 성질상 행정절차를 거치기 곤란하거나 거칠 필요가 없다고 인정되는 사항과 행정절차에 준하는 절차를 거친 사항으로서 대통령령으로 정하는 사항.":"징집, 출입국, 징계 등 성질상 절차를 거치기 곤란하거나 불필요한 사항과 준하는 절차를 거친 사항은 적용에서 제외됩니다.","병역의무 기피자 인적사항 공개 결정은 항고소송의 대상이 되는 처분이다.":"병역의무 기피자 명단 공개는 당사자의 명예 등 권익에 직접 영향을 주어 항고소송으로 다툴 수 있는 처분입니다.","보건복지부 고시인 약제급여·비급여목록 및 급여상한금액표에 대해서는 취소소송으로 다툴 수 있다. 제약회사는 위 고시 중 자기가 제조·공급하는 약제의 상한금액 인하 부분의 취소를 구할 원고적격이 있다.":"약제 상한금액 고시는 처분이어서 취소소송이 가능하고 상한금액이 낮아진 약을 만드는 제약회사에 원고적격이 있습니다.","보상금의 증감에 관한 소송에서 토지소유자 또는 관계인이 제기할 때에는 사업시행자를, 사업시행자가 제기할 때에는 토지소유자 또는 관계인을 피고로 한다.":"보상금의 많고 적음을 다투는 소송은 위원회가 아니라 상대방 당사자를 피고로 삼아 제기합니다.","보상액을 산정할 때 해당 공익사업으로 인하여 토지등의 가격이 변동되었을 때에는 이를 고려하지 아니한다.":"공익사업 때문에 오르거나 내린 땅값은 보상액을 정할 때 반영하지 않아 개발이익을 배제합니다.","보상액의 산정은 협의에 의한 경우 협의 성립 당시의 가격을, 재결에 의한 경우 수용 또는 사용의 재결 당시의 가격을 기준으로 한다. 수용개시 당시 가격이 아니다.":"보상액은 협의로 정하면 협의 성립 때 가격으로, 재결로 정하면 재결 당시 가격으로 정하며 수용 개시 때는 기준이 아닙니다.","보존용재산: 법령이나 그 밖의 필요에 따라 국가가 보존하는 재산. 행정재산에 속한다. 일반재산: 행정재산 외의 모든 국유재산.":"보존용재산은 국가가 보존하는 재산으로 행정재산에 들고 행정재산이 아닌 나머지 국유재산이 모두 일반재산입니다.","본래 행위로서는 무효이나 다른 행정행위의 요건을 갖춘 경우 그 행위로 인정하는 것.":"전환은 원래 행위로는 무효이지만 다른 행정행위의 요건을 갖췄다면 그 행위로서 효력을 인정하는 것입니다.","본인의 의사에 반한 불리한 처분에 관한 행정소송은 소청심사위원회의 심사·결정을 거치지 아니하면 제기할 수 없다(필요적 전치). 대통령의 처분의 경우 소속 장관을 피고로 한다.":"불리한 처분에 대한 행정소송은 소청심사를 먼저 거쳐야 하는 필요적 전치이고 대통령의 처분이면 소속 장관이 피고입니다.","부과·징수 주체, 부과 사유, 상한액, 가산금을 징수하려는 경우 그 사항, 과징금 또는 가산금 체납 시 강제징수를 하려는 경우 그 사항.":"과징금의 근거 법률에는 부과 주체와 사유와 상한액과 가산금과 체납 시 강제징수 여부가 분명히 적혀야 합니다.","부과·징수 주체, 부과 요건, 부과 금액, 부과 금액 산정기준, 연간 부과 횟수나 횟수의 상한. 제4호·제5호는 입법목적을 훼손할 우려가 큰 경우로서 대통령령으로 정하는 경우 제외.":"이행강제금은 부과 주체와 요건과 금액과 산정 기준과 연간 횟수를 근거 법률에 명확히 정해야 합니다.","부관을 붙일 수 있는 처분은 처분을 한 후에도 부관을 새로 붙이거나 종전의 부관을 변경할 수 있다. 사유는 3가지다.":"부관을 붙일 수 있는 처분은 한 뒤에도 사후부관을 붙이거나 바꿀 수 있고 허용 사유는 세 가지입니다.","부담 외의 부관(조건·기한 등)은 독립하여 쟁송할 수 없는 것이 원칙이다. 부담만 독립쟁송이 가능하다.":"조건과 기한 같은 부담 외의 부관은 처분과 분리해 다툴 수 없고 부담만 따로 쟁송할 수 있습니다.","부담은 그 자체로서 독립하여 행정쟁송의 대상이 될 수 있다.":"부담은 독립된 처분의 성질이 있어 주된 처분과 별개로 소송이나 심판으로 다툴 수 있습니다.","부담을 불이행한 것만으로는 주된 행정행위의 효력이 소멸하지 않는다. 철회 사유가 되고 강제집행의 대상이 된다.":"부담을 이행하지 않아도 주된 처분이 저절로 사라지지는 않고 철회 사유가 되며 강제집행도 가능합니다.","부령 형식의 제재적 처분기준은 행정청 내부의 사무처리준칙이다(판례). 대통령령 형식의 처분기준은 법규명령으로 보되 그 수치는 최고한도를 정한 것으로 본다.":"부령 형태의 처분기준은 내부 지침일 뿐이고 대통령령 형태는 법규명령이지만 그 수치는 상한선으로만 봅니다.","부작위에 의한 국가배상책임의 성립요건인 직무상 작위의무는 조리에 의해서도 성립할 수 있다.":"공무원이 해야 할 작위의무가 명문 법령에 없어도 조리상 인정되면 부작위로 인한 국가배상책임이 성립할 수 있습니다.","불가변력이 있는 행정행위라도 쟁송기간이 경과하지 않는 한 행정쟁송에 의한 취소가 가능하다.":"불가변력은 행정청을 묶을 뿐이어서 불복 기간 안이라면 상대방이 쟁송으로 취소를 구할 수 있습니다.","불가쟁력은 원칙적으로 모든 행정행위에 인정된다. 불가변력은 준사법적 행위(행정심판 재결 등) 등 일부 행정행위에 인정된다. 불가변력은 당해 행정행위에 대해서만 인정된다. 동종의 행정행위라도 대상을 달리하면 인정되지 않는다.":"불가쟁력은 모든 행정행위에 생기지만 불가변력은 재결 같은 일부에만 생기며 그 행위에 한정됩니다.","불가쟁력은 쟁송으로 다툴 수 없게 되는 형식적 확정력일 뿐 기판력과 같은 실질적 확정력이 아니다. 불복기간이 지나 확정되어도 처분의 기초가 된 사실관계나 법률적 판단이 확정되는 것이 아니고, 당사자나 법원이 이에 기속되지 않는다.":"불가쟁력은 절차상 다툴 수 없다는 뜻일 뿐이라 처분의 내용이 옳다고 확정되는 기판력과는 다릅니다.","불특정 다수가 이용하는 목욕실, 화장실, 발한실, 탈의실 등 사생활을 현저히 침해할 우려가 있는 장소의 내부를 볼 수 있도록 고정형 영상정보처리기기를 설치·운영하여서는 아니 된다. 교도소·정신보건시설 등 대통령령으로 정하는 시설은 예외다.":"목욕실과 화장실처럼 사생활 침해가 큰 곳은 내부를 찍는 카메라를 둘 수 없고 교도소 등 일부 시설만 예외입니다.","비공개 결정 또는 부분 공개 결정에 불복이 있거나 정보공개 청구 후 20일이 경과하도록 결정이 없는 때, 결정 통지를 받은 날 또는 청구 후 20일이 경과한 날부터 30일 이내에 해당 공공기관에 문서로 이의신청을 할 수 있다.":"비공개 결정에 불복하거나 20일이 지나도록 결정이 없으면 그날부터 30일 안에 해당 기관에 서면으로 이의신청을 합니다.","비공개 결정에 대한 불복절차로 이의신청, 행정심판, 행정소송이 있다.":"비공개 결정에 불복하려면 기관 안의 이의신청과 행정심판과 행정소송의 세 가지 수단이 있습니다.","비공개 결정을 한 경우 지체 없이 문서로 통지하고, 어느 호에 해당하는 비공개 대상인지를 포함한 비공개 이유와 불복의 방법 및 절차를 구체적으로 밝혀야 한다.":"비공개로 정하면 서면으로 알리면서 어느 호의 비공개 대상인지와 불복 방법과 절차도 구체적으로 밝혀야 합니다.","비공개 사유가 기간의 경과 등으로 없어진 경우에는 그 정보를 공개 대상으로 하여야 한다.":"비공개해야 했던 이유가 시간이 흘러 사라졌다면 그 정보는 이제 공개 대상으로 바뀝니다.","비상시 또는 위험이 절박한 경우 급속한 실시를 요하여 계고·영장 절차를 취할 여유가 없을 때에는 그 절차를 거치지 않고 대집행을 할 수 있다.":"위험이 절박해 급히 해야 하면 계고와 영장 절차를 밟을 여유가 없으므로 생략하고 곧바로 대집행할 수 있습니다.","비용을 징수하였을 때 그 징수금은 사무비의 소속에 따라 국고 또는 지방자치단체의 수입으로 한다.":"거둔 대집행 비용은 그 사무를 맡은 곳이 국가인지 지자체인지에 따라 국고나 지자체 수입이 됩니다.","사립대학교를 포함한 각급 학교는 대통령령으로 정하는 기관으로서 정보공개의무를 지는 공공기관에 해당한다.":"사립대학교를 포함한 각급 학교도 대통령령이 정한 기관이라 정보공개 의무를 지는 공공기관에 속합니다.","사망 당시의 월급액이나 월실수입액 또는 평균임금에 장래의 취업가능기간을 곱한 금액 및 대통령령으로 정하는 장례비.":"사망 배상은 사망 당시 소득에 앞으로 일할 수 있었던 기간을 곱한 금액에 장례비를 더해 정합니다.","사법상 계약에는 계약자유의 원칙이 적용된다.":"사법상 계약은 당사자가 자유롭게 내용을 정할 수 있다는 계약자유의 원칙이 적용됩니다.","사상·신념, 노동조합·정당의 가입·탈퇴, 정치적 견해, 건강, 성생활 등에 관한 정보. 정보주체에게 알리고 다른 개인정보 처리 동의와 별도로 동의를 받거나 법령에서 처리를 요구·허용하는 경우에만 처리할 수 있다.":"사상과 건강 등 민감정보는 알리고 다른 동의와 별도로 동의를 받거나 법령이 요구하거나 허용하는 경우에만 처리합니다.","사업시행자가 이의신청에 따라 늘어난 보상금을 지급할 때는 재결서 정본을 받은 날부터 30일 이내에 지급하여야 하며, 사업시행자가 행정소송을 제기하기 전에 늘어난 보상금을 공탁하여야 한다.":"이의신청으로 보상금이 늘면 정본을 받은 날부터 30일 안에 지급하고 사업시행자가 소송을 내기 전에 공탁해야 합니다.","사업시행자는 수용 또는 사용의 개시일까지 관할 토지수용위원회가 재결한 보상금을 지급하거나 공탁하여야 하며, 하지 않으면 재결은 효력을 상실하고 사업시행자는 손실을 보상하여야 한다.":"개시일까지 재결된 보상금을 지급하거나 공탁하지 않으면 재결이 효력을 잃고 사업시행자가 손실을 보상해야 합니다.","사업시행자는 수용의 개시일에 토지나 물건의 소유권을 취득하며, 그 토지나 물건에 관한 다른 권리는 이와 동시에 소멸한다. 사용의 개시일에는 사용권을 취득하며 다른 권리는 사용 기간 중에는 행사하지 못한다. 재결로 인정된 권리는 소멸되거나 행사가 정지되지 않는다.":"수용 개시일에 소유권을 얻고 다른 권리는 사라지며 사용의 경우는 사용 기간 중 다른 권리의 행사만 막힙니다.","사업시행자는 주거용 건축물을 제공함으로써 생활의 근거를 상실하게 되는 자(이주대책대상자)를 위하여 이주대책을 수립·실시하거나 이주정착금을 지급하여야 한다. 이주대책을 수립하려면 미리 관할 지방자치단체의 장과 협의하여야 한다.":"집을 내놓아 생활 터전을 잃는 사람에게 이주대책을 세우거나 이주정착금을 주어야 하고 대책 수립 전 지자체장과 협의합니다.","사업시행자는 토지등을 수용하거나 사용하려면 국토교통부장관의 사업인정을 받아야 한다.":"사업시행자가 남의 토지를 수용하려면 먼저 국토교통부장관에게 공익사업으로 인정받는 사업인정이 있어야 합니다.","사업시행자와 토지소유자 및 관계인 간 협의가 성립되어 토지수용위원회의 협의 성립 확인을 받으면 재결로 보며, 그 확인된 협의의 성립이나 내용을 다툴 수 없다.":"협의가 성립해 위원회의 확인을 받으면 재결처럼 취급되어 그 협의의 성립과 내용을 더는 다투지 못합니다.","사업인정고시가 된 날부터 1년 이내에 재결신청을 하지 아니하면 사업인정고시일부터 1년이 되는 날의 다음 날에 사업인정은 효력을 상실한다. 이때 사업시행자는 토지소유자나 관계인이 입은 손실을 보상하여야 한다.":"사업인정고시일부터 1년 안에 재결신청을 하지 않으면 다음 날 사업인정이 효력을 잃고 사업시행자가 손실을 보상합니다.","사업인정고시 후 사업의 전부 또는 일부를 폐지·변경함으로써 수용·사용할 필요가 없게 된 때에는 사업시행자는 지체 없이 시·도지사에게 신고하고 토지소유자 및 관계인에게 통지하여야 하며, 손실을 보상하여야 한다.":"사업을 폐지하거나 변경해 수용할 필요가 없어지면 시도지사에게 신고하고 소유자에게 알리며 그동안의 손실을 보상합니다.","사업인정고시 후 협의가 성립되지 아니하였을 때 토지소유자와 관계인은 서면으로 사업시행자에게 재결 신청을 청구할 수 있다. 사업시행자는 청구를 받은 날부터 60일 이내에 재결을 신청하여야 하고, 기간을 넘기면 지연된 기간에 대해 법정이율로 산정한 금액을 재결한 보상금에 가산하여 지급한다.":"협의가 안 되면 토지소유자도 재결 신청을 청구할 수 있고 사업시행자가 60일을 넘기면 지연 기간만큼 법정이율로 가산합니다.","사업인정에 불가쟁력이 발생한 경우 사업인정이 당연무효가 아닌 한 사업인정의 하자를 이유로 수용재결의 취소를 구할 수 없다.":"사업인정을 다툴 수 있는 기간이 지났다면 당연무효가 아닌 한 사업인정의 하자를 이유로 수용재결을 취소해 달라고 할 수 없습니다.","사업인정은 고시한 날부터 그 효력이 발생한다. 사업인정은 항고소송의 대상이 되는 처분이다.":"사업인정은 고시한 날부터 효력이 생기며 토지소유자에게 영향을 주는 처분이라 항고소송으로 다툴 수 있습니다.","사업인정처분이 당연무효이면 그것이 유효함을 전제로 이루어진 수용재결도 무효이다.":"사업인정이 무효라면 그 위에 세워진 수용재결도 바탕이 사라져 함께 무효가 됩니다.","사업인정 후 취득의 경우 공시지가는 사업인정고시일 전의 시점을 공시기준일로 하는 공시지가로서 협의 성립 또는 재결 당시 공시된 공시지가 중 사업인정고시일과 가장 가까운 시점에 공시된 것으로 한다.":"사업인정 후 취득이라면 사업인정고시일 전을 기준일로 하여 고시일과 가장 가까운 시점에 공시된 공시지가를 씁니다.","사용허가나 대부계약 없이 국유재산을 사용·수익하거나 점유한 자(허가·대부 기간 종료 후 계속 점유자 포함)에게 사용료나 대부료의 100분의 120에 상당하는 금액을 부과한다.":"허가나 계약 없이 국유재산을 쓰거나 기간이 끝난 뒤에도 계속 점유한 사람에게는 사용료나 대부료의 100분의 120을 부과합니다.","사용허가를 받은 자는 그 재산을 다른 사람에게 사용·수익하게 하여서는 아니 된다. 기부자·상속인 등의 경우 등 중앙관서의 장의 승인을 받은 경우는 예외.":"사용허가를 받은 사람이 재산을 남에게 쓰게 하는 전대는 금지되고 중앙관서의 장의 승인을 받은 경우에만 예외입니다.","사용허가를 취소하거나 철회하려는 경우 청문을 하여야 한다.":"사용허가를 취소하거나 철회하면 상대방의 이익에 큰 영향을 주므로 반드시 청문을 거쳐야 합니다.","사인의 공법행위에는 의사표시 하자에 관한 민법 규정이 당연히 적용되지는 않는다. 행위의 성질에 따라 개별적으로 판단한다.":"사인이 공법상 하는 행위에는 민법의 착오나 사기 규정이 자동으로 적용되지 않고 성질을 보아 가려냅니다.","사인의 공법행위의 철회·보정은 행정청의 처분이 있기 전까지 가능하다. 신청의 성질상 불가능하거나 특별한 규정이 있으면 예외다.":"신청의 철회와 보정은 행정청이 처분하기 전까지 가능하며 신청의 성질상 불가능하면 예외입니다.","사인의 신청을 받은 행정청은 접수를 보류·거부하거나 부당하게 되돌려 보내서는 안 되고, 접수한 경우 접수증을 주어야 한다.":"행정청은 신청을 일단 접수해야 하고 접수를 미루거나 부당하게 돌려보낼 수 없으며 접수증을 내줍니다.","사인이 행정청에 제3자에 대한 행정권 발동을 요구할 수 있는 권리다. 재량이 영(0)으로 수축되는 경우 인정된다.":"남에게 행정권을 발동해 달라고 요구하는 권리이며 재량이 영으로 줄어 하나의 선택만 남을 때 인정됩니다.","사전통지를 하지 아니하는 경우 처분을 할 때 당사자등에게 통지하지 아니한 사유를 알려야 한다. 신속한 처분이 필요하면 처분 후 알릴 수 있다.":"사전통지를 생략했다면 처분할 때 생략한 이유를 알려야 하며 서둘러야 하면 처분 후에 알릴 수 있습니다.","사정이 변경되어 부관을 새로 붙이거나 종전의 부관을 변경하지 아니하면 해당 처분의 목적을 달성할 수 없다고 인정되는 경우.":"사정이 바뀌어 부관을 바꾸지 않으면 처분 목적을 이룰 수 없을 때 사후부관이 허용됩니다.","사정재결을 할 때 청구인에 대하여 상당한 구제방법을 취하거나 취할 것을 피청구인에게 명할 수 있다. 사정재결은 무효등확인심판에는 적용하지 아니한다.":"사정재결을 하면서 청구인에게 상당한 구제 방법을 마련하게 할 수 있고 무효등확인심판에는 사정재결이 없습니다.","사정판결을 하려면 미리 원고가 입게 될 손해의 정도와 배상방법 그 밖의 사정을 조사하여야 하고, 원고는 피고 행정청이 속하는 국가 또는 공공단체를 상대로 손해배상, 제해시설의 설치 등 구제방법의 청구를 병합하여 제기할 수 있다. 사정판결의 경우 소송비용은 피고가 부담한다.":"사정판결 전에 원고의 손해와 배상방법을 조사하고 원고는 손해배상 같은 구제청구를 병합할 수 있으며 비용은 피고가 부담합니다.","사회적으로 유해한 행위를 원칙적으로 금지(억제적 금지)하고 예외적으로 허용하는 행위. 재량행위다.":"예외적 허가는 해로운 행위를 원칙적으로 막아 두고 예외로만 허용하므로 행정청에 재량이 있습니다.","산업재해보상보험법상 연금지급결정을 취소하는 처분이 적법하다고 하여 그에 터 잡은 징수처분이 반드시 적법한 것은 아니다.":"연금지급결정 취소가 적법해도 그에 기초한 징수처분은 별도의 요건을 따로 갖춰야 적법해집니다.","살아 있는 개인에 관한 정보로서 개인을 알아볼 수 있는 정보, 다른 정보와 쉽게 결합하여 알아볼 수 있는 정보, 이를 가명처리한 가명정보.":"개인정보에는 바로 개인을 알아볼 수 있는 정보와 다른 정보와 쉽게 결합해 알아볼 수 있는 정보와 가명정보가 포함됩니다.","상급관청은 직권에 의해 하급관청의 위법·부당한 행위의 취소를 명할 수 있다(감독권).":"상급관청은 따로 청구가 없어도 하급관청의 위법하거나 부당한 행위를 직권으로 취소하라고 명할 수 있습니다.","상급관청의 지휘·감독권에는 감시권, 인가권, 훈령권, 취소·정지권, 주관쟁의결정권이 있다.":"감시와 인가와 훈령과 취소정지와 주관쟁의결정이 상급관청의 지휘감독 수단으로 열거됩니다.","상급관청이 하급관청의 권한행사를 지휘하기 위하여 발하는 명령.":"훈령은 상급관청이 하급관청의 권한 행사를 지휘하려고 내리는 명령으로 일반 국민이 대상이 아닙니다.","상급행정기관의 소속 공무원에 대한 업무처리지침은 일반적으로 행정조직 내부에서만 효력을 가진다.":"상급기관이 소속 공무원에게 내린 업무지침은 조직 내부에서만 통하고 국민에게는 효력이 없습니다.","상급행정기관의 하급행정기관에 대한 승인·동의·지시는 국민의 권리·의무에 직접 영향을 미치지 않는 한 행정처분이 아니다.":"행정기관 내부에서 오가는 승인과 동의와 지시는 국민의 권리에 직접 영향이 없는 한 처분이 아닙니다.","상당한 이행기한을 정하여 그 기한까지 이행되지 아니할 때에는 대집행을 한다는 뜻을 미리 문서로 계고하여야 한다. 의무의 성질·내용 등을 고려하여 사회통념상 필요한 기간이 확보되도록 하여야 한다.":"대집행의 첫 단계로 상당한 기한을 주고 그 기한까지 이행하지 않으면 대집행하겠다는 뜻을 문서로 미리 알려야 합니다.","상위법령과 결합하여 대외적 구속력이 있는 법규명령으로서의 효력을 가진다. 「장기요양급여 제공기준 및 급여비용 산정방법 등에 관한 고시」는 외부적 구속효가 인정된다.":"상위법령의 위임을 받아 내용을 보충하는 행정규칙은 상위법령과 하나로 묶여 법규명령처럼 국민을 구속합니다.","새로운 법령등은 특별한 규정이 있는 경우를 제외하고는 그 효력 발생 전에 완성되거나 종결된 사실관계 또는 법률관계에 대해서는 적용되지 아니한다.":"새 법은 시행되기 전에 이미 끝난 일에는 적용하지 않는다는 소급적용 금지의 원칙입니다.","생명·신체에 대한 침해와 물건의 멸실·훼손 외의 손해는 불법행위와 상당한 인과관계가 있는 범위에서 배상한다.":"그 밖의 손해는 불법행위와 상당한 인과관계가 인정되는 범위까지만 배상합니다.","생명·신체의 침해로 인한 국가배상을 받을 권리는 양도하거나 압류하지 못한다.":"생명이나 신체 피해에 대한 배상청구권은 생활 보장을 위해 남에게 넘기거나 압류하지 못하게 막아 둡니다.","서울시립무용단 단원의 해촉에 관한 소송은 공법관계(공법상 당사자소송)다.":"시립무용단 단원 해촉 관련 소송은 공법상 근무 관계 문제여서 공법상 당사자소송으로 다툽니다.","선택적으로 동의할 수 있는 사항에 동의하지 않는다는 이유로 재화 또는 서비스 제공을 거부하여서는 아니 된다.":"필수가 아닌 선택 사항에 동의하지 않았다고 해서 상품이나 서비스 제공을 거절하면 안 됩니다.","선행행위에는 취소사유인 하자가 존재해야 한다. 선행행위가 무효이면 승계 문제가 아니라 당연히 후행행위도 무효다.":"앞선 행위의 하자는 취소 사유 정도여야 하고 무효라면 승계가 아니라 뒤 행위도 곧바로 무효입니다.","선행행위에 불가쟁력이 발생해야 한다. 후행행위에 불가변력이 발생해야 하는 것은 요건이 아니다.":"앞선 행위는 이미 불복 기간이 지나 다툴 수 없어야 하고 뒤따르는 행위의 불가변력은 요건이 아닙니다.","선행행위와 후행행위가 서로 결합하여 하나의 법률효과를 목적으로 하는 경우에는 하자가 승계된다. 별개의 효과를 목적으로 하면 승계되지 않는다(원칙). 예외적으로 수인한도·예측가능성 등을 고려해 승계를 인정한다.":"두 행위가 하나의 법률효과를 향해 결합하면 하자가 승계되고 별개의 효과를 노리면 원칙적으로 승계되지 않습니다.","선행행위의 하자를 이유로 후행행위를 다툴 수 있는 경우: 선행행위와 후행행위가 모두 항고소송의 대상인 행정처분이어야 한다.":"하자의 승계가 되려면 앞선 행위와 뒤따르는 행위가 모두 항고소송 대상인 처분이어야 합니다.","성명·주민등록번호 등 개인정보로서 공개될 경우 사생활의 비밀 또는 자유를 침해할 우려가 있다고 인정되는 정보. 법령에 따라 열람할 수 있는 정보, 공표 목적 정보로서 사생활을 부당하게 침해하지 않는 정보, 공개가 공익이나 개인의 권리구제를 위하여 필요하다고 인정되는 정보, 직무를 수행한 공무원의 성명·직위, 공익을 위해 필요한 경우 위탁·위촉 개인의 성명·직업은 제외.":"공개되면 사생활을 침해할 개인정보는 비공개이나 열람 가능 정보와 공익상 필요한 정보와 공무원의 성명과 직위 등은 예외입니다.","성실, 복종, 직장 이탈 금지, 친절·공정, 비밀 엄수, 청렴, 외국 정부의 영예 등 수령 시 대통령 허가, 품위 유지, 정치운동 금지, 집단행위 금지(사실상 노무 종사자 예외).":"공무원의 의무에는 성실과 복종과 직장 이탈 금지와 비밀 엄수와 청렴과 품위 유지와 정치운동 및 집단행위 금지 등이 있습니다.","소송 계속 중에 소송을 제기한 주민이 사망하거나 주민의 자격을 잃으면 소송절차는 중단된다. 감사 청구에 연대 서명한 다른 주민은 안 날부터 6개월 이내에 수계할 수 있고, 수계하지 않으면 소송절차는 종료된다.":"원고 주민이 사망하거나 자격을 잃으면 소송이 중단되고 다른 서명 주민이 6개월 안에 이어받지 않으면 종료됩니다.","소송은 해당 사유에 따른 날부터 90일 이내에 제기하여야 한다.":"주민소송은 제기 사유가 생긴 날부터 90일 안에 제기해야 합니다.","소청심사위원회가 소청 사건을 심사할 때 소청인 또는 대리인에게 진술 기회를 주어야 하며, 진술 기회를 주지 아니한 결정은 무효로 한다.":"소청인이나 대리인에게 진술할 기회를 줘야 하고 이를 주지 않고 한 결정은 무효가 됩니다.","소청심사위원회가 징계처분의 취소·변경을 구한 소청을 심사할 때에는 원징계처분보다 무거운 징계를 부과하는 결정을 하지 못한다.":"소청을 낸 사람이 오히려 더 무거운 징계를 받는 일이 없도록 원래 징계보다 무겁게 결정하지 못합니다.","소청심사위원회는 청구를 접수한 날부터 60일 이내에 결정하여야 하며, 불가피하면 의결로 30일을 연장할 수 있다.":"소청 결정은 접수한 날부터 60일이 기한이고 불가피하면 의결로 30일 더 늘릴 수 있습니다.","소청심사위원회의 결정은 그 이유를 구체적으로 밝힌 결정서로 하여야 한다.":"결정은 구체적인 이유를 적은 결정서로 해야 하며 이유 없이 결론만 알리는 것은 허용되지 않습니다.","소청심사위원회의 결정은 처분 행정청을 기속한다.":"소청심사위원회의 결정은 처분을 한 행정청이 그대로 따라야 하는 기속력이 있습니다.","손실보상은 다른 법률에 특별한 규정이 없으면 현금으로 지급한다. 개인별로 하여야 하며, 동일인 소유 토지등이 여러 개인 경우 요구가 있으면 일괄보상한다.":"보상은 원칙적으로 현금으로 개인별로 하되 한 사람이 여러 토지를 가졌다면 요구에 따라 일괄 보상합니다.","손실보상은 적법한 공권력 행사로 인한 특별한 희생에 대한 보상이고, 국가배상은 위법한 행위로 인한 손해의 배상이다.":"손실보상은 적법한 공권력 행사로 생긴 특별한 희생을 메우는 것이고 국가배상은 위법한 행위에 대한 책임이라는 점이 다릅니다.","손해배상 소송은 배상심의회에 배상신청을 하지 아니하고도 제기할 수 있다.":"배상심의회 신청은 선택이라서 이를 거치지 않고 바로 법원에 손해배상 소송을 제기할 수 있습니다.","손해의 원인에 대하여 책임을 질 자가 따로 있으면 국가나 지방자치단체는 그 자에게 구상할 수 있다.":"손해를 일으킨 원인에 따로 책임질 사람이 있으면 국가나 지자체가 배상한 뒤 그 사람에게 구상할 수 있습니다.","송달은 다른 법령등에 특별한 규정이 있는 경우를 제외하고는 해당 문서가 송달받을 자에게 도달됨으로써 효력이 발생한다(도달주의). 정보통신망 송달은 송달받을 자가 지정한 컴퓨터 등에 입력된 때 도달된 것으로 본다.":"송달은 문서가 상대에게 닿는 때 효력이 생기며 전자 송달은 지정한 컴퓨터에 기록된 순간 닿은 것으로 봅니다.","송달은 우편, 교부 또는 정보통신망 이용 등의 방법으로 하되, 송달받을 자의 주소·거소·영업소·사무소 또는 전자우편주소로 한다. 송달받을 자가 동의하는 경우에는 그를 만나는 장소에서 송달할 수 있다.":"송달은 우편이나 직접 교부 등으로 하며 받을 사람의 주소 등으로 보내고 동의하면 만나는 장소에서도 할 수 있습니다.","수사나 재판에 관여하게 되는 사항, 개인의 사생활을 침해할 우려가 있는 사항, 다른 기관에서 감사하였거나 감사 중인 사항(새로운 사항 발견·중요 사항 누락·주민소송 대상인 경우 제외), 동일한 사항에 대하여 주민소송이 진행 중이거나 판결이 확정된 사항.":"수사와 재판에 관여하는 사항과 사생활 침해 우려가 있는 사항과 이미 감사했거나 소송이 진행된 동일 사항은 감사청구에서 제외됩니다.","수상한 행동이나 주위 사정을 합리적으로 판단할 때 죄를 범하였거나 범하려 한다고 의심할 만한 상당한 이유가 있는 사람, 이미 행하여진 범죄나 행하여지려는 범죄행위에 관한 사실을 안다고 인정되는 사람.":"범죄를 저질렀거나 저지르려 한다고 의심할 상당한 이유가 있는 사람과 범죄 사실을 안다고 인정되는 사람이 불심검문 대상입니다.","수용에 의한 사업시행자의 토지소유권 취득은 법률의 규정에 의한 원시취득이다.":"수용은 종전 소유자의 권리를 넘겨받는 것이 아니라 법률로 새로 취득하는 것이라서 원시취득에 해당합니다.","수용재결에 대한 취소소송의 제기는 사업의 진행 및 토지의 수용 또는 사용을 정지시키지 아니한다.":"수용재결을 취소해 달라고 소송을 내도 사업 진행과 토지 수용은 멈추지 않는 집행부정지 원칙이 적용됩니다.","수용재결에 불복할 때 이의신청을 거치지 않고도 행정소송을 제기할 수 있다. 이의신청은 필수적 전심절차가 아니다(임의적).":"이의신청은 선택이라서 수용재결에 불복하는 사람은 이를 거치지 않고 바로 행정소송을 제기할 수 있습니다.","수용재결은 행정심판의 재결이 아니라 원처분이다. 수용재결에 대한 이의신청에 대한 재결이 행정심판의 성질을 가진다.":"수용재결은 원래의 처분이고 그에 대한 이의신청을 판단한 재결이 행정심판의 성질을 가집니다.","수용하거나 사용할 토지의 구역 및 사용방법, 손실보상, 수용 또는 사용의 개시일과 기간, 그 밖에 법령에서 규정한 사항. 신청한 범위에서 재결하되 손실보상은 증액재결을 할 수 있다.":"재결은 토지 구역과 사용방법과 손실보상과 개시일을 정하며 신청 범위에서만 하되 손실보상은 신청보다 늘릴 수 있습니다.","수익적 처분의 직권취소는 당사자에게 권익을 제한하는 처분이므로 행정절차법상 사전통지·의견청취 절차를 거쳐야 한다.":"이익을 준 처분을 거두는 일도 당사자에게는 불이익이므로 미리 알리고 의견을 들어야 합니다.","수임사무의 처리에 관하여 위임기관은 수임기관에 대하여 사전승인을 받거나 협의를 할 것을 요구할 수 없다.":"위임했다고 해서 위임기관이 수임기관에게 사무 처리 전에 승인이나 협의를 하라고 요구하는 것은 허용되지 않습니다.","수임사무 처리에 관한 책임은 수임기관에 있으며 위임기관은 감독책임을 진다. 권한을 행사할 때에는 수임기관의 명의로 하여야 한다.":"수임사무의 책임은 수임기관이 지고 위임기관은 감독 책임을 지며 권한은 수임기관의 이름으로 행사합니다.","수집·이용 목적, 수집하려는 항목, 보유 및 이용 기간, 동의를 거부할 권리가 있다는 사실 및 거부에 따른 불이익이 있는 경우 그 내용.":"동의를 받을 때는 수집 목적과 항목과 보유 기간과 동의 거부권 및 불이익을 반드시 알려야 합니다.","시·도 소속 행정청, 시·도 관할구역의 시·군·자치구의 장·소속 행정청 또는 시·군·자치구 의회의 처분에 대한 심판청구는 시·도지사 소속으로 두는 행정심판위원회에서 심리·재결한다.":"시도 소속 행정청과 관할 시군구의 처분은 시도지사 소속의 행정심판위원회가 심리하고 재결합니다.","시험승진후보자명부에서의 삭제행위는 행정처분이 아니다.":"시험승진후보자명부에서 이름을 빼는 것은 공무원의 권리의무에 직접 영향을 주지 않아 처분이 아닙니다.","신고서가 기재사항에 흠이 없고 구비서류가 첨부되어 있으며 형식상 요건에 적합하면 접수기관에 도달된 때 신고 의무가 이행된 것으로 본다.":"신고서가 형식 요건을 갖추었다면 접수기관에 닿은 때 신고 의무가 이행된 것으로 보며 행정청의 수리가 필요 없습니다.","신고서의 기재사항에 흠이 없을 것, 필요한 구비서류가 첨부되어 있을 것, 그 밖에 법령등에 규정된 형식상의 요건에 적합할 것.":"신고서의 기재와 첨부서류와 형식 요건이 갖춰져 있으면 별도 수리 없이 신고가 효력을 냅니다.","신뢰보호원칙의 적용은 공익과 신뢰 이익을 비교형량해 판단한다. 신뢰를 보호하는 것이 공익 또는 제3자 이익을 현저히 해치면 적용되지 않는다.":"신뢰보호는 지키려는 신뢰 이익과 공익을 견주어 정하므로 신뢰를 지키다 공익을 크게 해치면 적용되지 않습니다.","신청 내용을 모두 그대로 인정하는 처분인 경우, 단순·반복적인 처분 또는 경미한 처분으로서 당사자가 그 이유를 명백히 알 수 있는 경우, 긴급히 처분을 할 필요가 있는 경우. 단순·반복적 처분이나 긴급 처분에서 이유 제시를 생략한 경우에도 처분 후 당사자가 요청하면 근거와 이유를 제시하여야 한다.":"신청을 그대로 인정하거나 이유가 명백한 경미한 처분이나 긴급 처분은 생략하되 처분 후 요청하면 이유를 밝힙니다.","신청에 구비서류의 미비 등 흠이 있는 경우 행정청은 보완에 필요한 상당한 기간을 정하여 지체 없이 보완을 요구하여야 하고, 보완하지 아니하면 그 이유를 구체적으로 밝혀 접수된 신청을 되돌려 보낼 수 있다.":"서류가 부족하면 보완 기간을 주고 요구하며 끝내 보완이 없으면 이유를 밝혀 신청을 돌려보낼 수 있습니다.","신청에 대한 거부처분은 사전통지의 대상이 아니다. 당사자의 권익을 제한하는 처분이 아니기 때문이다.":"신청을 거부하는 처분은 이미 가진 권익을 빼앗는 것이 아니라서 사전통지를 하지 않아도 됩니다.","신청에 대한 거부행위도 취소소송의 대상이 되는 처분이 될 수 있다.":"신청을 거부하는 행위도 국민의 법적 지위에 영향을 주면 처분이 되어 취소소송으로 다툴 수 있습니다.","신청에 흠이 있으면 행정청은 보완에 필요한 상당한 기간을 정해 지체 없이 보완을 요구하여야 한다.":"신청에 잘못이 있어도 바로 거부하지 않고 고칠 시간을 주어 보완을 요구해야 합니다.","신청인은 처분이 있기 전에는 신청의 내용을 보완·변경하거나 취하할 수 있다. 다른 법령등에 특별한 규정이 있거나 성질상 불가능하면 예외다.":"신청인은 처분이 나오기 전이라면 신청 내용을 고치거나 거둘 수 있고 성질상 안 되는 경우만 예외입니다.","실제에 요한 비용액과 납기일을 정하여 의무자에게 문서로 납부를 명하여야 한다. 대집행에 요한 비용은 국세징수법의 예에 의하여 징수할 수 있다.":"대집행에 실제로 든 비용과 납기를 정해 서면으로 납부를 명하며 내지 않으면 국세징수법의 예로 거둘 수 있습니다.","심사청구, 해양안전심판, 조세심판, 특허심판, 행정심판, 그 밖의 불복절차에 따른 사항.":"심사청구와 각종 심판 같은 불복 절차는 그 자체가 쟁송 절차라서 행정절차법이 적용되지 않습니다.","심신장애로 판단·행위 능력이 없는 자의 행위는 과태료를 부과하지 아니하고, 능력이 미약한 자의 행위는 과태료를 감경한다. 스스로 심신장애 상태를 일으킨 경우에는 적용하지 아니한다.":"심신장애로 판단 능력이 없으면 면제하고 미약하면 감경하되 스스로 그 상태를 만든 경우에는 적용하지 않습니다.","심판청구가 적법하지 아니하면 각하, 이유가 없다고 인정하면 기각, 취소심판이 이유 있으면 처분을 취소·변경하거나 변경할 것을 피청구인에게 명함(취소·변경·변경명령), 무효등확인심판이 이유 있으면 효력 유무 또는 존재 여부를 확인, 의무이행심판이 이유 있으면 지체 없이 신청에 따른 처분을 하거나 처분을 할 것을 피청구인에게 명함.":"재결은 부적법이면 각하, 이유 없으면 기각이고 이유 있으면 심판 종류에 따라 취소 변경, 확인, 처분 또는 처분명령을 합니다.","심판청구는 서면으로 하며 피청구인이나 위원회에 제출한다. 심판청구서가 피청구인이나 위원회에 제출되었을 때 행정심판이 청구된 것으로 본다.":"심판청구는 서면으로 하고 피청구인이나 위원회 둘 중 어디에 내도 제출된 때 청구한 것으로 인정됩니다.","심판청구는 처분의 효력이나 그 집행 또는 절차의 속행에 영향을 주지 아니한다(집행부정지 원칙).":"심판을 청구했다고 처분의 효력이나 집행이 멈추지는 않는 집행부정지가 원칙입니다.","심판청구를 인용하는 재결은 피청구인과 그 밖의 관계 행정청을 기속한다.":"청구를 받아들인 재결은 피청구인뿐 아니라 관련된 다른 행정청도 따라야 하는 기속력이 있습니다.","심판청구에 대한 재결이 있으면 그 재결 및 같은 처분 또는 부작위에 대하여 다시 행정심판을 청구할 수 없다.":"한 번 재결이 있으면 같은 처분에 대해 다시 행정심판을 청구하지 못하는 일사부재리가 적용됩니다.","어업권면허에 선행하는 우선순위결정은 강학상 확약에 불과하고 행정처분이 아니다.":"면허 전의 우선순위결정은 최종 처분이 아닌 확약일 뿐이므로 따로 처분으로 다툴 수 없습니다.","어업면허처분 중 면허의 유효기간(기한)만 취소하여 달라는 소송은 허용될 수 없다.":"기한은 부담이 아니어서 어업면허의 유효기간 부분만 따로 떼어 취소해 달라는 소송은 허용되지 않습니다.","여러 명의 청구인이 공동으로 심판청구를 할 때에는 청구인들 중에서 3명 이하의 선정대표자를 선정할 수 있다.":"청구인이 여럿이면 절차를 간편하게 하려고 그중 3명 이하를 선정대표자로 뽑아 대표하게 할 수 있습니다.","연령미달의 결격자가 타인의 이름으로 운전면허시험에 응시·합격하여 교부받은 운전면허는 당연무효가 아니다.":"결격자가 타인 이름으로 얻은 운전면허는 하자가 있어도 당연무효가 아니라 취소 대상으로 봅니다.","열람한 정보주체는 정정 또는 삭제를 요구할 수 있다. 다른 법령에서 그 개인정보가 수집 대상으로 명시되어 있는 경우에는 삭제를 요구할 수 없다.":"열람 후 틀린 정보는 정정이나 삭제를 요구할 수 있으나 다른 법령이 수집 대상으로 정한 정보는 삭제를 요구하지 못합니다.","영업을 폐업하거나 휴업함에 따른 손실은 영업이익과 시설의 이전비용 등을 고려하여 보상한다. 농업의 손실은 실제 경작자에게, 휴직·실직 근로자의 임금손실은 평균임금 등을 고려하여 보상한다.":"영업 손실은 영업이익과 이전비용으로, 농업 손실은 실제 경작자에게, 근로자의 임금 손실은 평균임금 등을 고려해 보상합니다.","영조물 설치·관리상의 하자는 공공의 목적에 공여된 영조물이 그 용도에 따라 통상 갖추어야 할 안전성을 갖추지 못한 상태에 있음을 말한다.":"공공시설이 본래 용도에 맞게 통상 갖춰야 할 안전성을 못 갖춘 상태가 영조물 설치와 관리의 하자입니다.","예산 및 기금에 관한 사무는 기획예산처장관이, 결산에 관한 사무는 재정경제부장관이 관장한다(현행). 2025 기출 당시에는 기획재정부장관이 예산·결산·기금 사무를 관장하는 것으로 출제되었다.":"현행 규정에서는 예산과 기금에 관한 사무를 기획예산처장관이, 결산에 관한 사무를 재정경제부장관이 나누어 맡습니다.","예산안편성지침은 3월 31일까지 통보, 예산요구서는 5월 31일까지 제출, 예산안은 회계연도 개시 120일 전까지 국회에 제출한다.":"지침은 3월 31일, 요구서는 5월 31일까지 정해진 순서로 거치고 국회 제출은 회계연도 개시 120일 전까지입니다.","예산은 예산총칙·세입세출예산·계속비·명시이월비 및 국고채무부담행위를 총칭한다.":"예산은 예산총칙과 세입세출예산과 계속비와 명시이월비와 국고채무부담행위를 모두 묶어 부르는 말입니다.","완성에 수년이 필요한 공사나 제조 및 연구개발사업은 총액과 연부액을 정하여 국회의 의결을 얻은 범위 안에서 지출한다. 지출 연한은 그 회계연도부터 5년 이내이며 예외적으로 10년 이내로 할 수 있다.":"수년이 걸리는 사업은 총액과 연부액에 대해 국회 의결을 받아 5년 이내에 쓰고 예외적으로 10년까지 늘릴 수 있습니다.","완전히 자동화된 시스템(인공지능 기술 적용 포함)으로 처분할 수 있다. 처분에 재량이 있는 경우는 제외한다.":"사람이 개입하지 않는 자동화 시스템으로도 처분할 수 있지만 재량이 있는 처분은 대상에서 빠집니다.","외교·국방·사법·국세, 물가·금융·수출입정책, 농산물 등 수급조절, 국가종합경제개발계획·국가하천·국유림·지정항만·고속국도 등, 근로기준·측량단위 등, 우편·철도 등, 고도의 기술이 필요한 검사·시험·연구·항공관리·기상행정·원자력개발.":"외교와 국방과 사법과 국세처럼 전국적 통일성이 필요한 국가사무는 원칙적으로 지방자치단체가 처리할 수 없습니다.","외국에 거주하거나 체류하는 자에 대한 기간 및 기한은 행정청이 우편이나 통신에 걸리는 일수를 고려하여 정하여야 한다.":"외국에 있는 사람에게는 우편이나 통신에 걸리는 시일을 감안해 기간과 기한을 정해야 합니다.","외국인이 피해자인 경우에는 해당 국가와 상호 보증이 있을 때에만 국가배상법이 적용된다.":"외국인은 그 나라에서도 우리 국민에게 배상해 주는 상호보증이 있을 때에만 국가배상법을 적용받습니다.","요건을 갖춘 신고서가 접수기관에 도달된 때 신고의무가 이행된다.":"수리가 필요 없는 신고는 요건에 맞는 신고서가 접수기관에 닿는 순간 신고 의무가 이행된 것입니다.","요양비, 요양기간 중 손실액의 휴업배상, 완치 후 장해가 있는 경우 노동력 상실 정도에 따른 장해배상.":"신체 피해는 치료비와 치료 중 손실에 대한 휴업배상과 완치 후 남은 장해의 노동력 상실 정도만큼의 장해배상으로 나눕니다.","원고가 피고를 잘못 지정한 때에는 법원은 원고의 신청에 의하여 결정으로 피고의 경정을 허가할 수 있다. 경정 결정이 있으면 새로운 피고에 대한 소송은 처음 소를 제기한 때 제기된 것으로 본다.":"피고를 잘못 지정하면 법원이 신청에 따라 피고를 고치도록 허가할 수 있고 새 피고에 대한 소는 처음 제기한 때 낸 것으로 봅니다.","원고의 청구가 이유 있다고 인정하는 경우에도 처분등을 취소하는 것이 현저히 공공복리에 적합하지 아니하다고 인정하는 때 법원은 청구를 기각할 수 있다. 이 경우 판결의 주문에서 처분등이 위법함을 명시하여야 한다. 처분이 위법한 것으로 인정되는 경우에도 공공복리를 위하여 청구가 기각될 수 있다.":"위법이 인정되어도 취소하면 현저히 공공복리에 맞지 않을 때 법원이 기각하는 사정판결이며 주문에 위법함을 밝힙니다.","위반사실 등의 공표는 법률로 정하는 바에 따른다. 공표 전에 객관적이고 타당한 증거와 근거가 있는지 확인하고, 미리 당사자에게 통지하여 의견제출 기회를 주어야 한다(긴급·의견청취 곤란·명백히 불필요·포기의 경우 예외). 공표된 내용이 사실과 다른 것으로 밝혀지거나 공표에 포함된 처분이 취소된 경우에는 정정하여 같은 방법으로 공표된 기간 이상 공표한다. 당사자가 원하지 않으면 공표하지 아니할 수 있다.":"위반사실 공표는 법률 근거와 증거 확인과 사전 통지가 필요하고 사실과 다르거나 처분이 취소되면 같은 방법으로 정정 공표합니다.","위반행위 후 법령등이 변경되어 그 행위가 위반행위에 해당하지 아니하게 되거나 제재처분 기준이 가벼워진 경우로서 해당 법령등에 특별한 규정이 없는 경우에는 변경된 법령등을 적용한다.":"위반 뒤 법이 바뀌어 위반이 아니게 되거나 제재가 가벼워졌다면 특별 규정이 없는 한 바뀐 법이 적용됩니다.","위법한 처분의 일부에 대해서도 취소할 수 있다.":"처분이 나눌 수 있는 내용이라면 위법한 일부만 골라 취소하는 것도 가능합니다.","위원 또는 배우자 등이 사건의 당사자이거나 공동 권리자·의무자인 경우, 당사자와 친족이거나 친족이었던 경우, 사건에 관하여 증언·감정을 한 경우, 당사자의 대리인으로 관여한 경우, 사건의 대상이 된 처분 또는 부작위에 관여한 경우.":"위원이 사건의 당사자이거나 친족이거나 증언과 감정과 대리인과 처분에 관여한 적이 있으면 그 사건의 심리에서 제척됩니다.","위원회(중앙 제외)는 위원장 1명을 포함하여 50명 이내의 위원으로 구성하며, 회의는 위원장과 위원장이 회의마다 지정하는 8명의 위원으로 구성한다. 구성원 과반수의 출석과 출석위원 과반수의 찬성으로 의결한다.":"중앙 외 위원회는 위원장 포함 50명 이내로 꾸리고 회의는 위원장과 지정된 8명이 하며 과반수 출석과 과반수 찬성으로 의결합니다.","위원회는 당사자의 권리 및 권한의 범위에서 당사자의 동의를 받아 심판청구의 신속하고 공정한 해결을 위하여 조정을 할 수 있다. 조정이 공공복리에 적합하지 아니하거나 처분의 성질에 반하는 경우에는 할 수 없다.":"위원회는 당사자 동의를 받아 분쟁을 조정할 수 있지만 공공복리에 맞지 않거나 처분의 성질에 반하면 할 수 없습니다.","위원회는 사정의 변경이 있는 경우 당사자의 신청에 의하여 간접강제 결정의 내용을 변경할 수 있다. 결정 전에 신청 상대방의 의견을 들어야 한다.":"사정이 바뀌면 당사자 신청으로 간접강제 결정을 바꿀 수 있으며 결정 전에 상대방의 의견을 들어야 합니다.","위원회는 심판청구의 대상이 되는 처분 또는 부작위 외의 사항에 대하여는 재결하지 못하고, 처분보다 청구인에게 불리한 재결을 하지 못한다.":"위원회는 청구 대상 밖의 사항을 판단하지 못하고 청구인을 처분보다 불리하게 만드는 재결도 할 수 없습니다.","위원회는 직권으로 또는 당사자의 신청에 따라 증거조사(신문, 문서·물건 제출 요구와 영치, 감정, 출입·검증)를 할 수 있다.":"위원회는 직권이나 신청에 따라 신문과 문서 제출 요구와 감정과 검증 같은 증거조사를 할 수 있습니다.","위원회는 피청구인이 제49조 제3항에도 불구하고 처분을 하지 아니하는 경우 당사자가 신청하면 기간을 정하여 서면으로 시정을 명하고, 그 기간에 이행하지 아니하면 직접 처분을 할 수 있다(의무이행심판의 처분명령재결). 처분의 성질이나 그 밖의 불가피한 사유로 직접 처분을 할 수 없는 경우는 제외.":"처분명령에도 행정청이 처분하지 않으면 위원회가 기한을 정해 시정을 명하고 그래도 안 하면 직접 처분할 수 있습니다.","위원회는 필요하면 당사자가 주장하지 아니한 사실에 대하여도 심리할 수 있다(직권심리).":"위원회는 당사자가 말하지 않은 사실도 필요하면 스스로 조사해 심리할 수 있는 직권심리의 권한이 있습니다.","위임(법정 위임)은 권한 자체가 수임자에게 이전된다. 대리는 권한 자체가 이전되지 않는다.":"위임은 권한이 수임자에게 옮겨 가지만 대리는 권한이 대리인에게 넘어가지 않고 본래 기관에 남는다는 점이 다릅니다.","위임기관은 수임기관의 수임사무 처리에 대하여 지휘·감독하고, 그 처리가 위법하거나 부당하다고 인정될 때에는 이를 취소하거나 정지시킬 수 있다.":"위임기관은 수임기관이 맡은 사무를 지휘하고 감독하며 위법하거나 부당하면 취소하거나 정지시킬 수 있습니다.","위임 또는 위탁을 받은 기관은 특히 필요한 경우 법령으로 정하는 바에 따라 일부를 보조기관 또는 하급행정기관에 재위임할 수 있다.":"위임을 받은 기관도 특히 필요하면 법령에 따라 그 일부를 다시 하급기관에 넘기는 재위임을 할 수 있습니다.","위임·위탁 전에 수임기관의 수임능력 여부를 점검하고 필요한 인력 및 예산을 이관하여야 한다. 위임기관은 수임사무 처리 상황을 수시로 감사할 수 있다.":"위임하기 전에 수임기관이 감당할 수 있는지 점검해 인력과 예산을 함께 넘기고 위임기관은 처리 상황을 수시로 감사할 수 있습니다.","위해가 임박한 때 위해 방지·피해자 구조를 위해 부득이하다고 인정하면 필요한 한도에서 타인의 토지·건물·배·차에 출입할 수 있다. 흥행장·여관·음식점·역 등 공개된 장소의 관리자는 영업시간에 출입 요구를 정당한 이유 없이 거절할 수 없다.":"위해가 임박해 부득이하면 필요한 한도에서 남의 건물에 출입할 수 있고 공개 장소의 관리자는 영업시간 중 요구를 거절하지 못합니다.","위해성 경찰장비는 필요한 최소한도에서 사용하여야 한다. 경찰장구는 현행범 등의 체포·도주 방지, 생명·신체의 방어 및 보호, 공무집행에 대한 항거 제지를 위해 필요한 한도에서 사용한다.":"위해성 경찰장비는 필요한 최소한으로 쓰고 경찰장구는 체포와 도주 방지와 방어와 공무집행 방해 제지에 필요한 한도에서 사용합니다.","응원을 위하여 파견된 직원은 응원을 요청한 행정청의 지휘·감독을 받는다. 행정응원에 드는 비용은 응원을 요청한 행정청이 부담하며, 부담금액 및 부담방법은 양 행정청이 협의하여 결정한다.":"파견 직원은 요청한 행정청의 지휘를 받고 비용도 요청한 쪽이 지며 부담 방법은 두 행정청이 협의해 정합니다.","의견제출기한은 의견제출에 필요한 기간을 10일 이상으로 고려하여 정하여야 한다.":"의견을 낼 기한은 당사자가 준비하기에 충분하도록 10일 이상을 고려해서 정해야 합니다.","의견 제출 기한 이내에 자진 납부하려는 경우 과태료를 감경할 수 있고, 감경된 과태료를 납부하면 부과 및 징수절차는 종료한다.":"의견 제출 기한 안에 자진해서 내면 과태료를 줄여 줄 수 있고 감경된 금액을 내면 절차가 끝납니다.","의무를 이행할 때까지 반복하여 부과할 수 있다. 의무자가 의무를 이행하면 새로운 이행강제금의 부과를 즉시 중지하되, 이미 부과한 이행강제금은 징수하여야 한다.":"이행할 때까지 반복해 부과할 수 있고 이행하면 새 부과는 멈추지만 이미 부과한 금액은 그대로 징수합니다.","의무 불이행의 동기·목적 및 결과, 의무 불이행의 정도 및 상습성, 그 밖에 행정목적 달성에 필요하다고 인정되는 사유.":"금액을 정할 때는 의무를 어긴 동기와 결과와 정도와 상습성을 고려해 가중하거나 감경합니다.","의무자가 금전급부의무를 이행하지 아니하는 경우 행정청이 의무자의 재산에 실력을 행사하여 그 의무가 실현된 것과 같은 상태를 실현하는 것.":"강제징수는 세금이나 부담금 같은 돈을 내지 않을 때 의무자의 재산을 압류하는 등 직접 거두는 수단입니다.","의무자가 동의한 경우, 해가 지기 전에 대집행을 착수한 경우, 해가 뜬 후부터 해가 지기 전까지 대집행하면 목적 달성이 불가능한 경우, 그 밖에 비상시 또는 위험이 절박한 경우.":"의무자가 동의했거나 해지기 전에 착수했거나 낮에는 목적을 못 이루거나 위험이 절박하면 야간에도 대집행할 수 있습니다.","의무자가 타인이 대신하여 행할 수 있는 행정상 의무를 이행하지 아니하는 경우, 법률로 정하는 다른 수단으로는 이행 확보가 곤란하고 불이행을 방치하면 공익을 크게 해칠 것으로 인정될 때 행정청이 스스로 하거나 제3자에게 하게 하고 비용을 의무자로부터 징수하는 것.":"대집행은 남이 대신할 수 있는 의무를 지키지 않을 때 행정청이 직접 하거나 제삼자에게 시키고 드는 비용을 의무자에게 받는 수단입니다.","의무자가 행정상 의무를 이행하지 아니하는 경우 행정청이 의무자의 신체나 재산에 실력을 행사하여 그 행정상 의무의 이행이 있었던 것과 같은 상태를 실현하는 것.":"직접강제는 의무자의 신체나 재산에 직접 실력을 써서 의무를 이행한 것과 같은 상태를 만드는 수단입니다.","의무자가 행정상 의무를 이행하지 아니하는 경우 행정청이 적절한 이행기간을 부여하고, 그 기한까지 이행하지 아니하면 금전급부의무를 부과하는 것.":"이행강제금은 이행 기간을 준 뒤에도 의무를 이행하지 않으면 돈을 내도록 압박하는 간접적 강제 수단입니다.","의사결정 과정 또는 내부검토 과정을 이유로 비공개할 때에는 통지 시 그 단계 및 종료 예정일을 함께 안내하여야 하며, 과정이 종료되면 청구인에게 통지하여야 한다.":"내부 검토를 이유로 비공개하면 현재 단계와 종료 예정일을 함께 안내하고 과정이 끝나면 청구인에게 다시 알려야 합니다.","의사결정과정에 제공된 회의관련자료나 의사결정과정이 기록된 회의록은 의사가 결정되거나 집행된 경우에는 더 이상 의사결정과정에 있는 사항 그 자체는 아니나, 의사결정과정에 있는 사항에 준하는 사항으로서 비공개대상정보에 포함될 수 있다.":"의사가 이미 결정되거나 집행된 뒤의 회의자료도 결정 과정에 준하는 사항으로 보아 비공개 대상이 될 수 있습니다.","의장과 부의장의 임기는 2년이다. 불신임은 재적의원 4분의 1 이상의 발의와 재적의원 과반수의 찬성으로 의결한다.":"의장과 부의장은 임기가 2년이고 4분의 1 이상 발의와 과반수 찬성이 있으면 불신임할 수 있습니다.","이의신청 결과를 통지받은 후 행정심판 또는 행정소송을 제기하려면 그 결과를 통지받은 날부터 90일 이내에 하여야 한다. 이의신청과 관계없이 행정심판·행정소송을 제기할 수도 있다.":"이의신청 결과를 받은 날부터 90일 안에 심판이나 소송을 내야 하며 이의신청 없이 바로 제기해도 됩니다.","이의신청에 대한 재결이 확정되면 민사소송법상 확정판결이 있은 것으로 보며, 재결서 정본은 집행력 있는 판결의 정본과 동일한 효력을 가진다.":"이의신청 재결이 확정되면 확정판결과 같게 보아 재결서 정본에 집행력 있는 판결 정본과 같은 효력이 생깁니다.","이의제기를 받은 행정청은 14일 이내에 의견 및 증빙서류를 첨부하여 관할 법원에 통보하여야 한다. 이의제기가 철회되거나 이유 있어 과태료를 부과할 필요가 없다고 인정되는 경우는 제외.":"이의제기를 받은 행정청은 14일 안에 의견과 증빙서류를 붙여 관할 법원에 알려야 하며 철회되었거나 이유 있다고 보면 제외입니다.","이익설, 주체설, 성질설, 신주체설(귀속설), 복수기준설. 어느 하나로 정해지지 않으므로 법규의 취지·성질을 종합해 판단한다.":"공법과 사법을 가르는 학설이 여럿이고 하나로 정해지지 않아 법규의 취지와 성질을 종합해 판단합니다.","이주대책대상자는 사업시행자가 이주대책 대상자 확인·결정 처분을 한 때 비로소 수분양권을 취득한다. 사업시행자가 이주대책 구체적 계획을 수립·공고하는 것만으로 수분양권을 취득하지 않는다.":"이주대책대상자는 사업시행자가 대상자 확인과 결정 처분을 한 때에야 분양받을 권리를 얻으며 계획 공고만으로는 얻지 못합니다.","이주대책에는 이주정착지에 대한 도로·급수시설·배수시설 등 통상적인 수준의 생활기본시설이 포함되어야 하고 필요한 비용은 사업시행자가 부담한다.":"이주정착지에는 도로와 급수와 배수 같은 통상적 수준의 생활기본시설이 들어가고 그 비용은 사업시행자가 부담합니다.","이행강제금 부과처분은 항고소송의 대상이 되는 처분이다. 건축법상 이행강제금도 같다.":"이행강제금 부과는 국민의 재산에 직접 영향을 주는 처분이라서 건축법상 이행강제금도 항고소송으로 다툽니다.","이행강제금은 대체적 작위의무의 위반에 대하여도 부과할 수 있다.":"남이 대신할 수 있는 대체적 작위의무를 어긴 경우에도 이행강제금을 부과할 수 있습니다.","이행강제금을 납부기한까지 내지 아니하면 국세강제징수의 예 또는 「지방행정제재·부과금의 징수 등에 관한 법률」에 따라 징수한다.":"이행강제금을 기한까지 내지 않으면 국세 강제징수의 방법이나 지방행정제재 징수법에 따라 거둡니다.","이행강제금을 부과하기 전에 미리 의무자에게 적절한 이행기간을 정하여 그 기한까지 이행하지 아니하면 이행강제금을 부과한다는 뜻을 문서로 계고하여야 한다.":"부과하기 전에 이행 기간을 정해 그때까지 이행하지 않으면 이행강제금을 매기겠다는 뜻을 문서로 알려야 합니다.","인근 유사토지의 지료·임대료, 사용방법, 사용기간 및 토지의 가격 등을 고려한 적정가격으로 보상한다. 사용 기간이 3년 이상, 형질 변경, 소유자의 건축물이 있는 경우 소유자는 매수 또는 수용을 청구할 수 있다.":"사용하는 토지는 비슷한 땅의 지료와 사용 기간 등을 고려해 보상하며 3년 이상 사용하거나 형질을 바꾸면 매수나 수용을 청구할 수 있습니다.","인사업무담당 공무원이 다른 공무원의 공무원증을 위조한 행위는 직무집행행위에 해당한다(외형상 직무행위).":"겉으로 보아 직무로 보이는 행위라면 개인적 동기가 있어도 직무집행으로 인정하는 외형설을 적용한 사례입니다.","인허가의제를 받으려면 주된 인허가를 신청할 때 관련 인허가에 필요한 서류를 함께 제출하여야 한다. 불가피한 사유로 함께 제출할 수 없는 경우에는 주된 인허가 행정청이 별도로 정하는 기한까지 제출할 수 있다.":"의제를 받으려면 주된 인허가 신청 때 관련 서류를 같이 내야 하고 불가피하면 행정청이 정한 기한까지 낼 수 있습니다.","인허가의제의 경우 관련 인허가 행정청은 관련 인허가를 직접 한 것으로 보아 관계 법령에 따른 관리·감독 등 필요한 조치를 하여야 한다.":"의제로 허가가 성립한 뒤에도 관련 인허가 행정청은 자기가 허가한 것처럼 관리하고 감독해야 합니다.","일단의 토지 일부가 취득·사용됨으로 잔여지 가격이 감소하거나 통로·도랑·담장 등 공사가 필요하면 보상한다. 사업완료일부터 1년이 지난 후에는 청구할 수 없다.":"일부만 취득되어 남은 땅 값이 내리거나 통로와 담장 공사가 필요하면 보상하며 사업완료일로부터 1년이 지나면 청구하지 못합니다.","일반 재량보다 넓은 형성의 자유를 갖되, 형량명령(이익형량을 하지 않거나 누락하거나 과소·과대평가한 경우 위법)에 의한 통제를 받는다.":"계획재량은 일반 재량보다 넓지만 이익형량을 안 하거나 빠뜨리거나 잘못 평가하면 위법이 되는 형량명령의 통제를 받습니다.","일반직공무원(기술·연구 또는 행정 일반 업무)과 특정직공무원(법관, 검사, 외무공무원, 경찰공무원, 소방공무원, 교육공무원, 군인, 군무원, 헌법연구관, 국가정보원 직원, 경호공무원 등).":"경력직공무원은 일반 행정이나 기술 업무를 하는 일반직과 법관과 검사와 경찰과 군인 등 특수 분야의 특정직으로 나뉩니다.","임시처분은 집행정지로 목적을 달성할 수 있는 경우에는 허용되지 아니한다.":"집행정지로 충분히 막을 수 있는 불이익에는 임시처분이 쓰이지 않는 보충적 제도입니다.","임용결격자에 대한 임용행위가 당연무효이므로 국가가 사후에 이를 발견하여 취소하는 것은 취소권의 시효 제한을 받지 않는다.":"임용결격자의 임용은 당연무효이므로 국가가 나중에 발견해 바로잡아도 취소권의 기간 제한이 문제 되지 않습니다.","임용 당시 공무원임용결격사유가 있었다면 비록 국가의 과실에 의하여 임용결격자임을 밝혀내지 못하였다 하더라도 그 임용행위는 당연무효이다.":"결격사유가 있는 사람을 임용했다면 국가가 과실로 몰랐더라도 임용행위는 당연무효입니다.","임용행위의 하자로 임용행위가 취소되어 소급적으로 공무원의 지위를 상실한 자는 공무원연금법상 퇴직급여를 청구할 수 없다.":"임용이 하자로 소급해 취소되어 공무원 지위를 잃은 사람은 공무원연금법상 퇴직급여를 청구할 수 없습니다.","입법 실제에서 대통령령에는 시행령, 총리령과 부령에는 시행규칙이라는 이름을 붙인다.":"법 이름에 시행령이 붙으면 대통령령이고 시행규칙이 붙으면 총리령이나 부령임을 알 수 있습니다.","입법예고기간은 특별한 사정이 없으면 40일(자치법규는 20일) 이상으로 한다.":"입법예고 기간은 국민이 의견을 내도록 보통 40일 이상이며 자치법규는 그보다 짧은 20일 이상입니다.","자기구속의 법리는 행정관행이 형성된 경우 적용된다. 위법한 관행에는 자기구속이 인정되지 않는다.":"자기구속은 적법한 관행에만 인정되어 위법한 관행이 되풀이되었다고 따라야 하는 것은 아닙니다.","자동차운전면허대장상의 등재행위: 공증(준법률행위적 행정행위)으로 인가가 아니다.":"운전면허대장에 이름을 올리는 것은 이미 있는 사실을 공적으로 증명하는 공증이지 인가가 아닙니다.","자신의 행위가 위법하지 아니한 것으로 오인하고 행한 질서위반행위는 그 오인에 정당한 이유가 있는 때에 한하여 과태료를 부과하지 아니한다.":"위법하지 않다고 잘못 알고 한 행위는 그렇게 오인할 정당한 이유가 있을 때에만 과태료를 면합니다.","자신이 당사자등이거나 친족관계에 있거나 있었던 경우, 해당 처분과 관련하여 증언이나 감정을 한 경우, 당사자등의 대리인으로 관여하였던 경우, 해당 처분업무를 직접 처리하였던 경우, 해당 처분업무를 처리하는 부서에 근무하는 경우. 공정한 청문 진행이 어려운 사정이 있으면 당사자등은 기피신청을 할 수 있다.":"당사자나 친족이거나 처분에 관여한 적이 있으면 청문을 맡을 수 없고 공정성이 의심되면 당사자가 기피를 신청합니다.","자연공물: 자연 상태 그대로 공적 목적에 제공된 공물(하천·바다 등). 인공공물: 인공을 가해 공적 목적에 제공된 공물(도로·공원 등).":"자연공물은 하천처럼 자연 그대로 제공된 공물이고 인공공물은 도로와 공원처럼 사람이 만들어 제공한 공물입니다.","자연인, 법인·법인이 아닌 사단 또는 재단, 그 밖에 다른 법령등에 따라 권리·의무의 주체가 될 수 있는 자.":"행정절차에서 당사자가 될 수 있는 사람은 자연인과 법인과 법인 아닌 단체처럼 권리와 의무의 주체가 될 수 있는 자입니다.","자연환경 보호 등을 목적으로 하는 도시관리계획결정은 행정청의 재량적 판단으로서, 내용이 현저히 합리성을 결여하거나 형평·비례원칙에 뚜렷하게 반하는 등의 사정이 없는 한 폭넓게 존중되어야 한다.":"환경 보호를 위한 계획은 행정청 판단을 폭넓게 존중하되 현저히 불합리하거나 형평과 비례에 반하면 위법합니다.","자유공물(自有公物)은 공물의 관리주체와 귀속주체가 같은 공물, 타유공물(他有公物)은 관리주체와 귀속주체가 다른 공물이다.":"자유공물은 관리하는 주체와 소유가 속한 주체가 같은 공물이고 타유공물은 둘이 서로 다른 공물입니다.","자치사무와 법령에 따라 지방자치단체에 속하는 사무. 국가사무는 시·도지사와 시장·군수·구청장에게 위임하여 수행하는 것이 원칙이다(기관위임사무).":"지자체의 사무는 자치사무와 법령상 지자체 사무이고 국가사무는 시도지사와 시장 군수 등에게 위임해 수행하는 기관위임사무가 원칙입니다.","작위·부작위·급부·수인의 의무를 명하는 행위.":"하명은 무엇을 하라, 하지 마라, 내라, 참으라고 국민에게 의무를 명하는 행정행위입니다.","잔여지를 종래의 목적에 사용하는 것이 현저히 곤란할 때 사업시행자에게 매수를 청구하고, 사업인정 이후에는 토지수용위원회에 수용을 청구할 수 있다. 수용 청구는 매수 협의가 성립되지 아니한 경우에만 할 수 있고, 사업완료일까지 하여야 한다.":"남은 땅을 쓰기 현저히 곤란하면 매수를 청구하고 협의가 안 되면 사업완료일까지 위원회에 수용을 청구할 수 있습니다.","재결에서 정한 보상금액이 일부 보상항목은 과소하고 다른 보상항목은 과다할 경우 법원은 보상항목 상호간의 유용을 허용하여 보상금을 결정할 수 있다.":"항목별로 과소와 과다가 섞여 있으면 법원이 항목끼리 금액을 돌려 쓰는 유용을 허용해 전체 보상금을 정할 수 있습니다.","재결에 의하여 취소되거나 무효 또는 부존재로 확인되는 처분이 당사자의 신청을 거부하는 것이면 그 처분을 한 행정청은 재결의 취지에 따라 다시 이전의 신청에 대한 처분을 하여야 한다. 신청을 거부하거나 부작위로 방치한 처분의 이행을 명하는 재결이 있으면 행정청은 지체 없이 이전의 신청에 대하여 재결의 취지에 따라 처분을 하여야 한다. 신청에 따른 처분이 절차의 위법 또는 부당을 이유로 재결로 취소된 경우에도 재처분 의무가 있다.":"거부처분이 재결로 취소되거나 이행을 명받으면 행정청은 재결 취지에 따라 이전 신청에 대해 다시 처분해야 하고 절차 위법 취소에도 같습니다.","재결은 서면으로 하며, 재결서에는 사건번호와 사건명, 당사자·대표자 또는 대리인의 이름과 주소, 주문, 청구의 취지, 이유, 재결한 날짜가 포함되어야 한다.":"재결서에는 사건 번호와 당사자 정보와 주문과 청구 취지와 이유와 날짜를 서면으로 갖추어야 합니다.","재결은 심판청구서를 받은 날부터 60일 이내에 하여야 한다. 부득이한 사정이 있으면 위원장이 직권으로 30일을 연장할 수 있고, 재결 기간이 끝나기 7일 전까지 당사자에게 알려야 한다.":"재결은 청구서를 받은 날부터 60일 안에 해야 하고 위원장이 30일 연장할 수 있으며 끝나기 7일 전까지 당사자에게 알립니다.","재결은 청구인에게 재결서의 정본이 송달되었을 때에 효력이 생긴다.":"재결의 효력은 재결을 한 날이 아니라 청구인에게 재결서 정본이 송달되는 때에 시작됩니다.","재량권의 일탈(법정 한계를 넘음), 남용(목적 위반), 불행사(재량을 행사하지 아니함).":"재량의 하자는 법이 정한 한계를 넘는 일탈과 목적에 어긋나는 남용과 아예 재량을 쓰지 않는 불행사로 나눕니다.","재량권 행사의 준칙인 행정규칙이 되풀이 시행되어 행정관행이 형성되고 행정기관이 자기구속을 당하게 되는 경우에는 헌법소원의 대상이 될 수 있다.":"재량 준칙이 반복되어 관행이 되고 행정기관이 스스로 구속되는 경우에는 헌법소원으로 다툴 수 있습니다.","재량이 있는 제재처분 시 고려사항: 위반행위의 동기·목적 및 방법, 위반행위의 결과, 위반행위의 횟수, 그 밖에 이에 준하는 사항으로서 대통령령으로 정하는 사항.":"재량으로 제재를 정할 때는 위반의 동기와 방법, 결과, 횟수 등을 종합해서 판단하도록 법이 요구합니다.","재량준칙은 일반적으로 행정조직 내부에서만 효력을 가질 뿐 대외적인 구속력을 갖는 것은 아니다. 재량준칙은 행정의 자기구속법리나 평등원칙 등에 의해 대외적 구속력을 가질 수 있다.":"재량준칙은 원래 내부 효력뿐이지만 자기구속과 평등원칙을 통해서 대외적 구속력이 생길 수 있습니다.","재량준칙이 정한 바에 따라 되풀이 시행되어 행정관행이 형성되면, 행정기관은 그 상대방에 대한 관계에서 그 규칙에 따라야 할 자기구속을 받는다. 자기구속의 법리는 평등의 원칙이나 신뢰보호의 원칙에서 도출된다. 재량준칙은 이를 통해 대외적 구속력을 가질 수 있다.":"재량준칙대로 반복 처리해 관행이 생기면 행정청이 스스로 묶여 그 준칙이 대외적 효력을 갖게 됩니다.","재량행위에서 하자 없는 재량 행사를 요구할 수 있는 권리다. 특정 처분을 요구하는 권리가 아니다.":"재량행위에서 흠 없이 판단해 달라고 요구하는 권리이며 특정한 결론의 처분을 요구하는 것은 아닙니다.","재산의 소유자·점유자를 알 수 없거나 현장에서 소재를 즉시 확인하기 어려운 경우 즉시강제를 실시한 후 집행책임자의 이름 및 이유와 내용을 고지할 수 있다. 소유자·점유자를 알 수 없는 경우, 국외 거주나 행방불명 등인 경우에는 게시판이나 인터넷 홈페이지 게시 등 공고로 고지를 갈음할 수 있다.":"소유자를 알 수 없거나 현장에 없으면 즉시강제를 한 후에 이유를 고지하고 행방불명이면 게시판 공고로 갈음할 수 있습니다.","재심사 결과는 신청을 받은 날부터 90일(합의제행정기관은 180일) 이내에 통지하고, 연장은 한 차례 같은 기간의 범위에서 가능하다. 처분을 유지하는 결과는 쟁송으로 불복할 수 없다.":"재심사 결과는 90일 안에 통지하고 한 번 연장할 수 있으며 처분을 그대로 유지한다는 결과는 쟁송으로 다툴 수 없습니다.","재심사 신청은 당사자가 중대한 과실 없이 사유를 주장하지 못한 경우에만 가능하고, 사유를 안 날부터 60일 이내에 하여야 하며, 처분이 있은 날부터 5년이 지나면 신청할 수 없다.":"재심사는 중대한 과실 없이 사유를 못 낸 경우에 사유를 안 날부터 60일 안에 신청하고 처분 후 5년이 지나면 못 합니다.","재외동포에 대한 사증발급과 관련한 재량권 불행사는 재량권 일탈·남용에 해당하여 해당 처분을 취소하여야 할 위법사유가 된다.":"재외동포 사증발급에서 재량을 아예 행사하지 않았다면 일탈이나 남용으로 보아 처분을 취소해야 합니다.","쟁송에서 취소·철회된 제재처분의 재처분: 재결·판결이 확정된 날부터 1년(합의제행정기관은 2년)이 지나기 전까지 그 취지에 따른 새로운 제재처분을 할 수 있다.":"쟁송에서 제재가 취소되어도 재결이나 판결이 확정된 날부터 1년 안에 그 취지에 맞춰 다시 처분할 수 있습니다.","적법하게 부과될 정당한 세액이 산출되면 법원은 정당한 세액을 초과하는 부분만 취소할 수 있다.":"과세처분이 부당하게 많이 부과된 경우 정당한 세액을 넘는 부분만 취소하는 일부취소가 가능합니다.","적법한 처분을 장래를 향하여 효력을 소멸시키는 것.":"철회는 처음에는 적법했던 처분의 효력을 이후 사정 때문에 앞으로만 없애는 것입니다.","적법한 처분의 철회 사유 1호: 법률에서 정한 철회 사유에 해당하게 된 경우.":"법률이 철회 사유로 직접 정해 둔 사정이 생기면 행정청이 처분을 철회할 수 있습니다.","전사하거나 순직한 군인·군무원·경찰공무원 또는 예비군대원의 유족은 자신의 정신적 고통에 대한 위자료를 청구할 수 있다.":"유족은 보상을 받는 본인이 아니라 자신이 입은 정신적 고통에 대한 위자료는 청구할 수 있습니다.","전투·훈련 등 직무 집행과 관련하여 전사·순직하거나 공상을 입은 손해에 한한다. 본인이나 유족이 다른 법령에 따라 재해보상금·유족연금·상이연금 등의 보상을 지급받을 수 있을 때 이 법 및 민법에 따른 손해배상을 청구할 수 없다.":"전투나 훈련 중 전사와 순직과 공상을 입고 다른 법령상 보상을 받을 수 있으면 국가배상과 민법상 배상을 청구하지 못합니다.","전투·훈련 또는 이에 준하는 직무집행뿐 아니라 일반 직무집행에 관하여도 적용된다.":"이중배상 금지는 전투와 훈련에 한정되지 않고 일반적인 직무집행과 관련한 손해에도 적용됩니다.","전투훈련 중 민간인이 군인과 공동불법행위를 한 경우 민간인은 자신의 부담 부분만을 피해 군인에게 배상하면 된다(대법원 전원합의체 판례).":"민간인이 군인과 공동불법행위를 했다면 피해 군인에게 전체가 아니라 자기 부담 부분만 배상하면 됩니다.","정무직공무원(선거로 취임하거나 임명에 국회 동의가 필요한 공무원, 고도의 정책결정 업무 담당 공무원)과 별정직공무원(비서관·비서 등). 정무직공무원은 특수경력직공무원에 해당한다.":"특수경력직은 선거로 취임하거나 국회 동의가 필요하거나 정책을 결정하는 정무직과 비서관 같은 별정직으로 이루어집니다.","정보공개 청구권자: 모든 국민. 외국인의 청구는 대통령령으로 정한다.":"정보공개는 모든 국민이 청구할 수 있고 외국인이 청구할 수 있는 범위는 대통령령으로 따로 정합니다.","정보공개 청구권자의 권리구제 가능성이 없다는 이유로 비공개 대상 정보에 해당하지 않는 정보를 공개하지 않을 수는 없다.":"청구인이 권리구제를 받을 가능성이 없다는 이유만으로 비공개 대상이 아닌 정보의 공개를 거부할 수 없습니다.","정보공개 청구는 청구서를 제출하거나 말로써 할 수 있다. 말로 하는 경우 담당공무원 앞에서 진술하고, 담당공무원이 청구조서를 작성하여 청구인과 함께 기명날인 또는 서명한다.":"청구는 서면으로 하거나 말로 할 수 있고 말로 하면 담당공무원이 청구조서를 쓰고 청구인과 함께 서명합니다.","정보주체가 개인정보처리자의 위반으로 손해를 입으면 손해배상을 청구할 수 있고, 개인정보처리자는 고의 또는 과실이 없음을 입증하지 아니하면 책임을 면할 수 없다. 개인정보처리자의 고의 또는 중대한 과실로 유출등이 된 경우 법원은 손해액의 5배를 넘지 않는 범위에서 손해배상액을 정할 수 있다.":"처리자는 고의나 과실이 없음을 스스로 증명해야 책임을 면하고 고의나 중과실 유출이면 손해액의 5배 범위에서 배상액이 정해집니다.","정보주체는 개인정보 처리의 정지를 요구하거나 동의를 철회할 수 있다.":"정보주체는 자기 정보가 처리되는 것을 멈추라고 요구하거나 이미 한 동의를 거둘 수 있습니다.","정보주체는 개인정보처리자가 처리하는 자신의 개인정보에 대한 열람을 요구할 수 있다. 열람 제한·거절 사유: 법률에 따라 열람이 금지·제한되는 경우, 다른 사람의 생명·신체를 해할 우려나 재산 등 이익을 부당하게 침해할 우려가 있는 경우, 공공기관의 조세 부과·징수, 학교 성적 평가·입학자 선발, 학력·기능·채용 시험, 보상금 산정 평가, 진행 중인 감사·조사 업무에 중대한 지장을 초래하는 경우.":"자기 정보는 열람을 요구할 수 있지만 법률 금지나 타인 이익 침해나 시험과 감사 업무에 중대한 지장이 있으면 제한됩니다.","정보주체 또는 제3자 이익을 부당하게 침해할 우려가 있을 때 제외: 정보주체의 별도 동의, 다른 법률에 특별한 규정, 급박한 생명·신체·재산 이익, 법령상 소관 업무 수행 불가 시 보호위원회 심의·의결(공공기관), 조약 이행, 범죄의 수사와 공소 제기·유지, 법원의 재판업무, 형 및 감호·보호처분의 집행, 공중위생 등 긴급.":"별도 동의나 다른 법률 규정이나 급박한 이익 보호 등의 경우에만 목적 외로 쓸 수 있고 이익을 부당하게 침해할 우려가 있으면 막힙니다.","정보주체에게 알리고 별도로 동의를 받거나 법령에서 구체적으로 처리를 요구·허용하는 경우에만 처리할 수 있고, 유출 등이 되지 않도록 암호화 등 안전성 확보 조치를 하여야 한다.":"고유식별정보는 별도 동의나 법령의 구체적 허용이 있을 때만 처리하고 유출되지 않도록 암호화 같은 조치를 해야 합니다.","정보주체의 동의, 법률 규정 또는 법령상 의무 준수를 위해 불가피한 경우, 공공기관의 법령상 소관 업무 수행을 위해 불가피한 경우, 계약 이행·체결 과정에서 정보주체 요청에 따른 조치를 위해 필요한 경우, 명백히 정보주체 또는 제3자의 급박한 생명·신체·재산 이익을 위해 필요한 경우, 개인정보처리자의 정당한 이익 달성을 위해 필요하고 명백하게 정보주체의 권리보다 우선하는 경우, 공중위생 등 공공의 안전과 안녕을 위하여 긴급히 필요한 경우.":"동의가 있거나 법령 의무 이행이나 계약 이행이나 급박한 생명 보호나 정당한 이익이 우선하는 경우 등에 개인정보를 수집하고 이용할 수 있습니다.","정보통신망을 이용한 송달은 송달받을 자가 동의하는 경우에만 한다. 이 경우 송달받을 전자우편주소 등을 지정하여야 한다.":"전자적 송달은 받을 사람의 동의가 있어야 가능하고 이때 받을 전자우편주소 등을 지정해야 합니다.","정부기업이 직접 사무용·사업용 또는 그 기업에 종사하는 직원의 주거용으로 사용하거나 기한까지 사용하기로 결정한 재산.":"기업용재산은 정부기업이 직접 사무용이나 사업용이나 직원 주거용으로 쓰거나 기한까지 쓰기로 정한 재산입니다.","정부는 성별영향평가 결과를 포함하여 예산이 여성과 남성에게 미치는 효과를 평가하고 그 결과를 예산편성에 반영하기 위하여 노력하여야 한다.":"예산이 남녀에게 미치는 효과를 성별영향평가로 살펴 그 결과를 예산편성에 반영하려고 노력해야 합니다.","정부는 예측할 수 없는 예산 외의 지출 또는 예산초과지출에 충당하기 위하여 일반회계 예산총액의 100분의 1 이내의 금액을 예비비로 세입세출예산에 계상할 수 있다. 10분의 1이 아니다.":"예측할 수 없는 지출에 대비해 일반회계 예산총액의 100분의 1 이내를 예비비로 잡을 수 있으며 10분의 1이 아닙니다.","정부는 재정건전성의 확보를 위하여 최선을 다하여야 한다. 국민부담의 최소화, 재정지출 성과 제고, 예산과정의 투명성 제고에도 노력한다.":"정부는 재정건전성 확보를 위해 최선을 다하고 국민부담 최소화와 성과 제고와 예산과정의 투명성도 함께 추구해야 합니다.","정신착란 또는 술에 취하여 자신 또는 타인의 생명·신체·재산에 위해를 끼칠 우려가 있는 사람, 자살을 시도하는 사람, 미아·병자·부상자 등으로서 적당한 보호자가 없고 응급구호가 필요한 사람(본인이 구호를 거절하는 경우 제외).":"자해나 타해 우려가 있는 사람과 자살 시도자와 보호자가 없는 미아나 병자와 부상자가 보호조치 대상이며 본인이 거절하면 제외됩니다.","정지시킨 장소에서 질문하는 것이 그 사람에게 불리하거나 교통에 방해가 된다고 인정될 때에는 가까운 경찰관서로 동행할 것을 요구할 수 있다. 동행을 요구받은 사람은 그 요구를 거절할 수 있다.":"현장 질문이 불리하거나 교통에 방해가 되면 경찰관서 동행을 요구할 수 있으나 요구를 받은 사람은 거절할 수 있습니다.","정책의 결정 및 집행 과정에 참여할 권리, 재산과 공공시설을 이용할 권리, 균등하게 행정의 혜택을 받을 권리, 지방선거에 참여할 권리.":"주민은 정책 결정과 집행에 참여하고 재산과 공공시설을 이용하고 균등한 혜택을 받고 선거에 참여할 권리를 가집니다.","정책·제도·계획(정책등)을 수립·시행하거나 변경하려는 경우 행정예고를 하여야 한다. 행정예고기간은 20일 이상이다. 긴급한 필요가 있으면 단축할 수 있으나 10일 이상이어야 한다.":"정책과 제도와 계획을 세우거나 바꿀 때 20일 이상 행정예고를 하며 긴급하면 줄일 수 있어도 10일 이상이어야 합니다.","제21조 제4항 각 호(사전통지 생략 사유)에 해당하는 경우, 당사자가 의견진술의 기회를 포기한다는 뜻을 명백히 표시한 경우.":"사전통지 생략 사유에 해당하거나 당사자가 의견진술을 포기하겠다고 분명히 밝히면 의견청취를 하지 않아도 됩니다.","제3자는 통지를 받은 날부터 3일 이내에 비공개를 요청할 수 있다. 비공개 요청에도 공개 결정을 한 경우 제3자는 통지를 받은 날부터 7일 이내에 이의신청을 하거나 행정심판 또는 행정소송을 제기할 수 있고, 공개 결정일과 공개 실시일 사이에 최소한 30일의 간격을 두어야 한다.":"제삼자는 3일 안에 비공개를 요청하고 그래도 공개되면 7일 안에 불복할 수 있으며 공개 결정과 실시 사이에 30일 이상 둡니다.","제3자의 법률행위의 효력을 보충하여 완성시키는 행위. 기본행위가 없으면 인가는 무효이고, 기본행위에 하자가 있으면 인가가 있어도 기본행위의 하자를 다툰다.":"인가는 남의 법률행위를 보충해 완성시키므로 기본행위가 없으면 무효이고 하자는 기본행위를 직접 다퉈야 합니다.","제5조 제1항에도 제2조 제1항 단서(군인 등), 제3조(배상기준), 제3조의2(공제액)가 준용된다.":"영조물 책임에도 군인 등 이중배상 금지와 배상기준과 공제액 규정이 같이 적용됩니다.","제9조, 제10조, 제13조~제17조, 제19조, 제22조~제26조, 제29조~제31조, 제33조가 준용된다. 사정판결(제28조)과 간접강제(제34조), 제소기간(제20조)은 준용되지 않는다.":"무효등 확인소송에도 취소소송 규정이 대부분 준용되지만 사정판결과 간접강제와 제소기간은 준용되지 않습니다.","제공받는 자, 제공받는 자의 이용 목적, 제공하는 항목, 제공받는 자의 보유 및 이용 기간, 동의 거부권 및 불이익.":"제삼자에게 제공하려면 누가 받는지와 그 이용 목적과 제공 항목과 보유 기간과 동의 거부권을 알려야 합니다.","제약회사는 보건복지부 고시인 약제급여·비급여 목록 및 급여 상한금액표 중 자신이 제조·공급하는 약제의 상한금액 인하 부분의 취소를 구할 원고적격이 있다.":"자기 약제의 상한금액이 내려간 제약회사는 그 부분이 자기에게 직접 불이익을 주므로 취소를 구할 원고적격이 있습니다.","제재적 행정처분으로서의 과징금은 원칙적으로 위반자의 고의 또는 과실을 요하지 않는다.":"제재적 과징금은 의무 위반이라는 객관적 사실을 기준으로 하므로 위반자의 고의나 과실이 원칙적으로 필요 없습니다.","제재적 행정처분으로서의 과징금은 현실적인 행위자가 아닌 법령상 책임자에게 부과할 수 있다.":"제재적 과징금은 실제로 행위를 한 사람이 아니라 법령이 정한 책임자에게 부과할 수 있습니다.","제재처분의 근거 법률에는 제재처분의 주체, 사유, 유형 및 상한을 명확하게 규정하여야 한다.":"제재의 법적 근거에는 누가 어떤 사유로 어떤 종류를 어느 한도까지 할 수 있는지가 분명히 적혀 있어야 합니다.","조건, 기한, 부담, 철회권의 유보 등.":"부관은 처분의 효과를 제한하려고 덧붙이는 약정으로 조건과 기한과 부담과 철회권 유보가 대표적입니다.","조건: 효력 발생·소멸이 장래 불확실한 사실에 의존하는 부관(정지조건·해제조건). 기한: 장래 확실한 사실에 의존하는 부관(시기·종기). 철회권의 유보: 일정한 경우 철회할 수 있음을 유보하는 부관.":"조건은 불확실한 사실에 기한은 확실히 올 사실에 의존하고 철회권 유보는 일정 경우 철회할 수 있도록 남겨 두는 것입니다.","조례가 집행행위의 개입 없이 그 자체로서 직접 국민의 구체적인 권리의무에 영향을 미치는 등 법률상 효과를 발생하는 경우에는 항고소송의 대상이 되는 처분이다.":"조례가 별도 집행 없이 곧바로 국민의 권리와 의무에 영향을 준다면 처분으로 보아 항고소송으로 다툴 수 있습니다.","조례안이 의결되면 의장은 5일 이내에 지방자치단체의 장에게 이송하고, 장은 20일 이내에 공포하거나 이유를 붙여 재의를 요구할 수 있다(일부 재의·수정 재의 불가). 재의 결과 재적의원 과반수 출석과 출석의원 3분의 2 이상 찬성으로 전과 같이 의결하면 조례로 확정된다.":"의결된 조례안은 5일 안에 이송되어 단체장이 20일 안에 공포하거나 재의를 요구하고 3분의 2 이상 찬성으로 재의결하면 확정됩니다.","조례와 규칙은 특별한 규정이 없으면 공포한 날부터 20일이 지나면 효력을 발생한다.":"조례와 규칙은 공포일이 곧 시행일이 아니라 특별한 규정이 없으면 20일이 지나서 효력이 생깁니다.","조례 위반 행위에 대해 조례로 1천만원 이하의 과태료를 정할 수 있다.":"조례를 어긴 행위에 대해서는 1천만원 이하의 과태료까지 조례로 정할 수 있습니다.","조례의 제정·개정 및 폐지, 예산의 심의·확정, 결산의 승인, 법령에 규정된 것을 제외한 사용료·수수료·분담금·지방세 또는 가입금의 부과와 징수, 기금의 설치·운용, 대통령령으로 정하는 중요 재산의 취득·처분, 대통령령으로 정하는 공공시설의 설치·처분, 법령과 조례에 규정된 것을 제외한 예산 외의 의무부담이나 권리의 포기, 청원의 수리와 처리, 외국 지방자치단체와의 교류·협력, 그 밖에 법령에 따라 그 권한에 속하는 사항.":"지방의회는 조례 제정과 예산 심의와 결산 승인과 기금 운용과 청원 처리 같은 사항을 의결할 권한이 있습니다.","조림 목적 토지와 정착물 20년, 대부받은 자의 비용으로 시설을 보수하는 건물 10년, 그 밖의 토지와 정착물 5년, 그 밖의 재산 1년.":"일반재산의 대부기간은 재산 종류에 따라 조림 목적 20년과 보수 시설 건물 10년과 그 밖의 토지 5년과 그 밖의 재산 1년으로 다릅니다.","조직규칙, 근무규칙(훈령·지시·예규·일일명령), 영조물규칙, 규범해석규칙, 재량준칙, 법령보충적 행정규칙.":"행정규칙은 내용에 따라 조직 규칙부터 법령을 보충하는 행정규칙까지 여섯 갈래로 나뉩니다.","주거용 건물의 거주자에 대해서는 주거 이전에 필요한 비용과 가재도구 등 동산의 운반에 필요한 비용을 보상한다. 이주정착금·주거이전비 보상을 둘러싼 소송은 공법상 당사자소송으로 다툰다.":"거주자에게는 이사 비용과 가재도구 운반비를 보상하며 이주정착금과 주거이전비 관련 소송은 공법상 당사자소송으로 다툽니다.","주된 인허가가 있은 후 이를 변경하는 경우에는 제24조·제25조 및 제26조 제1항을 준용한다.":"주된 인허가를 나중에 변경할 때에도 처음과 같은 서류 제출과 협의 규정을 준용합니다.","주된 인허가 행정청은 주된 인허가를 하기 전에 관련 인허가에 관하여 미리 관련 인허가 행정청과 협의하여야 한다.":"주된 인허가를 내주기 전에 관련 인허가를 담당하는 행정청과 미리 협의하는 절차가 필요합니다.","주된 행정행위에 부가하여 작위·부작위·급부·수인의무를 명하는 부관. 주된 행정행위의 효력 발생과는 별개로 효력을 발생한다.":"부담은 처분에 덧붙여 의무를 명하는 부관이며 주된 처분의 효력과 따로 효력이 생깁니다.","주무부장관이나 시·도지사는 청구를 받으면 5일 이내에 내용을 공표하고, 공표한 날부터 10일간 청구인명부를 열람하게 한다. 청구를 수리한 날부터 60일 이내에 감사를 끝내야 하며, 정당한 사유가 있으면 기간을 연장할 수 있다.":"청구를 받으면 5일 안에 공표하고 10일간 청구인명부를 열람하게 하며 수리한 날부터 60일 안에 감사를 끝내야 합니다.","주민등록 전입신고와 그 수리 여부에 관한 소송은 공법관계(항고소송)다.":"주민등록 전입신고의 수리 여부는 행정청의 공권력 행사라서 공법관계이며 항고소송으로 다툽니다.","주민소송에서 당사자는 법원의 허가를 받지 아니하고는 소의 취하, 소송의 화해 또는 청구의 포기를 할 수 없다.":"주민소송은 공익을 위한 소송이라 소 취하와 화해와 청구 포기를 하려면 법원의 허가가 있어야 합니다.","주민소송은 감사청구한 사항과 동일할 필요는 없고, 감사청구한 사항과 관련이 있는 위법한 행위나 업무를 게을리한 사실이면 된다.":"주민소송은 감사청구한 사항과 똑같을 필요는 없고 그와 관련이 있는 위법 행위나 해태 사실이면 가능합니다.","주민소송은 민중소송이며 객관소송이다. 해당 지방자치단체의 사무소 소재지를 관할하는 행정법원의 관할이다.":"주민소송은 개인의 권리구제가 아니라 위법을 바로잡는 민중소송이자 객관소송이며 단체 소재지 행정법원이 관할합니다.","주민소송이 진행 중이면 다른 주민은 같은 사항에 대하여 별도의 소송을 제기할 수 없다.":"한 주민이 소송을 진행 중이면 같은 사항으로 다른 주민이 따로 소송을 내지 못하도록 막습니다.","주민은 규칙(권리·의무와 직접 관련되는 사항에 한함)의 제정·개정·폐지와 관련된 의견을 지방자치단체의 장에게 제출할 수 있고, 장은 의견이 제출된 날부터 30일 이내에 검토 결과를 통보하여야 한다.":"권리와 의무에 직접 관련된 규칙에 대해 주민이 의견을 내면 단체장은 30일 안에 검토 결과를 알려야 합니다.","주민은 지방자치단체의 장 및 지방의회의원(비례대표 지방의회의원은 제외)을 소환할 권리를 가진다.":"주민은 단체장과 지방의회의원을 임기 중에 소환할 수 있으나 비례대표 의원은 소환 대상에서 빠집니다.","주민은 지방자치단체의 조례를 제정하거나 개정하거나 폐지할 것을 청구할 수 있다.":"주민은 지방자치단체의 조례를 만들거나 고치거나 없애 달라고 직접 청구할 수 있습니다.","주민투표권은 헌법상 보장되는 기본권 또는 헌법상 제도적으로 보장되는 주관적 공권이 아니다. 법률상 권리다.":"주민투표권은 헌법이 직접 보장하는 기본권이 아니라 법률로 정해진 권리입니다.","주소등을 통상적인 방법으로 확인할 수 없거나 송달이 불가능한 경우에는 관보, 공보, 게시판, 일간신문 중 하나 이상에 공고하고 인터넷에도 공고하여야 한다. 공고일부터 14일이 지난 때에 효력이 발생한다. 긴급 시 효력 발생 시기를 달리 정하여 공고할 수 있다.":"송달이 불가능하면 관보 등에 공고하고 인터넷에도 올리며 공고일부터 14일이 지나야 효력이 생기고 긴급하면 달리 정합니다.","준용되는 취소소송 규정: 제9조, 제10조, 제13조~제19조, 제20조, 제25조~제27조, 제29조~제31조, 제33조, 제34조. 사정판결(제28조)과 집행정지(제23조)는 준용되지 않는다. 제3자의 소송참가(제16조), 소송비용에 관한 재판의 효력(제33조), 거부처분취소판결의 간접강제(제34조)가 준용된다.":"부작위위법확인소송에는 취소소송 규정 대부분이 준용되지만 사정판결과 집행정지는 준용되지 않습니다.","중대한 공익을 위하여 필요한 경우.":"중대한 공익을 지키기 위해 필요하다면 적법하게 한 처분도 철회할 수 있습니다.","중앙관서의 장은 공용·공공용·기업용재산은 그 용도나 목적에 장애가 되지 아니하는 범위에서, 보존용재산은 보존목적의 수행에 필요한 범위에서만 사용허가를 할 수 있다. 특별한 제한 없이 허가할 수 있는 것이 아니다.":"행정재산의 사용허가는 용도나 목적에 장애가 되지 않는 범위에서만 할 수 있고 보존용재산은 보존 목적 수행에 필요한 범위에서만 가능합니다.","중앙관서의 장은 사용허가한 행정재산을 국가나 지방자치단체가 직접 공용이나 공공용으로 사용하기 위하여 필요하게 된 경우에는 그 허가를 철회할 수 있다. 이때 손실이 발생하면 그 재산을 사용할 기관이 보상한다.":"국가나 지자체가 직접 공용이나 공공용으로 쓸 필요가 생기면 허가를 철회할 수 있고 그 때문에 생긴 손실은 그 재산을 쓸 기관이 보상합니다.","중앙토지수용위원회는 국가 또는 시·도가 사업시행자인 사업, 수용·사용할 토지가 둘 이상의 시·도에 걸쳐 있는 사업의 재결을 관장하고, 그 밖의 사업은 지방토지수용위원회가 관장한다.":"국가나 시도가 시행하거나 토지가 둘 이상의 시도에 걸친 사업은 중앙위원회가, 나머지는 지방위원회가 재결합니다.","중앙토지수용위원회의 재결에 이의가 있는 자는 중앙토지수용위원회에, 지방토지수용위원회의 재결에 이의가 있는 자는 해당 지방토지수용위원회를 거쳐 중앙토지수용위원회에 이의를 신청할 수 있다. 재결서의 정본을 받은 날부터 30일 이내에 하여야 한다.":"재결에 불복하면 중앙위원회에, 지방위원회 재결이면 해당 지방위원회를 거쳐 중앙위원회에 30일 안에 이의를 신청합니다.","중앙행정기관은 부·처·청과 법률에 따라 설치되는 위원회 등이다. 보조기관은 차관·차장·실장·국장·과장, 보좌기관은 정책의 기획·계획의 입안 등을 보좌하는 기관이다.":"중앙행정기관은 부와 처와 청과 위원회 등이고 보조기관은 차관부터 과장까지이며 보좌기관은 기획과 입안을 돕는 기관입니다.","중앙행정기관의 설치와 직무범위는 법률로 정한다. 행정각부의 설치·조직과 직무범위는 법률로 정한다(헌법).":"중앙행정기관과 행정각부의 설치와 조직과 직무범위는 대통령령이 아니라 법률로 정하도록 헌법이 요구합니다.","중앙행정심판위원회는 위원장 1명을 포함하여 70명 이내(상임위원 4명 이내)로 구성하며, 회의는 위원장, 상임위원 및 위원장이 지정하는 비상임위원 총 9명으로 구성한다. 위원장은 국민권익위원회 부위원장 중 1명이다.":"중앙행정심판위원회는 위원장 포함 70명 이내에 상임위원 4명 이내로 구성하고 회의는 총 9명이며 위원장은 국민권익위 부위원장 중 1명입니다.","중앙행정심판위원회는 처분의 근거가 되는 명령 등이 법령에 근거가 없거나 상위 법령에 위배되거나 국민에게 과도한 부담을 주는 등 크게 불합리하면 관계 행정기관에 개정·폐지 등 시정조치를 요청할 수 있다.":"처분의 근거 명령이 상위 법령에 어긋나거나 불합리하면 중앙위원회가 관계 기관에 개정이나 폐지 같은 시정조치를 요청할 수 있습니다.","중지청구소송은 해당 행위를 중지할 경우 생명이나 신체에 중대한 위해가 생길 우려가 있거나 공공복리를 현저하게 해칠 우려가 있으면 제기할 수 없다.":"행위를 멈추면 생명과 신체에 중대한 위해가 생기거나 공공복리를 현저히 해칠 우려가 있으면 중지청구는 낼 수 없습니다.","즉시강제는 다른 수단으로는 행정목적을 달성할 수 없는 경우에만 허용되며, 이 경우에도 최소한으로만 실시하여야 한다.":"즉시강제는 다른 수단으로는 목적을 이룰 수 없을 때에만 허용되고 그때도 필요한 최소한으로 실시합니다.","즉시강제 집행책임자는 증표를 보여 주고 즉시강제의 이유와 내용을 고지하여야 한다.":"즉시강제를 하는 사람은 먼저 증표를 보여 주고 왜 하는지와 무엇을 하는지를 알려야 합니다.","지목변경신청 반려행위, 건축물 용도변경신청 거부행위, 건축물대장 작성신청 반려행위, 토지대장 직권말소행위는 항고소송의 대상이 되는 행정처분이다. 청소년유해매체물 결정 및 고시처분은 항고소송의 대상이 되는 처분이다. 두밀분교를 폐교하는 경기도의 조례는 항고소송의 대상이 되는 처분이다.":"지목변경 반려와 용도변경 거부와 대장 관련 행위와 유해매체물 결정과 폐교 조례는 모두 항고소송 대상인 처분입니다.","지방법무사회가 법무사의 사무원 채용승인 신청을 거부한 경우, 채용승인을 신청한 법무사가 아닌 사무원이 될 자도 취소소송을 제기할 수 있다.":"채용승인 거부로 일자리를 얻지 못한 사무원 지망자도 직접 불이익을 입으므로 신청한 법무사가 아니어도 소송할 수 있습니다.","지방의회가 의결정족수에 미달될 때나 주민의 생명과 재산 보호를 위하여 긴급하게 필요한 사항으로서 지방의회를 소집할 시간적 여유가 없거나 의결이 지체되는 경우 선결처분을 할 수 있다. 지체 없이 지방의회에 보고하여 승인을 받아야 하고, 승인을 받지 못하면 그때부터 효력을 상실한다.":"의회를 열 시간이 없거나 의결이 지체될 때 단체장이 선결처분을 하되 의회에 보고해 승인받아야 하고 승인이 없으면 그때부터 효력을 잃습니다.","지방의회는 매년 2회 정례회를 개최하고, 매년 1회 시·도에서는 14일, 시·군 및 자치구에서는 9일의 범위에서 행정사무 감사를 실시한다. 조사는 재적의원 3분의 1 이상의 발의와 본회의 의결이 필요하다.":"의회는 해마다 정례회를 2회 열고 시도는 14일 시군구는 9일 범위에서 감사를 하며 조사는 재적의원 3분의 1 이상 발의가 필요합니다.","지방의회는 자치사무에 관하여 법률에 특별한 규정이 없는 한 지방자치단체장의 고유권한을 침해하지 않는 범위 내에서 조례를 제정할 수 있다.":"지방의회는 자치사무에 대해 단체장의 고유권한을 침해하지 않는 한도 안에서 조례를 정할 수 있습니다.","지방의회의원 정수의 2분의 1 범위에서 해당 지방자치단체의 조례로 정하는 바에 따라 지방의회에 정책지원 전문인력을 둘 수 있다.":"지방의회는 의원 정수의 2분의 1 범위에서 조례로 정한 만큼 정책지원 전문인력을 둘 수 있습니다.","지방자치단체가 국가사무를 수임한 경우 그 처리에 드는 경비는 위임한 국가기관이 부담한다. 수임한 지방자치단체가 부담하지 않는다.":"국가사무를 위임받아 처리하는 경비는 일을 시킨 국가가 부담하고 수임한 지방자치단체가 지지 않습니다.","지방자치단체는 법령의 범위에서 그 사무에 관하여 조례를 제정할 수 있다. 주민의 권리 제한 또는 의무 부과에 관한 사항이나 벌칙은 법률의 위임이 있어야 한다.":"조례는 법령의 범위에서 정하되 주민의 권리 제한이나 의무 부과나 벌칙은 법률의 위임이 있어야 합니다.","지방자치단체는 법령의 범위에서 그 사무에 관하여 조례를 제정할 수 있다. 주민의 권리 제한 또는 의무 부과에 관한 사항이나 벌칙을 정할 때에는 법률의 위임이 있어야 한다.":"조례는 법령 범위에서 정하되 주민의 권리를 제한하거나 벌칙을 정하려면 법률의 위임이 반드시 있어야 합니다.","지방자치단체의 구역에 주소를 가진 자는 그 지방자치단체의 주민이 된다.":"지방자치단체의 구역에 주소를 둔 사람은 그 단체의 주민으로서 지위를 얻습니다.","지방자치단체의 명칭과 구역을 바꾸거나 폐지·설치·분합할 때에는 법률로 정한다. 관할 구역 경계변경과 한자 명칭 변경은 대통령령으로 정한다.":"지자체의 명칭과 구역을 바꾸거나 새로 만들거나 합칠 때는 법률로 정하고 경계변경과 한자 명칭 변경은 대통령령으로 정합니다.","지방자치단체의 장 등이 수임사무의 일부를 재위임하려면 위임기관의 승인을 받아 규칙으로 정하는 바에 따라 시장·군수·구청장 또는 읍·면·동장 등에게 다시 위임할 수 있다.":"지자체장이 수임사무를 재위임하려면 위임기관의 승인을 받아 규칙으로 정한 대로 시장이나 읍면동장 등에게 맡깁니다.","지방자치단체의 장은 관할 구역과 생활권과의 불일치 등 대통령령으로 정하는 사유가 있으면 행정안전부장관에게 경계변경에 대한 조정을 신청할 수 있다. 이 경우 지방의회 재적의원 과반수의 출석과 출석의원 3분의 2 이상의 동의를 받아야 한다.":"관할 구역과 생활권이 맞지 않는 등 사유가 있으면 단체장이 행정안전부장관에게 경계변경 조정을 신청하되 의회 동의가 필요합니다.","지방자치단체의 장은 주민에게 과도한 부담을 주거나 중대한 영향을 미치는 주요 결정사항 등에 대하여 주민투표에 부칠 수 있다. 주민투표 회부권은 지방자치단체의 장에게 있고 지방의회의 권한이 아니다.":"주민에게 큰 영향을 주는 결정은 단체장이 주민투표에 부칠 수 있고 회부 권한은 지방의회가 아니라 단체장에게 있습니다.","지방자치단체의 장은 주민이 보통·평등·직접·비밀선거로 선출하며 임기는 4년으로 3기 내에서만 계속 재임할 수 있다.":"단체장은 주민이 보통과 평등과 직접과 비밀선거로 뽑고 임기 4년에 연속해서 3기까지만 재임할 수 있습니다.","지방자치단체의 장은 지방의회의 의결이 월권이거나 법령에 위반되거나 공익을 현저히 해친다고 인정되면 이송받은 날부터 20일 이내에 이유를 붙여 재의를 요구할 수 있다. 재적의원 과반수 출석과 출석의원 3분의 2 이상 찬성으로 전과 같이 의결하면 확정되고, 법령에 위반된다고 인정되면 대법원에 소를 제기할 수 있다.":"의결이 월권이거나 위법하거나 공익을 해치면 20일 안에 재의를 요구하고 재의결이 위법하다고 보면 대법원에 소를 제기할 수 있습니다.","지방자치단체장이 동일 수탁자에게 위탁사무를 재위탁하고자 할 때 지방의회의 동의를 받도록 한 조례안은 집행권한을 본질적으로 침해하는 것으로 볼 수 없다.":"위탁사무를 재위탁할 때 의회의 동의를 받게 한 조례안은 단체장의 집행권한을 본질적으로 침해하지 않습니다.","직권취소와 철회는 처분의 재심사에 의하여 영향을 받지 아니한다.":"처분의 재심사를 하더라도 행정청의 직권취소와 철회 권한에는 아무 영향이 없습니다.","직무수행 능력이 부족하거나 근무성적이 극히 나쁜 자, 파면·해임·강등 또는 정직에 해당하는 징계 의결이 요구 중인 자, 형사 사건으로 기소된 자(약식명령 청구자 제외), 고위공무원단 적격심사 요구를 받은 자, 금품비위·성범죄 등으로 감사원·수사기관에서 조사나 수사 중인 자로서 비위가 중대하여 정상적인 업무수행을 기대하기 현저히 어려운 자.":"직무 능력이 부족하거나 중한 징계가 요구 중이거나 기소되었거나 중대한 비위로 조사 중인 공무원이 직위해제 대상입니다.","직위: 1명의 공무원에게 부여할 수 있는 직무와 책임. 직급: 직무의 종류·곤란성과 책임도가 상당히 유사한 직위의 군이다.":"직위는 한 사람에게 주어지는 직무와 책임의 단위이고 직급은 직무의 종류와 곤란성과 책임도가 비슷한 직위의 묶음입니다.","직위해제는 징계처분이 아니라 잠정적 보직 박탈이다.":"직위해제는 징계가 아니라 일정 사유가 있을 때 잠정적으로 직위를 맡기지 않는 임시 조치입니다.","직위해제 사유가 소멸되면 임용권자는 지체 없이 직위를 부여하여야 한다. 직무수행 능력 부족 등으로 직위해제된 자에게는 3개월의 범위에서 대기를 명한다.":"직위해제 사유가 사라지면 지체 없이 직위를 다시 주어야 하고 능력 부족이 사유인 경우 3개월 범위에서 대기를 명합니다.","직위해제처분과 그 후속 직권면직처분은 별개 독립의 처분으로 일사부재리원칙에 위배되지 않는다. 직위해제 후 동일한 사유로 다시 해임처분을 하는 것도 일사부재리에 어긋나지 않는다.":"직위해제와 뒤따르는 면직은 서로 다른 독립 처분이라 같은 사유로 거듭 처분해도 일사부재리에 어긋나지 않습니다.","직접강제는 행정대집행이나 이행강제금 부과의 방법으로는 행정상 의무 이행을 확보할 수 없거나 그 실현이 불가능한 경우에 실시하여야 한다.":"직접강제는 강도가 센 수단이라 대집행이나 이행강제금으로 이행을 확보하기 어려울 때에만 보충적으로 씁니다.","직접강제를 실시하기 위하여 현장에 파견되는 집행책임자는 집행책임자임을 표시하는 증표를 보여 주어야 한다. 직접강제의 계고 및 통지에는 이행강제금의 계고·통지 규정을 준용한다.":"직접강제 현장의 집행책임자도 증표를 보여 주어야 하며 계고와 통지는 이행강제금의 규정을 가져와 적용합니다.","직접 처분을 한 경우 그 사실을 해당 행정청에 통보하여야 하며, 통보를 받은 행정청은 위원회가 한 처분을 자기가 한 처분으로 보아 관리·감독 등 필요한 조치를 하여야 한다.":"위원회가 직접 처분하면 해당 행정청에 알려야 하고 행정청은 그 처분을 자기가 한 것처럼 관리하고 감독해야 합니다.","직제와 정원의 개폐 또는 예산 감소에 따른 폐직·과원, 휴직 기간 종료 후 복귀하지 않거나 직무를 감당할 수 없을 때, 대기 명령을 받은 자의 능력·근무성적 향상을 기대하기 어려운 때, 전직시험 3회 이상 불합격, 병역 관련 기피·이탈, 필요한 자격증 효력 상실·면허 취소, 고위공무원단 적격심사 부적격 결정.":"직제 개폐로 자리가 없어지거나 대기 후에도 능력 향상이 어렵거나 자격이 상실되는 등의 사유가 있으면 직권으로 면직할 수 있습니다.","진행 중인 재판에 관련된 정보와 범죄의 예방, 수사, 공소의 제기 및 유지, 형의 집행, 교정, 보안처분에 관한 사항으로서 공개될 경우 직무수행을 현저히 곤란하게 하거나 형사피고인의 공정한 재판을 받을 권리를 침해한다고 인정할 만한 상당한 이유가 있는 정보. ‘진행 중인 재판에 관련된 정보’에 해당하여 공개를 거부하기 위해 반드시 그 정보가 진행 중인 재판의 소송기록 자체에 포함되어야 하는 것은 아니다.":"진행 중인 재판이나 수사 정보로 공개 시 직무에 곤란을 주거나 공정한 재판을 침해할 이유가 있으면 소송기록 자체가 아니어도 거부합니다.","질문을 받거나 동행을 요구받은 사람은 형사소송에 관한 법률에 따르지 아니하고는 신체를 구속당하지 아니하며, 그 의사에 반하여 답변을 강요당하지 아니한다.":"불심검문을 받는 사람은 형사소송법에 따르지 않고는 신체를 구속당하지 않고 답변도 강요당하지 않습니다.","질문이나 동행 요구 시 신분을 표시하는 증표를 제시하면서 소속과 성명을 밝히고 목적과 이유를 설명하여야 하며, 동행 장소를 밝혀야 한다.":"질문이나 동행을 요구할 때 증표를 제시하고 소속과 성명과 목적과 이유를 설명하며 동행 장소도 밝혀야 합니다.","질서위반행위의 동기·목적·방법·결과, 위반 이후 당사자의 태도와 정황, 당사자의 연령·재산상태·환경, 그 밖에 필요하다고 인정되는 사유.":"과태료 액수를 정할 때는 위반의 동기와 결과와 위반 후 태도와 당사자의 연령과 재산상태를 함께 고려합니다.","질서위반행위의 성립과 과태료 처분은 행위 시의 법률에 따른다. 행위 후 법률이 변경되어 질서위반행위에 해당하지 아니하게 되거나 과태료가 변경 전보다 가볍게 된 때에는 특별한 규정이 없는 한 변경된 법률을 적용한다.":"위반 성립과 처분은 행위 당시 법률을 따르되 이후 법이 바뀌어 위반이 아니게 되거나 가벼워지면 바뀐 법을 적용합니다.","집행력은 의무가 부과되는 행정행위에서 문제된다.":"집행력은 행정청이 법원을 거치지 않고 의무 이행을 스스로 강제할 수 있는 힘으로 의무를 지우는 처분에서 문제입니다.","집행명령은 새로운 국민의 권리·의무를 정할 수 없다. 상위 법령의 위임이 없으면 새로운 의무를 정할 수 없다.":"위임이 없으면 새로운 권리나 의무를 만들 수 없으므로 집행명령은 상위 법령의 세부 시행에만 머뭅니다.","집행정지결정은 제3자에 대하여도 효력이 있고, 당사자인 행정청과 그 밖의 관계행정청을 기속한다.":"집행정지 결정은 당사자뿐 아니라 제삼자에게도 효력이 미치고 행정청들을 기속합니다.","집행정지결정이 확정된 후 집행정지가 공공복리에 중대한 영향을 미치거나 정지사유가 없어진 때에는 당사자의 신청 또는 직권으로 취소할 수 있다.":"집행정지 후에 공공복리에 중대한 영향이 생기거나 정지 사유가 사라지면 신청이나 직권으로 결정을 취소할 수 있습니다.","집행정지는 부작위위법확인소송에는 인정되지 않는다(준용 규정에 없다).":"부작위에는 집행할 처분 자체가 없으므로 부작위위법확인소송에는 집행정지 규정이 준용되지 않습니다.","집행정지는 처분의 전부 또는 일부에 대하여 할 수 있다. 처분이 가분적이면 일부에 대한 집행정지도 허용된다.":"처분이 나눌 수 있는 내용이면 일부만 집행을 정지하는 것도 가능합니다.","집행정지의 결정 또는 기각의 결정에 대하여는 즉시항고할 수 있다. 집행정지결정에 대한 즉시항고에는 결정의 집행을 정지하는 효력이 없다.":"집행정지의 결정과 기각 모두 즉시항고할 수 있지만 즉시항고가 있어도 집행정지 결정의 집행이 멈추지는 않습니다.","징계위원회 같은 의결기관으로서의 위원회는 의결권만 갖고, 정해진 의사를 대외적으로 표시할 권한은 없다. 대외적 표시는 행정청이 한다.":"징계위원회 같은 의결기관은 결정만 하고 그 결정을 밖으로 표시하는 일은 행정청이 맡습니다.","처리기간은 종류별로 미리 정하여 공표하여야 한다. 부득이한 사유가 있으면 처리기간의 범위에서 한 번만 연장할 수 있고, 연장 사유와 처리 예정 기한을 지체 없이 신청인에게 통지하여야 한다. 정당한 처리기간 내에 처리하지 아니하면 신청인은 해당 행정청 또는 감독 행정청에 신속한 처리를 요청할 수 있다.":"처리기간을 미리 공표하고 연장은 한 번만 하며 사유를 알려야 하고 기간 안에 처리되지 않으면 신속 처리를 요청할 수 있습니다.","처리에 관한 정보를 제공받을 권리, 동의 여부·범위 등을 선택하고 결정할 권리, 처리 여부를 확인하고 열람(사본 발급 포함) 및 전송을 요구할 권리, 처리 정지·정정·삭제 및 파기를 요구할 권리, 처리로 인한 피해를 신속하고 공정한 절차에 따라 구제받을 권리, 완전히 자동화된 처리에 따른 결정을 거부하거나 설명 등을 요구할 권리.":"정보주체는 정보를 제공받고 동의를 선택하고 열람과 전송을 요구하고 정정과 삭제를 요구하고 피해를 구제받는 권리를 가집니다.","처분(제재처분 및 행정상 강제 제외)이 쟁송으로 다툴 수 없게 된 경우(법원의 확정판결이 있는 경우 제외)에도 처분의 근거가 된 사실관계·법률관계가 당사자에게 유리하게 바뀐 경우, 새로운 증거가 있는 경우, 민사소송법 재심사유에 준하는 사유가 있는 경우에는 처분을 한 행정청에 취소·철회·변경을 신청할 수 있다.":"쟁송기간이 지났어도 사정이 유리하게 바뀌거나 새 증거가 생기는 등 사유가 있으면 처분청에 재심사를 신청할 수 있습니다.","처분, 신고, 확약, 위반사실 등의 공표, 행정계획, 행정상 입법예고, 행정예고, 행정지도.":"행정절차법의 적용 대상은 처분과 신고와 확약 등 여덟 가지 행정 활동입니다.","처분, 처분의 집행 또는 절차의 속행 때문에 중대한 손해가 생기는 것을 예방할 필요성이 긴급하다고 인정될 것. 공공복리에 중대한 영향을 미칠 우려가 없을 것. 처분의 효력정지는 집행 또는 절차의 속행의 정지로 목적을 달성할 수 있을 때는 허용되지 않는다.":"집행정지는 중대한 손해를 막을 긴급한 필요가 있고 공공복리에 중대한 영향이 없어야 하며 집행정지로 충분하면 효력정지는 안 됩니다.","처분기준은 해당 처분의 성질에 비추어 되도록 구체적으로 정하여 공표하여야 하고, 변경하는 경우에도 같다. 해당 처분의 성질상 공표가 현저히 곤란하거나 공공의 안전 또는 복리를 현저히 해치는 것으로 인정될 만한 상당한 이유가 있는 경우에는 공표하지 아니할 수 있다.":"처분기준은 구체적으로 정해 공표해야 하고 공표가 현저히 곤란하거나 공공의 안전을 해칠 경우만 공표하지 않을 수 있습니다.","처분등을 취소하는 판결에 의하여 권리 또는 이익의 침해를 받은 제3자는 자기에게 책임 없는 사유로 소송에 참가하지 못해 방어방법을 제출하지 못한 때 재심을 청구할 수 있다. 확정판결이 있음을 안 날부터 30일 이내, 확정된 날부터 1년 이내에 제기한다.":"취소판결로 권익을 침해받은 제삼자는 책임 없는 사유로 참가하지 못했다면 안 날부터 30일 안, 확정일부터 1년 안에 재심을 청구합니다.","처분등을 취소하는 확정판결은 그 사건에 관하여 당사자인 행정청과 그 밖의 관계행정청을 기속한다. 판결에 의하여 취소되는 처분이 신청을 거부하는 것이면 판결의 취지에 따라 다시 이전의 신청에 대한 처분을 하여야 하고, 신청에 따른 처분이 절차의 위법을 이유로 취소되는 경우에도 같다.":"취소판결은 관계 행정청을 기속하여 거부처분이 취소되면 판결 취지에 따라 이전 신청에 다시 처분해야 하고 절차 위법 취소도 같습니다.","처분등을 취소하는 확정판결은 제3자에 대하여도 효력이 있다(형성력, 대세효).":"취소 확정판결은 소송 당사자만이 아니라 제삼자에게도 미치는 형성력과 대세효가 있습니다.","처분등을 취소하는 확정판결은 제3자에 대하여도 효력이 있다.":"취소 확정판결의 형성력은 소송에 참여하지 않은 제삼자에게도 미칩니다.","처분등을 할 정당한 권한이 없는 행정청도 처분명의자라면 항고소송의 피고가 될 수 있다(처분명의자가 피고).":"권한이 없는 행정청이라도 자기 이름으로 처분했다면 처분명의자로서 항고소송의 피고가 됩니다.","처분등의 효력 유무 또는 존재 여부가 민사소송의 선결문제로 되어 수소법원이 심리·판단하는 경우 제17조, 제25조, 제26조, 제33조를 준용하며 수소법원은 처분등을 행한 행정청에게 그 사실을 통지하여야 한다.":"민사소송에서 처분의 효력이 선결문제가 되어 판단하는 법원은 처분 행정청에 사실을 통지하며 관련 규정이 준용됩니다.","처분등의 효력 유무 또는 존재 여부의 확인을 구할 법률상 이익이 있는 자가 제기할 수 있다.":"무효등 확인소송은 처분의 효력 유무나 존재 여부를 확인받을 법률상 이익이 있는 사람이 제기할 수 있습니다.","처분 또는 부작위가 위법·부당하다고 상당히 의심되는 경우로서 당사자가 받을 우려가 있는 중대한 불이익이나 급박한 위험을 막기 위하여 임시지위를 정하여야 할 필요가 있을 때 결정한다.":"위법 부당이 상당히 의심되고 중대한 불이익이나 급박한 위험을 막기 위해 잠정적 지위를 정해 줄 필요가 있을 때 임시처분을 합니다.","처분사유 설명서를 받은 공무원이 불복할 때에는 설명서를 받은 날부터, 그 밖의 불리한 처분은 그 처분이 있은 것을 안 날부터 30일 이내에 소청심사위원회에 심사를 청구할 수 있다.":"설명서를 받은 날부터 또는 불리한 처분을 안 날부터 30일 안에 소청심사위원회에 심사를 청구할 수 있습니다.","처분에 오기, 오산 또는 그 밖에 이에 준하는 명백한 잘못이 있을 때에는 직권으로 또는 신청에 따라 지체 없이 정정하고 그 사실을 당사자에게 통지하여야 한다.":"처분에 오기나 오산 같은 명백한 잘못이 있으면 직권이나 신청으로 곧바로 고치고 당사자에게 알려야 합니다.","처분에 이의가 있는 당사자는 처분을 받은 날부터 30일 이내에 해당 행정청에 이의신청을 할 수 있다. 행정청은 이의신청을 받은 날부터 14일 이내에 결과를 통지하고, 부득이한 사유가 있으면 만료일 다음 날부터 10일의 범위에서 한 차례 연장할 수 있다.":"처분을 받은 날부터 30일 안에 이의신청을 하면 행정청은 14일 안에 결과를 알리고 부득이하면 10일 범위에서 한 번 늘립니다.","처분은 권한이 있는 기관이 취소 또는 철회하거나 기간의 경과 등으로 소멸되기 전까지는 유효한 것으로 통용된다. 무효인 처분은 처음부터 효력이 발생하지 아니한다.":"처분은 권한 있는 기관이 없애기 전까지 일단 유효하게 통용되지만 무효인 처분은 처음부터 효력이 없습니다.","처분은 권한이 있는 기관이 취소·철회하거나 기간의 경과 등으로 소멸되기 전까지 유효한 것으로 통용된다. 실정법상 공정력을 규정한 조문으로 행정기본법 제15조가 있다.":"공정력은 위법한 처분이라도 권한 있는 기관이 없애기 전까지는 유효한 것으로 통용되는 힘이며 행정기본법에 조문이 있습니다.","처분은 문서로 하여야 한다. 당사자등의 동의가 있거나 당사자가 전자문서로 신청한 경우에는 전자문서로 할 수 있다. 공공의 안전 또는 복리를 위하여 긴급히 처분을 할 필요가 있거나 사안이 경미한 경우에는 말, 전화, 문자 전송, 팩스 또는 전자우편 등 문서가 아닌 방법으로 할 수 있다. 당사자가 요청하면 지체 없이 문서를 주어야 한다.":"처분은 문서가 원칙이고 동의나 전자 신청이면 전자문서로, 긴급하거나 경미하면 말이나 전화로도 하되 요청 시 문서를 줍니다.","처분을 구하는 신청은 문서로 하여야 한다. 다른 법령등에 특별한 규정이 있거나 행정청이 미리 다른 방법을 정하여 공시한 경우는 예외다.":"처분 신청은 문서로 해야 하고 다른 법령의 규정이나 행정청이 미리 공시한 다른 방식이 있다면 예외입니다.","처분을 하는 문서에는 처분 행정청과 담당자의 소속·성명 및 연락처를 적어야 한다.":"처분 문서에는 책임 소재와 문의처를 알 수 있도록 행정청과 담당자의 소속과 성명과 연락처를 적어야 합니다.","처분을 한 행정청(의무이행심판은 청구인의 신청을 받은 행정청)이다. 권한이 다른 행정청에 승계된 경우 승계한 행정청이 피청구인이다.":"피청구인은 처분을 한 행정청이며 의무이행심판은 신청을 받은 행정청이고 권한이 승계되면 승계한 행정청입니다.","처분을 할 때에는 당사자에게 행정심판 및 행정소송을 제기할 수 있는지 여부, 청구절차 및 청구기간, 그 밖에 필요한 사항을 알려야 한다.":"처분할 때 불복할 수 있는지와 절차와 기간을 함께 알려 주어 당사자가 권리를 행사할 수 있게 합니다.","처분을 할 때에는 처분의 상대방에게 행정심판을 청구할 수 있는지, 심판청구 절차 및 청구 기간을 알려야 한다. 이해관계인이 요구하면 지체 없이 알려 주어야 한다.":"처분을 할 때 상대방에게 심판 청구 가능 여부와 절차와 기간을 알려야 하고 이해관계인이 요구하면 곧바로 알려야 합니다.","처분의 신청을 한 자로서 부작위의 위법의 확인을 구할 법률상 이익이 있는 자만이 제기할 수 있다.":"부작위위법확인소송은 처분을 신청한 사람 중 위법 확인에 법률상 이익이 있는 사람만 제기합니다.","처분의 위법은 물론 부당한 경우에도 직권취소의 사유가 된다. 수익적 처분에 대한 직권취소의 필요성에 관한 증명책임은 처분청에 있다.":"처분이 위법하거나 부당하면 직권취소할 수 있고 수익적 처분을 취소할 필요가 있다는 점은 처분청이 증명해야 합니다.","처분의 전제가 되는 사실이 경찰의 수사에 의하여 객관적으로 증명된 사항은 적용 제외 사항이 아니다. 법원의 재판 등에 의하여 객관적으로 증명된 경우는 사전통지 생략 사유(제21조 제4항 제2호)다.":"경찰 수사로 사실이 증명되었다는 이유로는 적용 제외가 안 되고 법원 재판으로 증명된 경우만 사전통지를 생략합니다.","처분의 효과가 소멸된 뒤에도 그 처분의 취소로 회복되는 법률상 이익이 있으면 취소소송을 제기할 수 있다.":"효력이 끝난 처분이라도 취소하면 회복되는 이익이 남아 있다면 협의의 소익이 있어 취소소송이 가능합니다.","처분의 효력정지는 처분등의 집행 또는 절차의 속행을 정지함으로써 목적을 달성할 수 있는 경우에는 허용되지 아니한다.":"효력정지는 가장 강한 조치라서 집행이나 절차의 정지만으로 충분하다면 허용되지 않는 보충성이 있습니다.","처분이 있었던 날부터 180일이 지나면 청구하지 못한다. 정당한 사유가 있는 경우에는 예외다.":"처분이 있었던 날부터 180일이 지나면 정당한 사유가 없는 한 심판을 청구할 수 없습니다.","처분이 행정규칙을 위반하였다고 해서 그러한 사정만으로 곧바로 위법하게 되는 것은 아니다. 행정규칙에 따른 처분의 적법성은 상위법령의 규정과 입법 목적 등에 적합한지 여부에 따라 판단한다.":"규칙을 어겼다고 곧바로 위법한 것이 아니며 상위법령과 입법 목적에 맞는지를 기준으로 적법성을 따집니다.","처분청 스스로도 당해 행정행위에 구속되어 직권으로 취소·변경할 수 없는 것. 행정청을 구속하는 효력이다.":"불가변력은 처분을 한 행정청 자신이 그 처분에 묶여 스스로 취소나 변경을 할 수 없게 하는 효력입니다.","처분청은 그 처분의 성립에 하자가 있는 경우 이를 취소할 별도의 법적 근거가 없다고 하더라도 직권으로 취소할 수 있다.":"처분청은 처분에 처음부터 하자가 있다면 취소를 허용하는 별도의 법 조항이 없어도 직권으로 취소할 수 있습니다.","처음에는 흠이 있었으나 사후에 보완되거나 사정이 변하여 적법해지는 것. 쟁송제기 이전에 가능하다.":"하자의 치유는 처음 흠이 있었더라도 나중에 보완되어 적법해지는 것이며 쟁송을 제기하기 전에만 가능합니다.","천재, 사변, 인공구조물의 파손이나 붕괴, 교통사고, 위험물의 폭발 등의 사태가 있을 때 경고, 이동 제한·대피, 원인 제공자의 퇴거·접근 금지, 관계인에게 위해를 방지하기 위해 필요하다고 인정되는 조치를 하게 하거나 직접 그 조치를 하는 것.":"재난이나 폭발 같은 위험이 생기면 경찰관이 경고하고 대피시키고 접근을 막거나 관계인에게 조치를 명하고 직접 조치할 수도 있습니다.","천재지변, 전쟁, 사변, 그 밖의 불가항력으로 청구기간 내에 청구할 수 없었을 때에는 사유가 소멸한 날부터 14일(국외에서 청구하는 경우 30일) 이내에 청구할 수 있다.":"불가항력으로 기간을 지키지 못하면 그 사유가 없어진 날부터 14일 안에, 국외라면 30일 안에 청구할 수 있습니다.","천재지변이나 그 밖에 당사자등에게 책임이 없는 사유로 기간 및 기한을 지킬 수 없는 경우에는 그 사유가 끝나는 날까지 기간의 진행이 정지된다.":"천재지변처럼 당사자 책임이 아닌 사유로 기간을 못 지키면 그 사유가 끝날 때까지 기간이 멈춥니다.","철거대집행 계고처분 후속의 대집행영장발부통보처분의 취소소송에서는 선행처분인 계고처분의 위법을 이유로 대집행영장발부통보처분이 위법하다고 주장할 수 있다(하자의 승계 인정).":"계고처분의 위법을 대집행영장 통보처분의 취소소송에서 주장할 수 있으므로 하자의 승계가 인정됩니다.","철거명령과 계고처분은 계고서라는 명칭의 1장의 문서로 이루어질 수 있다. 철거대집행 계고처분 후 행한 제2차 계고는 대집행기한의 연기통지에 불과하고 새로운 철거의무를 부과한 것이 아니다.":"철거명령과 계고를 한 장의 계고서로 할 수 있고 뒤의 제2차 계고는 새로운 의무가 아니라 기한 연기 통지일 뿐입니다.","철회의 전부 또는 일부를 장래를 향하여 할 수 있다. 철회하려는 경우에는 철회로 인하여 당사자가 입게 될 불이익을 철회로 달성되는 공익과 비교·형량하여야 한다. 예외 없이 형량이 필요하다.":"철회는 앞으로만 효력이 있고 직권취소와 달리 예외 없이 당사자의 불이익과 공익을 비교해야 합니다.","청구가 이유 있다고 인정하는 경우에도 인용하는 것이 공공복리에 크게 위배된다고 인정하면 심판청구를 기각하는 재결을 할 수 있다. 이 경우 재결의 주문에서 처분 또는 부작위가 위법하거나 부당하다는 것을 구체적으로 밝혀야 한다.":"청구가 타당해도 인용하면 공공복리에 크게 어긋날 때 기각하는 사정재결이며 주문에 처분의 위법이나 부당을 밝혀야 합니다.","청구기간 규정(제1항~제6항)은 무효등확인심판청구와 부작위에 대한 의무이행심판청구에는 적용하지 않는다.":"무효등확인심판과 부작위에 대한 의무이행심판은 언제든 청구할 수 있어 청구기간 규정이 적용되지 않습니다.","청구인은 간접강제 결정에 불복하는 경우 그 결정에 대하여 행정소송을 제기할 수 있다.":"간접강제 결정에 불복하는 청구인은 그 결정을 대상으로 행정소송을 제기할 수 있습니다.","청구인은 위원회 의결이 있을 때까지 서면으로 심판청구를 취하할 수 있다.":"청구인은 위원회가 의결하기 전이라면 서면으로 심판청구를 거둘 수 있습니다.","청구인은 이의신청 절차를 거치지 아니하고 행정심판을 청구할 수 있다.":"이의신청은 선택이라서 청구인은 이를 거치지 않고 곧바로 행정심판을 청구할 수 있습니다.","청구인의 배우자, 청구인 또는 배우자의 사촌 이내의 혈족, 법인의 소속 임직원, 변호사, 다른 법률에 따라 심판청구를 대리할 수 있는 자, 위원회의 허가를 받은 자.":"청구인의 가족과 법인 임직원과 변호사와 위원회 허가를 받은 사람이 청구인을 대리해 심판을 할 수 있습니다.","청구인이 경제적 능력으로 인해 대리인을 선임할 수 없는 경우에는 행정심판위원회에 국선대리인을 선임하여 줄 것을 신청할 수 있다.":"경제적 사정으로 대리인을 구할 수 없으면 행정심판위원회에 국선대리인을 선임해 달라고 신청할 수 있습니다.","청문은 당사자가 공개를 신청하거나 청문 주재자가 필요하다고 인정하는 경우 공개할 수 있다. 공익 또는 제3자의 정당한 이익을 현저히 해칠 우려가 있는 경우에는 당사자가 공개를 신청하더라도 공개하여서는 아니 된다.":"청문은 당사자 신청이나 주재자 판단으로 공개할 수 있지만 공익이나 제삼자 이익을 크게 해치면 신청해도 공개하지 않습니다.","청문을 하려면 청문이 시작되는 날부터 10일 전까지 통지하여야 한다.":"청문은 준비할 시간을 주기 위해 시작되는 날로부터 10일 전까지는 당사자에게 알려야 합니다.","청문이나 공청회를 하는 경우가 아니면서 의무를 부과하거나 권익을 제한하는 처분을 할 때에는 당사자등에게 의견제출의 기회를 주어야 한다.":"청문이나 공청회가 없는 불이익 처분이라도 당사자가 입장을 밝힐 수 있도록 의견제출 기회를 줘야 합니다.","청문 주재자는 독립하여 공정하게 직무를 수행하며, 직무 수행을 이유로 본인의 의사에 반하여 신분상 불이익을 받지 아니한다. 벌칙 적용에서는 공무원으로 본다.":"청문 주재자는 독립해서 공정하게 일하고 직무 때문에 불이익을 받지 않으며 벌칙 적용에서는 공무원으로 봅니다.","청문 주재자는 소속 직원 또는 대통령령으로 정하는 자격을 가진 사람 중에서 공정하게 선정한다. 다수 국민의 이해가 상충되는 처분, 다수 국민에게 불편이나 부담을 주는 처분, 그 밖에 전문적이고 공정한 청문을 위하여 필요하다고 인정하는 처분을 하려는 경우에는 청문 주재자를 2명 이상으로 선정할 수 있다. 이 경우 1명이 대표한다.":"청문 주재자는 자격 있는 사람 중 공정하게 정하고 중요한 처분에서는 2명 이상으로 하되 그중 1명이 대표합니다.","청문 주재자는 직권으로 또는 당사자의 신청에 따라 필요한 조사를 할 수 있으며, 당사자등이 주장하지 아니한 사실에 대하여도 조사할 수 있다. 필요하다고 인정할 때 관계 행정청에 필요한 문서의 제출 또는 의견의 진술을 요구할 수 있고, 관계 행정청은 직무 수행에 특별한 지장이 없으면 따라야 한다.":"주재자는 직권으로 당사자가 말하지 않은 사실까지 조사할 수 있고 관계 행정청에 문서 제출이나 의견 진술을 요구합니다.","청문 주재자는 청문을 시작할 때 먼저 예정된 처분의 내용, 그 원인이 되는 사실 및 법적 근거 등을 설명하여야 한다. 당사자등은 의견을 진술하고 증거를 제출할 수 있으며 참고인이나 감정인 등에게 질문할 수 있다. 의견서를 제출하면 출석하여 진술한 것으로 본다.":"청문은 주재자가 예정 처분의 내용과 근거를 먼저 설명하고 당사자가 진술과 증거 제출과 질문을 할 수 있으며 의견서는 진술로 칩니다.","청문 주재자는 청문조서를 작성하고, 청문을 마치면 청문조서, 의견서, 그 밖의 관계 서류를 행정청에 지체 없이 제출한다. 행정청은 처분 시 청문 결과를 상당한 이유가 있다고 인정하면 반영하여야 한다.":"주재자는 청문조서를 쓰고 마치면 관련 서류를 행정청에 내며 행정청은 결과가 타당하다고 인정하면 처분에 반영해야 합니다.","총괄청이나 중앙관서의 장은 소유자 없는 부동산을 국유재산으로 취득한다. 6개월 이상의 기간을 정하여 이의를 제기할 수 있다는 뜻을 공고하여야 하고, 취득한 국유재산은 등기일부터 10년간 처분하지 못한다.":"주인 없는 부동산은 6개월 이상의 이의 제기 기간을 공고한 뒤 국유재산으로 취득하고 등기일부터 10년간 처분하지 못합니다.","총리령·부령은 법률이나 대통령령의 위임 또는 직권으로 발한다.":"총리령과 부령은 법률이나 대통령령이 위임했을 때뿐 아니라 직권으로도 발령할 수 있습니다.","촬영 사실을 명확히 표시하여 정보주체가 촬영 사실을 알 수 있도록 하였음에도 촬영 거부 의사를 밝히지 아니한 경우는 이동형 영상정보처리기기의 촬영 허용 사유이고, 고정형 설치·운영 허용 사유가 아니다.":"촬영을 알렸는데도 거부하지 않은 경우는 이동형 기기에만 인정되는 사유이고 고정형 설치의 허용 사유가 아닙니다.","취득하는 토지는 부동산 가격공시법에 따른 공시지가를 기준으로 하되 이용계획, 지가변동률, 생산자물가상승률, 위치·형상·환경·이용상황 등을 고려하여 평가한 적정가격으로 보상한다.":"토지 보상은 공시지가를 기준으로 하고 지가변동률과 위치와 이용상황 등을 반영해 평가한 적정가격으로 합니다.","취득한 토지가 사업의 폐지·변경 등으로 필요 없게 된 경우 일정 기간 안에 보상금 상당 금액을 지급하고 환매할 수 있다.":"사업이 폐지되거나 변경되어 땅이 필요 없어지면 원래 소유자가 일정 기간 안에 보상금 상당액을 내고 되살 수 있습니다.","취소소송(위법한 처분등을 취소 또는 변경), 무효등 확인소송(처분등의 효력 유무 또는 존재 여부 확인), 부작위위법확인소송(부작위가 위법하다는 것을 확인)의 3가지다.":"항고소송은 처분을 취소하거나 바꾸는 취소소송, 효력을 확인하는 무효등 확인소송, 부작위의 위법을 확인하는 소송의 세 가지입니다.","취소소송과 관련청구소송(처분등과 관련되는 손해배상·부당이득반환·원상회복 등 청구소송, 처분등과 관련되는 취소소송)이 각각 다른 법원에 계속되는 경우 관련청구소송이 계속된 법원이 상당하다고 인정하면 취소소송이 계속된 법원으로 이송할 수 있다. 취소소송에는 사실심의 변론종결시까지 관련청구소송을 병합할 수 있다.":"취소소송과 관련청구가 다른 법원에 있으면 이송할 수 있고 취소소송에는 변론종결 때까지 관련청구소송을 병합할 수 있습니다.","취소소송은 다른 법률에 특별한 규정이 없는 한 처분등을 행한 행정청을 피고로 한다. 처분등이 있은 뒤 권한이 다른 행정청에 승계된 때에는 승계한 행정청이 피고다. 행정청이 없게 된 때에는 사무가 귀속되는 국가 또는 공공단체를 피고로 한다.":"피고는 처분한 행정청이고 권한이 승계되면 승계한 행정청이며 행정청이 없어지면 사무가 귀속되는 국가나 공공단체입니다.","취소소송은 법령의 규정에 의하여 처분에 대한 행정심판을 제기할 수 있는 경우에도 이를 거치지 아니하고 제기할 수 있다(임의적 전치). 다른 법률에 재결을 거치지 않으면 제기할 수 없다는 규정이 있는 경우에는 그에 따른다(필요적 전치).":"행정심판은 원칙적으로 거치지 않아도 되는 임의적 전치이고 다른 법률이 재결을 거치도록 정하면 필요적 전치가 됩니다.","취소소송은 처분등을 대상으로 한다. 재결취소소송은 재결 자체에 고유한 위법이 있음을 이유로 하는 경우에 한한다(원처분주의).":"취소소송은 원래의 처분을 대상으로 하고 재결을 다투려면 재결 자체의 고유한 위법을 이유로 해야 하는 원처분주의입니다.","취소소송은 처분등의 취소를 구할 법률상 이익이 있는 자가 제기할 수 있다. 처분의 효과가 기간의 경과, 집행 등으로 소멸된 뒤에도 취소로 회복되는 법률상 이익이 있는 자는 제기할 수 있다.":"취소소송의 원고는 법률상 이익이 있어야 하고 처분 효과가 사라진 뒤에도 취소로 회복할 이익이 남아 있으면 제기할 수 있습니다.","취소소송은 처분등이 있음을 안 날부터 90일 이내에 제기하여야 하고, 처분등이 있은 날부터 1년이 지나면 제기하지 못한다. 정당한 사유가 있으면 예외다. 90일은 불변기간이다.":"취소소송은 처분을 안 날부터 90일 안에, 처분이 있은 날부터 1년 안에 내야 하고 90일은 법원이 늘릴 수 없는 불변기간입니다.","취소소송의 제1심 관할법원은 피고의 소재지를 관할하는 행정법원이다. 중앙행정기관 등을 피고로 하는 경우에는 대법원소재지를 관할하는 행정법원에 제기할 수 있다.":"제1심은 피고 소재지의 행정법원이 관할하고 중앙행정기관 등이 피고이면 대법원 소재지의 행정법원에도 낼 수 있습니다.","취소소송의 제기는 처분등의 효력이나 그 집행 또는 절차의 속행에 영향을 주지 아니한다(집행부정지 원칙).":"취소소송을 제기해도 처분의 효력이나 집행이 멈추지 않는 집행부정지가 원칙입니다.","취소소송이 제기되었을 것, 처분등이나 그 집행 또는 절차의 속행으로 인하여 생길 회복하기 어려운 손해를 예방하기 위한 긴급한 필요가 있을 것, 공공복리에 중대한 영향을 미칠 우려가 없을 것, 본안이 계속 중일 것. 신청인이 이유를 소명한다.":"집행정지는 본안 소송이 걸려 있고 회복하기 어려운 손해를 막을 긴급한 필요가 있으며 공공복리에 중대한 영향이 없어야 합니다.","취소심판(위법 또는 부당한 처분의 취소·변경), 무효등확인심판(효력 유무 또는 존재 여부의 확인), 의무이행심판(신청에 대한 위법 또는 부당한 거부처분이나 부작위에 대하여 일정한 처분을 하도록 하는 심판)의 3가지다.":"행정심판은 처분을 취소하거나 바꾸는 취소심판, 효력을 확인하는 무효등확인심판, 처분을 하도록 하는 의무이행심판의 세 가지입니다.","취소심판은 처분의 취소 또는 변경을 구할 법률상 이익이 있는 자(처분의 효과가 소멸한 뒤에도 취소로 회복되는 법률상 이익이 있는 자 포함), 무효등확인심판은 효력 유무 또는 존재 여부의 확인을 구할 법률상 이익이 있는 자, 의무이행심판은 처분을 신청한 자로서 거부처분 또는 부작위에 대하여 일정한 처분을 구할 법률상 이익이 있는 자.":"청구인은 심판 종류별로 법률상 이익이 있는 사람이며 의무이행심판은 처분을 신청한 사람이어야 합니다.","침해유보설, 권력행위유보설, 급부행정유보설, 전부유보설, 중요사항유보설(본질성설).":"법률유보의 범위를 어디까지 볼지에 대한 학설이 다섯 가지로 나뉘며 각각 대상 행정 영역이 다릅니다.","타인을 감독하는 자가 타인의 행위에 대하여 지는 경찰책임은 타인의 책임을 대신하여 지는 것이 아니라 자기의 감독의무 위반에 대한 자기책임이다.":"감독자의 경찰책임은 남의 책임을 대신 지는 것이 아니라 자신의 감독의무를 소홀히 한 데 대한 자기책임입니다.","텔레비전방송수신료 금액의 결정은 수신료에 관한 본질적으로 중요한 사항이므로 국회가 스스로 행하여야 한다. 한국방송공사법이 국회의 결정이나 관여를 배제하고 한국방송공사가 금액을 결정해 문화관광부장관의 승인을 얻도록 한 것은 법률유보원칙에 위반된다.":"수신료 금액은 본질적으로 중요해 국회가 정해야 하므로 공사가 정해 장관 승인을 받게 한 법은 위반입니다.","토지대장상의 소유자명의변경신청 거부행위는 항고소송의 대상이 되는 처분이 아니다. 어업권 면허에 선행하는 우선순위결정은 확약에 불과하여 항고소송의 대상이 아니다.":"토지대장의 소유자명의변경 신청 거부와 어업면허 전 우선순위결정은 권리관계에 직접 영향이 없어 처분이 아닙니다.","토지수용위원회는 심리를 시작한 날부터 14일 이내에 재결을 하여야 한다. 특별한 사유가 있으면 14일의 범위에서 한 차례만 연장할 수 있다.":"심리를 시작한 날부터 14일 안에 재결해야 하고 특별한 사유가 있으면 14일 범위에서 한 번만 연장할 수 있습니다.","토지수용위원회는 재결신청서를 접수하면 공고하고 공고한 날부터 14일 이상 관계 서류의 사본을 일반인이 열람할 수 있도록 하여야 한다.":"위원회는 재결신청서를 받으면 공고하고 공고한 날부터 14일 이상 관계 서류 사본을 누구나 볼 수 있게 해야 합니다.","토지수용위원회의 재결은 서면으로 하며, 재결서에는 주문 및 그 이유와 재결일을 적고 위원장 및 회의에 참석한 위원이 기명날인한 후 정본을 사업시행자, 토지소유자 및 관계인에게 송달하여야 한다.":"재결은 서면으로 하고 주문과 이유와 재결일을 적어 위원장과 참석 위원이 서명한 뒤 정본을 당사자들에게 보냅니다.","토지에 대한 보상액은 가격시점에서의 현실적인 이용상황과 일반적인 이용방법에 의한 객관적 상황을 고려해 산정하고, 일시적 이용상황과 주관적 가치, 특별한 용도 사용을 전제로 한 경우 등은 고려하지 않는다.":"보상액은 가격시점의 현실적이고 일반적인 이용상황으로 정하고 일시적 이용과 주관적 가치는 반영하지 않습니다.","토지형질변경행위허가에 부관을 붙일 필요가 있는지 판단함에 있어서는 허가권자에게 재량의 여지가 있다.":"토지형질변경 허가에 부관이 필요한지는 허가권자가 재량으로 판단할 여지가 있습니다.","통계작성, 과학적 연구, 공익적 기록보존 등을 위하여 정보주체의 동의 없이 처리할 수 있다. 제3자에게 제공할 때 특정 개인을 알아보기 위하여 사용될 수 있는 정보를 포함해서는 아니 된다.":"통계와 연구와 기록보존을 위한 가명정보는 동의 없이 처리하되 제삼자에게 줄 때는 개인을 알아볼 수 있는 정보를 빼야 합니다.","특별행정심판이나 행정심판 절차 특례는 사안의 전문성과 특수성을 살리기 위하여 특히 필요한 경우 외에는 다른 법률로 정할 수 없다. 특별행정심판에서 규정하지 않은 사항은 행정심판법에 따른다.":"특별행정심판은 전문성이 꼭 필요한 경우에만 다른 법률로 정할 수 있고 거기에 없는 사항은 행정심판법을 따릅니다.","특정인에게 권리·능력·포괄적 법률관계를 설정하는 형성적 행위. 재량행위다.":"특허는 특정인에게 새로운 권리나 능력을 설정해 주는 형성적 행위이며 재량행위입니다.","특정한 행정목표를 달성하기 위하여 서로 관련되는 행정수단을 종합·조정함으로써 장래의 일정한 시점에 일정한 질서를 실현하기 위한 활동기준으로 설정된 것.":"행정계획은 여러 행정수단을 종합하고 조정해 미래에 일정한 질서를 이루려고 정한 활동 기준입니다.","파면과 해임은 징계위원회의 의결을 거쳐 각 임용권자 또는 임용권을 위임한 상급 감독기관의 장이 한다.":"파면과 해임처럼 중한 징계는 징계위원회 의결 후 임용권자나 임용권을 위임한 상급기관의 장이 합니다.","파면 또는 해임 처분에 대한 소청에서 후임자 보충발령은 처분일부터 40일 이내에는 하지 못하며, 소청심사위원회는 청구 접수일부터 5일 이내에 후임자 보충발령 유예 임시결정을 할 수 있다.":"파면이나 해임의 소청 중에는 처분일부터 40일 이내에 후임자를 보충발령하지 못하게 해 소청인의 복직 가능성을 보호합니다.","파면·해임·강등·정직·감봉·견책의 6가지.":"징계의 종류는 중한 순서로 파면과 해임과 강등과 정직과 감봉과 견책의 여섯 가지입니다.","피대리 행정청의 수권에 의하여 대리관계가 성립한다. 일반적·포괄적 수권은 허용되지 않는다.":"임의대리는 대리를 시키는 행정청의 수권으로 성립하며 포괄적으로 전부를 맡기는 수권은 허용되지 않습니다.","피성년후견인, 파산선고를 받고 복권되지 아니한 자, 금고 이상 실형 집행 종료·면제 후 5년 미경과, 금고 이상 집행유예 기간 종료 후 2년 미경과, 금고 이상 선고유예 기간 중, 법원 판결 또는 법률에 따라 자격 상실·정지된 자, 일정 범죄(공무원 재직 중 직무 관련 횡령·배임 300만원 이상 벌금 후 2년 미경과 등), 징계 파면 후 5년 미경과, 징계 해임 후 3년 미경과.":"피성년후견인과 파산자와 일정 형을 마친 지 얼마 안 된 사람과 징계로 파면이나 해임된 지 얼마 안 된 사람은 임용될 수 없습니다.","피청구인은 심판청구가 이유 있다고 인정하면 직권으로 처분을 취소·변경하거나 확인을 하거나 신청에 따른 처분을 할 수 있다.":"피청구인이 청구가 타당하다고 보면 위원회 결정을 기다리지 않고 스스로 처분을 취소하거나 변경하거나 신청한 처분을 할 수 있습니다.","피청구인은 심판청구서를 받으면 10일 이내에 심판청구서(또는 답변서)를 위원회에 보내야 한다. 답변서에는 처분의 근거와 이유, 청구 취지·이유에 대응하는 답변을 적는다.":"피청구인은 청구서를 받으면 10일 안에 답변서와 함께 위원회에 보내고 답변서에는 처분의 근거와 이유와 청구에 대한 답변을 적습니다.","피청구인이 제49조 제2항(제4항 준용 포함) 또는 제3항에 따른 처분을 하지 아니하면 청구인의 신청에 의하여 상당한 기간을 정하고, 그 기간 내에 이행하지 않으면 지연기간에 따라 일정한 배상을 하도록 명하거나 즉시 배상을 할 것을 명할 수 있다.":"행정청이 재처분을 하지 않으면 위원회가 기한을 주고 지연 기간에 따른 배상이나 즉시 배상을 명하는 간접강제를 할 수 있습니다.","피해자가 군인·군무원·경찰공무원 또는 예비군대원이어야 한다.":"이중배상 금지는 피해자가 군인과 군무원과 경찰공무원과 예비군대원에 해당할 때만 적용됩니다.","피해자가 손해를 입은 동시에 이익을 얻은 경우 손해배상액에서 그 이익에 상당하는 금액을 뺀다. 유족배상·장해배상·장래 요양비 등을 한꺼번에 신청하는 경우 중간이자를 뺀다.":"손해와 함께 이익도 얻었다면 그 이익만큼 배상액에서 빼고 장래 배상을 한꺼번에 받으면 앞당겨 받는 중간이자를 뺍니다.","피해자나 그 법정대리인이 손해 및 가해자를 알지 못한 경우 국가배상청구권의 소멸시효 기간은 5년이다.":"손해와 가해자를 모르는 경우 국가배상청구권의 소멸시효는 5년으로 정해져 있습니다.","필요적 전치의 경우에도 동종사건에 관하여 이미 행정심판의 기각재결이 있은 때, 서로 내용상 관련되는 처분 중 어느 하나가 이미 재결을 거친 때, 사실심 변론종결 후 처분이 변경되어 변경된 처분에 관하여 소를 제기하는 때, 행정청이 심판을 거칠 필요가 없다고 잘못 알린 때에는 행정심판을 제기함이 없이 소송을 제기할 수 있다.":"필요적 전치라도 이미 같은 사건에 기각재결이 있거나 관련 처분이 재결을 거쳤거나 행정청이 잘못 알렸다면 심판 없이 소송할 수 있습니다.","필요적 전치의 경우에도 행정심판청구가 있은 날부터 60일이 지나도 재결이 없는 때, 처분의 집행 등으로 생길 중대한 손해를 예방하여야 할 긴급한 필요가 있는 때, 행정심판기관이 의결·재결을 하지 못할 사유가 있는 때, 그 밖의 정당한 사유가 있는 때에는 재결을 거치지 않고 제기할 수 있다.":"필요적 전치라도 60일 지나도 재결이 없거나 긴급한 필요가 있거나 심판기관이 못 하는 사정이면 재결 없이 소송할 수 있습니다.","하급관청 사이에 권한의 분쟁이 있는 경우 상급관청이 그 분쟁을 해결하고 결정하는 권한.":"주관쟁의결정권은 하급관청끼리 권한을 두고 다툴 때 공통의 상급관청이 그 분쟁을 해결하는 권한입니다.","하나의 인허가(주된 인허가)를 받으면 법률로 정하는 바에 따라 그와 관련된 여러 인허가(관련 인허가)를 받은 것으로 보는 것.":"인허가의제는 주된 인허가 하나만 받으면 법에 정해진 관련 인허가를 받은 것으로 인정해 절차를 줄이는 제도입니다.","하나의 행위가 2 이상의 질서위반행위에 해당하는 경우에는 각 질서위반행위에 대하여 정한 과태료 중 가장 중한 과태료를 부과한다. 그 외 2 이상의 질서위반행위가 경합하면 각각 부과한다.":"하나의 행위가 여러 위반에 해당하면 그중 가장 무거운 과태료 하나를 매기고 별개의 행위들은 각각 부과합니다.","하천법상 하천의 점용허가권은 대세적 효력이 있는 물권이 아니다.":"하천 점용허가권은 누구에게나 주장할 수 있는 물권이 아니라 허가에 따른 공법상 권리입니다.","학교폭력대책자치위원회의 회의록은 공개될 경우 업무의 공정한 수행에 현저한 지장을 초래한다고 인정할 만한 상당한 이유가 있는 정보에 해당한다.":"학교폭력대책자치위원회 회의록은 공개되면 위원들의 솔직한 논의가 어려워 업무의 공정한 수행에 지장이 있다고 봅니다.","한국마사회 기수의 면허취소를 다투는 소송은 공법관계가 아니다. 사법관계로서 민사소송으로 다툰다.":"마사회 기수 면허취소는 사법 관계로 보아 행정소송이 아니라 민사소송으로 다툽니다.","한 회계연도의 모든 수입을 세입으로 하고, 모든 지출을 세출로 한다.":"예산총계주의는 모든 수입을 세입으로 모든 지출을 세출으로 빠짐없이 잡아 재정을 투명하게 하는 원칙입니다.","항고소송과 당사자소송 상호간의 소의 변경은 청구의 기초에 변경이 없는 한 사실심 변론종결시까지 법원의 허가로 할 수 있다.":"항고소송과 당사자소송은 청구의 기초가 같으면 변론종결 때까지 법원 허가를 받아 서로 소 종류를 바꿀 수 있습니다.","항고소송에서의 처분사유의 추가·변경 법리는 행정심판에도 적용된다. 처분청은 당초 처분 사유와 기본적 사실관계의 동일성이 인정되는 한도 내에서 다른 사유를 추가·변경할 수 있다.":"처분청은 원래 사유와 기본적 사실관계가 같은 범위에서만 다른 사유를 보태거나 바꿀 수 있고 이는 행정심판에도 적용됩니다.","해당 지방자치단체의 장 및 직원, 지방의회의원, 해당 행위와 관련이 있는 상대방에게 손해배상청구 또는 부당이득반환청구를 할 것을 요구하는 소송. 지방의회의원에게 손해배상청구를 요구하는 주민소송도 인정된다.":"주민이 단체를 대신해 단체장이나 직원이나 의원이나 상대방에게 손해배상과 부당이득반환을 청구하라고 요구하는 유형입니다.","해당 처분의 목적에 위배되지 아니할 것, 해당 처분과 실질적인 관련이 있을 것, 해당 처분의 목적을 달성하기 위하여 필요한 최소한의 범위일 것.":"부관은 처분의 목적에 어긋나지 않고 처분과 실질적으로 관련되고 필요한 최소한의 범위여야 합니다.","해당 행위를 계속하면 회복하기 어려운 손해가 발생할 우려가 있는 경우 그 행위의 전부나 일부를 중지할 것을 요구하는 소송.":"주민소송 중 중지청구는 행위를 계속하면 회복하기 어려운 손해가 생길 때 그 행위를 멈추게 하는 소송입니다.","행위능력이 없는 자도 경찰책임자가 될 수 있다.":"경찰책임은 위험을 일으킨 사실을 기준으로 하므로 행위능력이 없는 사람도 책임자가 될 수 있습니다.","행위요건적 신고(수리를 요하는 신고): 수리 거부에 대해 항고소송이 가능하고, 수리가 있어야 법적 효과가 발생한다.":"수리를 요하는 신고는 수리되어야 효과가 생기고 수리를 거부하면 이를 항고소송으로 다툴 수 있습니다.","행위책임의 행위에는 부작위를 포함한다.":"행위책임은 적극적으로 위험을 일으킨 행위뿐 아니라 해야 할 일을 하지 않은 부작위도 포함합니다.","행정계획은 사인의 신뢰보호를 위해 일반적으로 계획존속청구권이 인정되는 것이 아니다. 계획변경청구권도 원칙적으로 부정되고, 예외적으로 특별한 사정이 있는 경우에만 인정된다.":"계획을 유지해 달라는 청구권은 일반적으로 없고 변경 청구권도 원칙적으로 부정되며 특별한 사정이 있을 때만 예외입니다.","행정규칙에 의한 불문경고조치는 항고소송의 대상이 되는 행정처분에 해당하지 아니한다(2025 기출).":"불문경고는 행정규칙에 따른 내부적 조치라 국민의 권리의무에 직접 영향을 주지 않아 처분이 아닙니다.","행정규칙에 의한 불문경고조치는 항고소송의 대상이 되는 행정처분에 해당하지 아니한다.":"행정규칙에 따른 불문경고는 국민의 권리의무에 직접 영향을 주지 않아 처분이 아니므로 항고소송 대상이 아닙니다.","행정규칙은 특별한 사정이 없는 한 대외적으로 국민이나 법원을 구속하는 효력이 없다.":"행정규칙은 행정 내부 규범이라 국민이나 법원을 구속하지 못하고 재판에서도 그대로 따를 필요가 없습니다.","행정기관 또는 소속기관을 설치하거나 공무원의 정원을 증원할 때에는 반드시 예산상의 조치가 병행되어야 한다.":"기관을 새로 두거나 정원을 늘릴 때는 필요한 재원이 있어야 하므로 예산상의 조치를 함께 마련해야 합니다.","행정기관 소속 공무원의 징계처분, 그 밖에 그 의사에 반하는 불리한 처분이나 부작위에 대한 소청을 심사·결정하게 하기 위하여 인사혁신처에 소청심사위원회를 둔다. 국회·법원·헌법재판소·선거관리위원회 소속 공무원은 각 사무처에 해당 소청심사위원회를 둔다.":"행정기관 공무원의 징계나 불리한 처분에 대한 소청은 인사혁신처의 소청심사위원회가 심사하고 국회와 법원 등은 각 사무처에 둡니다.","행정기관에는 소관사무의 일부를 독립하여 수행할 필요가 있는 때에는 법률로 정하는 바에 따라 행정위원회 등 합의제행정기관을 둘 수 있다. 정부조직법은 합의제행정기관 설치의 법적 근거를 두고 있다. 지방자치단체는 소관 사무의 일부를 독립하여 수행할 필요가 있으면 법령이나 조례로 정하는 바에 따라 합의제행정기관을 설치할 수 있다.":"사무 일부를 독립해서 수행할 필요가 있으면 법률로 행정위원회 같은 합의제행정기관을 두며 지자체는 법령이나 조례로도 둡니다.","행정기관은 법령으로 정하는 바에 따라 소관사무의 일부를 보조기관 또는 하급행정기관에 위임하거나 다른 행정기관·지방자치단체 또는 그 기관에 위탁 또는 위임할 수 있다.":"행정기관은 법령 범위에서 자기 사무의 일부를 하급기관에 위임하거나 다른 행정기관과 지자체에 위탁할 수 있습니다.","행정기관은 상대방이 행정지도에 따르지 아니하였다는 것을 이유로 불이익한 조치를 하여서는 아니 된다.":"행정지도는 임의적 협력을 구하는 것이라 따르지 않았다는 이유로 불이익을 주면 안 됩니다.","행정기관의 장은 소관사무를 통할하고 소속공무원을 지휘·감독한다.":"행정기관의 장은 맡은 사무 전체를 총괄하고 소속 공무원을 지휘하고 감독하는 권한이 있습니다.","행정기관이 소관 사무의 범위에서 일정한 행정목적을 실현하기 위하여 특정인에게 일정한 행위를 하거나 하지 아니하도록 지도·권고·조언 등을 하는 행정작용.":"행정지도는 강제력 없이 지도와 권고와 조언으로 특정인이 어떤 행위를 하거나 하지 않도록 유도하는 행정작용입니다.","행정기본법에 명문으로 규정된 법원칙은 법치행정, 평등, 비례, 성실의무 및 권한남용금지, 신뢰보호, 부당결부금지의 6개다.":"행정기본법이 직접 조문으로 정한 원칙은 여섯 가지이며 자기구속은 그 안에 들어 있지 않습니다.","행정목적을 달성하는 데 유효하고 적절할 것.":"적합성은 선택한 수단이 목적을 이루는 데 실제로 도움이 되는지를 묻는 비례원칙의 첫 단계입니다.","행정목적을 달성하는 데 필요한 최소한도에 그칠 것.":"같은 효과를 내는 여러 수단 중 국민에게 가장 덜 피해를 주는 수단을 골라야 한다는 요건입니다.","행정법규 위반에 대해 벌금 이외에 과징금을 부과하는 것은 이중처벌금지의 원칙에 반하지 않는다.":"과징금은 형벌이 아닌 행정상 제재라서 벌금과 함께 부과해도 이중처벌금지에 어긋나지 않습니다.","행정법의 법원 중 헌법은 최고법이고, 법률 > 법규명령(대통령령 > 총리령·부령) 순의 단계를 이룬다. 자치법규는 조례 > 규칙 순이다.":"헌법이 가장 위이고 법률, 법규명령 순으로 단계를 이루며 자치법규에서는 조례가 규칙보다 위입니다.","행정상 강제는 법률로 정하는 바에 따라 필요한 최소한의 범위에서 할 수 있다.":"행정상 강제는 국민의 신체나 재산에 영향을 주므로 법률 근거가 있어야 하고 필요한 최소한에 그쳐야 합니다.","행정서비스에 대한 국민의 만족도를 높이기 위하여 필요한 경우는 행정응원 사유가 아니라 행정협업의 방식으로 적극 협조하는 사유(제7조 제2항)다.":"국민 만족도를 높이려는 경우는 응원 요청 사유가 아니라 행정협업의 방식으로 적극 협조하는 별도 사유입니다.","행정소송법은 의무이행소송을 규정하고 있지 않다.":"행정청에게 특정 처분을 하라고 명하는 의무이행소송은 행정소송법상 인정되는 소송 종류가 아닙니다.","행정소송법은 의무이행소송을 명문으로 인정하지 않는다.":"행정청에게 일정한 처분을 하라고 직접 명하는 소송은 행정소송법에 규정이 없습니다.","행정소송에 대하여는 다른 법률에 특별한 규정이 있는 경우를 제외하고는 행정소송법이 정하는 바에 의한다. 행정소송법에 특별한 규정이 없는 사항은 법원조직법, 민사소송법 및 민사집행법을 준용한다.":"행정소송은 행정소송법이 먼저 적용되고 거기에 규정이 없는 사항은 법원조직법과 민사소송법과 민사집행법을 준용합니다.","행정소송에 대한 대법원판결에 의하여 명령·규칙이 헌법 또는 법률에 위반된다는 것이 확정되면 대법원은 지체 없이 그 사유를 행정안전부장관에게 통보하여야 하고, 통보를 받은 행정안전부장관은 지체 없이 이를 관보에 게재하여야 한다.":"대법원이 명령이나 규칙의 위법을 확정하면 행정안전부장관에게 통보하고 장관은 이를 관보에 실어 알립니다.","행정소송에서 재판장은 필요하다고 인정하면 당사자를 참여시키지 않고 제출된 공개 청구 정보를 비공개로 열람·심사할 수 있다.":"재판장은 필요하면 당사자를 참여시키지 않고 비공개 상태로 청구된 정보를 직접 열람해 심사할 수 있습니다.","행정소송은 항고소송, 당사자소송, 민중소송, 기관소송의 네 가지다.":"행정소송은 처분을 다투는 항고소송과 공법상 법률관계를 다투는 당사자소송과 객관소송인 민중소송과 기관소송으로 나뉩니다.","행정소송의 종류에서 정한 항고소송의 대상인 처분에 대해서도 재량권의 한계를 넘거나 남용이 있으면 법원은 취소할 수 있다.":"항고소송의 대상인 재량 처분이라도 재량의 한계를 넘거나 남용했다면 법원이 취소할 수 있습니다.","행정소송이 계속되고 있는 때에도 행정청은 직권으로 해당 처분을 변경할 수 있다. 소송 대상 처분이 변경되면 원고는 청구의 취지·원인의 변경을 신청할 수 있다.":"소송 중에도 행정청은 처분을 스스로 변경할 수 있으며 원고는 변경된 처분에 맞게 청구를 바꿀 수 있습니다.","행정소송 제기기간: 재결서를 받은 날부터 90일 이내, 이의신청을 거쳤을 때에는 이의신청에 대한 재결서를 받은 날부터 60일 이내.":"소송은 재결서를 받은 날부터 90일 안에, 이의신청을 거쳤다면 그 재결서를 받은 날부터 60일 안에 제기해야 합니다.","행정심판 결과에 이해관계가 있는 제3자나 행정청은 위원회 의결이 있기 전까지 심판참가를 할 수 있고, 위원회는 참가를 요구할 수도 있다.":"이해관계 있는 제삼자나 행정청은 의결 전에 스스로 참가하거나 위원회의 요구로 심판에 들어올 수 있습니다.","행정심판법은 당사자심판에 관해서 규정하고 있지 않다.":"행정심판법에는 행정소송과 달리 당사자 사이의 법률관계를 다투는 당사자심판이 규정되어 있지 않습니다.","행정심판은 처분이 있음을 알게 된 날부터 90일 이내에 청구하여야 한다.":"처분을 알게 된 날이 기산점이며 그날부터 90일이 지나면 청구기간이 끝납니다.","행정심판의 심리는 구술심리나 서면심리로 한다. 당사자가 구술심리를 신청한 경우에는 서면심리만으로 결정할 수 있다고 인정되는 경우 외에는 구술심리를 하여야 한다.":"심리는 구술이나 서면으로 하며 당사자가 구술을 신청하면 서면만으로 충분한 경우가 아닌 한 구술심리를 해야 합니다.","행정심판의 재결은 준사법적 행위로서 불가변력이 인정된다. 재결에 대해서도 제소기간 안에 취소소송을 제기할 수 있다.":"재결은 분쟁을 판정하는 준사법 행위라 불가변력이 있고 그래도 제소기간 안이면 취소소송이 가능합니다.","행정심판 재결에서 처분이 일부취소(감액)된 경우 취소소송의 대상은 감액된 원처분이고, 제소기간은 재결서 정본을 송달받은 날부터 기산한다.":"재결로 처분이 일부 줄어들었다면 소송 대상은 감액된 원래 처분이고 제소기간은 재결서를 송달받은 날부터 셉니다.","행정심판청구가 있은 때의 제소기간은 재결서의 정본을 송달받은 날부터 기산한다. 재결이 있은 날부터 1년이 지나면 제기하지 못한다.":"행정심판을 거쳤다면 재결서 정본을 송달받은 날부터 기간을 세고 재결이 있은 날부터 1년이 지나면 낼 수 없습니다.","행정에 관하여 다른 법률에 특별한 규정이 있는 경우를 제외하고는 행정기본법이 정하는 바에 따른다. 행정에 관한 다른 법률을 제정하거나 개정하는 경우에는 행정기본법의 목적과 원칙, 기준 및 취지에 부합되도록 노력하여야 한다.":"행정기본법은 행정에 관한 일반법이라 다른 법에 특별 규정이 없으면 적용되고 새 법도 이 취지에 맞추도록 합니다.","행정에 관한 기간 계산은 행정기본법 또는 다른 법령등에 특별한 규정이 있는 경우를 제외하고는 민법을 준용한다.":"행정 분야의 기간도 특별한 규정이 없으면 민법의 기간 계산 방식을 가져와 셉니다.","행정에 관한 나이는 만(滿) 나이로 계산하고 표시한다. 출생일을 산입하여 계산하며, 만 1세에 이르지 아니한 경우에는 월수로 표시할 수 있다.":"행정에서 나이는 태어난 날을 넣어 만 나이로 세며 한 살이 안 되면 개월 수로 나타낼 수 있습니다.","행정에 관한 의사를 결정하여 표시하는 국가 또는 지방자치단체의 기관, 그 밖에 법령 또는 자치법규에 따라 행정권한을 가지고 있거나 위임 또는 위탁받은 공공단체 또는 그 기관이나 사인.":"행정청은 국가나 지자체의 기관뿐 아니라 법령에 따라 행정권한을 위임이나 위탁받은 공공단체와 사인도 포함합니다.","행정에 관한 의사를 결정하여 표시하는 국가 또는 지방자치단체의 기관.":"행정청은 국가나 지방자치단체를 대표해 행정에 관한 의사를 스스로 정하고 대외적으로 표시하는 기관입니다.","행정의무의 이행확보에 관하여서는 따로 법률로 정하는 것을 제외하고는 행정대집행법이 정하는 바에 의한다.":"행정의무의 이행 확보는 따로 법률이 없으면 행정대집행법이 정한 절차를 따릅니다.","행정의 자기구속의 원칙은 행정기본법에 명문 규정이 없다.":"자기구속의 원칙은 판례와 학설로 인정되는 불문 원칙이어서 행정기본법에는 조문이 없습니다.","행정입법의 부작위는 항고소송으로 다툴 수 없다.":"행정입법을 하지 않은 것은 처분이 아니라서 항고소송으로 다툴 수 없습니다.","행정작용으로 인한 국민의 이익 침해가 그 행정작용이 의도하는 공익보다 크지 아니할 것.":"협의의 비례는 침해되는 사익이 얻으려는 공익을 넘지 않도록 두 이익을 저울질하는 단계입니다.","행정작용은 법률에 위반되어서는 아니 된다(법률우위).":"법률우위는 행정이 이미 있는 법률의 내용에 어긋나게 행동할 수 없다는 소극적 제약입니다.","행정작용의 내용은 구체적이고 명확하여야 한다. 법령등의 내용이 명확하지 아니한 경우 상대방은 해석을 요청할 수 있고, 행정청은 특별한 사유가 없으면 요청에 따라야 한다.":"행정작용은 구체적이고 분명해야 하며 법령 내용이 불명확하면 상대방이 해석을 요청해 설명을 들을 수 있습니다.","행정재산은 민법 제245조에도 불구하고 시효취득의 대상이 되지 아니한다. 기업용재산도 행정재산이므로 시효취득 대상이 아니다. 일반재산은 시효취득의 대상이 된다.":"행정재산은 기업용재산을 포함해 민법의 시효취득 대상이 아니고 일반재산만 시효취득이 가능합니다.","행정재산은 처분하지 못한다. 공유 또는 사유재산과 교환하여 행정재산으로 관리하려는 경우 등 예외적으로 교환하거나 양여할 수 있다.":"행정재산은 처분이 금지되지만 다른 재산과 교환해 행정재산으로 관리하려는 경우 등에는 예외로 교환하거나 양여할 수 있습니다.","행정재산의 사용허가기간은 5년 이내로 한다. 허가기간이 끝난 재산에 대하여 종전 허가기간에 관계없이 5년을 초과하지 않는 범위에서 갱신할 수 있다(수의 허가가 아니면 1회). 갱신 신청은 허가기간이 끝나기 1개월 전에 한다.":"사용허가기간은 5년 이내이고 5년을 넘지 않는 범위에서 갱신할 수 있으며 갱신 신청은 기간이 끝나기 1개월 전에 합니다.","행정재산의 사용허가는 그 뜻을 공고하여 일반경쟁에 부쳐야 한다. 필요하다고 인정되면 참가자격 제한·지명경쟁·수의의 방법으로 할 수 있다.":"행정재산의 사용허가는 공고하여 일반경쟁으로 하는 것이 원칙이고 필요하면 참가자격 제한이나 지명경쟁이나 수의의 방법도 가능합니다.","행정재산의 사용허가 신청에 대한 거부를 다투는 소송은 공법관계(항고소송)다.":"행정재산 사용허가는 행정처분이어서 그 거부를 다투는 소송은 공법관계로서 항고소송으로 합니다.","행정재산이 공용폐지되어 시효취득의 대상이 된다는 증명책임은 시효취득을 주장하는 자에게 있다.":"행정재산이 공용폐지되어 시효취득이 가능해졌다는 점은 시효취득을 주장하는 사람이 증명해야 합니다.","행정절차법에는 공법상 계약에 관한 규정이 없다. 행정절차법이 규정하는 행정절차는 처분, 신고, 확약, 위반사실 등의 공표, 행정계획, 행정상 입법예고, 행정예고 및 행정지도다.":"행정절차법이 다루는 절차에 공법상 계약은 들어 있지 않고 처분, 신고, 확약 등 여덟 가지가 대상입니다.","행정절차에 관하여 다른 법률에 특별한 규정이 있는 경우를 제외하고는 행정절차법이 정하는 바에 따른다. 다른 법률의 특별 규정이 우선한다.":"행정절차법은 일반법이라 다른 법률에 특별한 규정이 있으면 그 규정이 먼저 적용됩니다.","행정절차에 드는 비용은 행정청이 부담한다. 당사자등이 자기를 위하여 스스로 지출한 비용은 그러하지 아니하다.":"절차에 드는 비용은 행정청이 부담하지만 당사자가 자기를 위해 따로 쓴 비용은 당사자 몫입니다.","행정주체가 기반시설을 조성하기 위하여 도시·군계획시설결정을 할 때 행사하는 재량권에는 한계가 있다.":"기반시설 계획을 정하는 재량도 무한하지 않아서 법이 정한 한계를 벗어나면 위법이 됩니다.","행정주체가 사법형식으로 공행정을 수행하는 경우에도 기본권과 행정법의 일반원칙 등 공법적 제한을 받는다. 사적자치의 원칙이 통용된다고 공법적 제한을 받지 않는 것이 아니다.":"공행정을 사법 형식으로 수행해도 기본권과 행정법 원칙의 제약을 받으며 사적자치가 통한다고 면제되지 않습니다.","행정주체는 구체적인 행정계획을 입안·결정하면서 비교적 광범위한 형성의 자유를 가진다.":"행정계획은 목표 달성 방법이 다양해서 행정주체가 입안하고 결정할 때 비교적 넓은 재량을 가집니다.","행정지도가 말로 이루어지는 경우 상대방이 서면의 교부를 요구하면, 직무 수행에 특별한 지장이 없는 한 서면을 교부하여야 한다. 행정지도를 반드시 서면으로 해야 하는 것은 아니다.":"말로 한 행정지도라도 상대방이 서면을 요구하면 특별한 지장이 없는 한 줘야 하고 처음부터 서면일 필요는 없습니다.","행정지도는 그 목적 달성에 필요한 최소한도에 그쳐야 하며, 상대방의 의사에 반하여 부당하게 강요하여서는 아니 된다.":"행정지도는 필요한 최소한에 그쳐야 하고 상대방이 원하지 않는데 부당하게 강요하면 안 됩니다.","행정지도를 하는 자는 그 상대방에게 그 행정지도의 취지 및 내용과 신분을 밝혀야 한다.":"지도하는 사람은 상대방에게 지도의 취지와 내용 그리고 자신의 신분을 밝히고 해야 합니다.","행정지도에도 법률우위의 원칙은 적용된다.":"행정지도가 비권력적이라도 법률에 어긋나는 내용으로 할 수 없다는 법률우위는 그대로 적용됩니다.","행정지도와 같은 비권력적 작용도 국가배상법상 공무원의 직무에 포함된다.":"행정지도처럼 강제력이 없는 작용도 공무원의 직무이므로 그로 인한 손해에 국가배상이 가능합니다.","행정지도의 상대방은 해당 행정지도의 방식·내용 등에 관하여 행정기관에 의견제출을 할 수 있다.":"지도를 받는 사람은 지도의 방식과 내용에 대해 행정기관에 의견을 낼 수 있습니다.","행정지도의 원칙(임의성 원칙 등)은 행정절차법이 규정한다. 행정기본법에는 없다.":"행정지도의 임의성 같은 원칙은 행정절차법에 있고 행정기본법에는 이를 정한 조문이 없습니다.","행정처분의 무효 확인을 구하는 소에는 특단의 사정이 없는 한 취소를 구하는 취지도 포함되어 있다.":"무효확인을 구하는 소에는 특별한 사정이 없으면 그 처분을 취소해 달라는 뜻도 함께 담긴 것으로 봅니다.","행정처분인 해당 행위의 취소 또는 변경을 요구하거나 그 행위의 효력 유무 또는 존재 여부의 확인을 요구하는 소송.":"주민소송 중 처분의 취소와 변경 요구나 효력 유무와 존재 여부의 확인을 구하는 유형입니다.","행정청(대집행을 실행하는 제3자 포함)은 해가 뜨기 전이나 해가 진 후에는 대집행을 하여서는 아니 된다.":"대집행은 주민 안전과 평온을 위해 해가 뜨기 전이나 해가 진 뒤에는 하지 못하도록 시간이 제한됩니다.","행정청(의사 결정·표시), 보조기관, 보좌기관, 자문기관, 의결기관, 집행기관, 감사기관 등.":"행정기관은 하는 일에 따라 행정청과 보조기관과 보좌기관과 자문기관과 의결기관과 집행기관과 감사기관 등으로 나눕니다.","행정청에는 법령등에 따라 행정권한을 가지고 있거나 위임 또는 위탁받은 공공단체 또는 그 기관이나 사인(私人)도 포함된다. 법령에 따라 행정권한을 위탁받은 사인도 행정청이 될 수 있다.":"행정권한을 위임이나 위탁받은 공공단체와 사인도 그 범위에서는 행정청이 될 수 있습니다.","행정청은 계획 중 국민의 권리·의무에 직접 영향을 미치는 계획을 수립하거나 변경·폐지할 때 관련된 여러 이익을 정당하게 형량하여야 한다.":"국민의 권리와 의무에 직접 영향을 주는 계획을 세우거나 바꾸거나 없앨 때는 관련 이익을 정당하게 저울질해야 합니다.","행정청은 공법상 계약의 상대방을 선정하고 계약 내용을 정할 때 공법상 계약의 공공성과 제3자의 이해관계를 고려하여야 한다.":"계약 상대방을 고르고 내용을 정할 때 공공성과 제삼자의 이해관계를 함께 고려해야 합니다.","행정청은 공익 또는 제3자의 이익을 현저히 해칠 우려가 있는 경우를 제외하고는 행정에 대한 국민의 정당하고 합리적인 신뢰를 보호하여야 한다.":"국민이 행정을 정당하게 믿고 행동했다면 그 신뢰를 보호하되 공익이나 제삼자를 크게 해치면 예외입니다.","행정청은 권한 행사의 기회가 있음에도 장기간 권한을 행사하지 아니하여 국민이 그 권한이 행사되지 아니할 것으로 믿을 만한 정당한 사유가 있으면 그 권한을 행사해서는 아니 된다. 공익 또는 제3자의 이익을 현저히 해칠 우려가 있으면 예외다.":"행정청이 오래 권한을 쓰지 않아 국민이 믿을 만하게 되면 뒤늦은 행사를 막지만 공익을 해치면 예외입니다.","행정청은 당사자등이 제출한 의견이 상당한 이유가 있다고 인정하는 경우 이를 반영하여야 한다. 반영하지 아니하고 처분한 경우 당사자등이 처분이 있음을 안 날부터 90일 이내에 이유의 설명을 요청하면 서면으로 이유를 알려야 한다.":"의견이 타당하면 반영해야 하고 반영하지 않았다면 처분을 안 날부터 90일 안에 요청할 때 서면으로 이유를 설명합니다.","행정청은 당사자에게 의무를 부과하거나 권익을 제한하는 처분을 하는 경우에는 미리 처분의 제목, 당사자의 성명 또는 명칭과 주소, 처분하려는 원인이 되는 사실과 처분의 내용 및 법적 근거, 의견을 제출할 수 있다는 뜻과 의견을 제출하지 아니하는 경우의 처리방법, 의견제출기관의 명칭과 주소, 의견제출기한, 그 밖에 필요한 사항을 당사자등에게 통지하여야 한다.":"의무를 지우거나 권익을 제한하는 처분을 하기 전에 원인 사실과 내용과 법적 근거와 의견제출 방법 등을 미리 알려야 합니다.","행정청은 대집행 과정에서의 안전 확보를 위하여 필요하다고 인정하는 경우 현장에 긴급 의료장비나 시설을 갖추는 등 필요한 조치를 하여야 한다.":"대집행 현장에서 사고가 날 수 있으므로 필요하면 긴급 의료장비와 시설을 갖추는 등 안전 조치를 해야 합니다.","행정청은 법령등에 따른 의무를 성실히 수행하여야 한다.":"성실의무는 행정청이 법령에서 맡은 의무를 형식만이 아니라 제대로 이행해야 한다는 원칙입니다.","행정청은 법령등에 따른 의무를 위반한 자에 대하여 법률로 정하는 바에 따라 그 위반행위에 대한 제재로서 과징금을 부과할 수 있다.":"과징금은 법령상 의무를 어긴 사람에게 법률 근거에 따라 제재로 매기는 금전 부담입니다.","행정청은 법령등을 위반하지 아니하는 범위에서 행정목적을 달성하기 위하여 필요한 경우에는 공법상 법률관계에 관한 계약을 체결할 수 있다. 이 경우 계약의 목적 및 내용을 명확하게 적은 계약서를 작성하여야 한다.":"법령에 어긋나지 않는 범위에서 행정목적을 위해 공법상 계약을 맺을 수 있고 목적과 내용을 분명히 적은 계약서를 써야 합니다.","행정청은 송달하는 문서의 명칭, 송달받는 자의 성명 또는 명칭, 발송방법 및 발송 연월일을 확인할 수 있는 기록을 보존하여야 한다.":"무엇을 누구에게 어떻게 언제 보냈는지 나중에 확인할 수 있도록 송달 기록을 남겨 두어야 합니다.","행정청은 신청에 필요한 구비서류, 접수기관, 처리기간, 그 밖에 필요한 사항을 게시하거나 편람을 갖추어 두고 누구나 열람할 수 있도록 하여야 한다.":"신청에 필요한 서류와 접수 기관과 처리 기간 등을 게시하거나 편람으로 두어 누구든 볼 수 있게 해야 합니다.","행정청은 신청을 받았을 때 접수를 보류·거부하거나 부당하게 되돌려 보내서는 아니 되며, 접수한 경우 신청인에게 접수증을 주어야 한다.":"신청이 오면 일단 접수해야 하고 미루거나 돌려보낼 수 없으며 접수했다는 증거로 접수증을 내줘야 합니다.","행정청은 신청인의 편의를 위하여 다른 행정청에 신청을 접수하게 할 수 있고, 이 경우 접수할 수 있는 신청의 종류를 미리 정하여 공시하여야 한다. 행정청의 편의를 위한 것이 아니다.":"다른 행정청에 접수하게 하는 것은 신청인이 편하도록 하는 것이며 접수할 수 있는 종류를 미리 공시해야 합니다.","행정청은 요건을 갖추지 못한 신고서가 제출된 경우 지체 없이 상당한 기간을 정하여 보완을 요구하여야 하며, 보완하지 아니하면 그 이유를 구체적으로 밝혀 신고서를 되돌려 보내야 한다.":"신고서가 미비하면 곧바로 보완 기간을 주고 요구해야 하며 끝내 보완이 없으면 이유를 밝혀 돌려보냅니다.","행정청은 위법 또는 부당한 처분의 전부나 일부를 소급하여 취소할 수 있다. 취소사유에는 위법뿐 아니라 부당도 포함된다.":"행정청은 위법한 처분은 물론 부당한 처분도 전부나 일부를 처음 시점으로 거슬러 올라가 취소할 수 있습니다.","행정청은 의견 제출 절차를 마친 후 서면(당사자 동의 시 전자문서)으로 과태료를 부과하여야 한다.":"의견 제출 절차를 끝낸 뒤에 서면으로 과태료를 부과하며 당사자가 동의하면 전자문서로도 가능합니다.","행정청은 재량이 있는 처분을 할 때 관련 이익을 정당하게 형량하여야 하며, 재량권의 범위를 넘어서는 아니 된다.":"재량 처분을 할 때에는 관련된 여러 이익을 정당하게 저울질해야 하고 재량의 범위를 벗어날 수 없습니다.","행정청은 직무를 수행할 때 신의에 따라 성실히 하여야 하고, 법령등의 해석 또는 관행이 일반적으로 받아들여졌을 때에는 소급하여 불리하게 처리하여서는 아니 된다.":"신의성실과 신뢰보호를 행정절차법에도 규정해 받아들여진 해석이 바뀌어도 소급해 불리하게 처리하지 못하게 합니다.","행정청은 직무를 수행할 때 신의에 따라 성실히 하여야 한다.":"행정절차법에도 직무는 신의에 따라 성실하게 해야 한다고 정해져 있어 같은 취지를 따로 둔 규정입니다.","행정청은 질서위반행위가 종료된 날(다수인 가담 시 최종행위 종료일)부터 5년이 경과하면 과태료를 부과할 수 없다.":"위반행위가 끝난 날부터 5년이 지나면 오래된 일로 보아 더는 과태료를 부과할 수 없습니다.","행정청은 처분에 재량이 있는 경우에는 부관을 붙일 수 있다. 행정청은 처분에 재량이 없는 경우에는 법률에 근거가 있는 경우에 부관을 붙일 수 있다.":"재량이 있는 처분에는 부관을 붙일 수 있고 재량이 없는 처분은 법률에 근거가 있을 때만 붙일 수 있습니다.","행정청은 처분을 할 때 당사자에게 그 근거와 이유를 제시하여야 한다. 이해관계인이 아니라 당사자에게 제시한다.":"처분의 근거와 이유는 처분 상대방인 당사자에게 밝혀야 하고 단순한 이해관계인이 대상은 아닙니다.","행정청은 처분 후 1년 이내에 당사자등이 요청하면 청문·공청회·의견제출을 위하여 제출받은 서류나 그 밖의 물건을 반환하여야 한다.":"당사자가 제출한 서류는 처분 후 1년 이내에 요청하면 행정청이 돌려줘야 합니다.","행정청은 청문·공청회 또는 의견제출을 거쳤을 때에는 신속히 처분하여 해당 처분이 지연되지 아니하도록 하여야 한다.":"청문이나 공청회 등 절차를 마쳤다면 처분이 늦춰지지 않도록 지체 없이 처분해야 합니다.","행정청은 청문이 시작되는 날부터 7일 전까지 청문 주재자에게 청문과 관련한 필요한 자료를 미리 통지하여야 한다.":"주재자가 준비할 수 있도록 청문 시작 7일 전까지 필요한 자료를 미리 넘겨야 합니다.","행정청은 합리적 이유 없이 국민을 차별하여서는 아니 된다.":"비슷한 사안은 똑같이 처리해야 하고 합리적 이유가 있을 때만 다르게 대할 수 있습니다.","행정청은 행정권한을 남용하거나 그 권한의 범위를 넘어서는 아니 된다.":"행정청은 권한을 본래 목적과 다르게 쓰거나 맡은 범위를 벗어나 행사해서는 안 됩니다.","행정청은 행정의 원활한 수행을 위하여 서로 협조하여야 한다.":"행정청들은 행정이 원활히 이루어지도록 서로 협조해야 하며 협조는 행정응원의 바탕이 됩니다.","행정청은 행정작용을 할 때 상대방에게 해당 행정작용과 실질적인 관련이 없는 의무를 부과해서는 아니 된다. 부관은 해당 처분과 실질적인 관련이 있어야 한다(부당결부금지의 구체화).":"행정작용과 관련 없는 의무를 덧붙여 요구할 수 없고 부관도 그 처분과 실질적으로 이어져야 합니다.","행정청의 공적 견해표명, 상대방의 귀책사유 없는 신뢰, 신뢰에 기한 상대방의 조치(처리), 그 견해표명에 반하는 처분으로 인한 이익 침해의 4가지.":"신뢰보호가 인정되려면 공적 견해표명, 귀책사유 없는 신뢰, 신뢰에 따른 조치, 그에 반하는 처분의 침해가 모두 있어야 합니다.","행정청의 과태료 부과에 불복하는 당사자는 부과 통지를 받은 날부터 60일 이내에 해당 행정청에 서면으로 이의제기를 할 수 있다. 이의제기가 있으면 행정청의 과태료 부과처분은 효력을 상실한다.":"부과 통지를 받은 날부터 60일 안에 서면으로 이의제기를 하면 행정청의 부과처분은 효력을 잃고 법원 판단으로 넘어갑니다.","행정청의 관할이 분명하지 아니한 경우 공통으로 감독하는 상급 행정청이 관할을 결정하고, 공통 상급 행정청이 없으면 각 상급 행정청이 협의하여 결정한다.":"관할이 불분명하면 공통의 상급 행정청이 정하고 공통 상급이 없으면 각 상급 행정청이 협의해 정합니다.","행정청의 재량에 속하는 처분이라도 재량권의 한계를 넘거나 그 남용이 있는 때에는 법원은 이를 취소할 수 있다.":"재량 처분이라도 한계를 넘거나 남용되었다면 법원의 심사 대상이 되어 법원이 취소할 수 있습니다.","행정청의 처분등을 원인으로 하는 법률관계에 관한 소송 그 밖에 공법상의 법률관계에 관한 소송으로서 그 법률관계의 한쪽 당사자를 피고로 하는 소송.":"당사자소송은 공법상 법률관계를 다투면서 처분청이 아니라 그 법률관계의 한쪽 당사자를 피고로 삼는 소송입니다.","행정청의 처분 또는 부작위에 대하여는 다른 법률에 특별한 규정이 있는 경우 외에는 행정심판법에 따라 행정심판을 청구할 수 있다.":"행정청의 처분이나 부작위에 불복할 때 다른 법률에 특별 규정이 없다면 행정심판법에 따라 행정심판을 청구합니다.","행정청의 처분에 대하여 직접 그 상대가 되는 당사자, 행정청이 직권으로 또는 신청에 따라 행정절차에 참여하게 한 이해관계인.":"당사자등은 처분의 직접 상대방과 행정청이 절차에 참여하도록 허용한 이해관계인을 함께 가리킵니다.","행정청의 행정행위 취소가 있더라도 취소사유의 내용, 경위 기타 제반 사정을 종합하여 행정행위의 효력을 장래에 향해 소멸시키는 철회에 해당하는지 살펴보아야 한다.":"이름이 취소여도 사유와 경위를 종합해 보면 장래로만 효력을 없애는 철회일 수 있어 실질을 따져야 합니다.","행정청이 공적 견해표명을 한 후 사정변경이 있는 경우, 특별한 사정이 없는 한 그 견해표명에 반하는 처분을 하더라도 신뢰보호원칙 위반이 아니다.":"견해를 밝힌 뒤 사정이 바뀌었다면 앞서 밝힌 의견과 다른 처분을 해도 특별한 사정이 없는 한 위반이 아닙니다.","행정청이 관할에 속하지 아니하는 사안을 접수하였거나 이송받은 경우에는 지체 없이 관할 행정청에 이송하여야 하고 그 사실을 신청인에게 통지하여야 한다. 행정청의 관할이 분명하지 아니한 경우에는 해당 행정청을 공통으로 감독하는 상급 행정청이 관할을 결정하며, 공통으로 감독하는 상급 행정청이 없으면 각 상급 행정청이 협의하여 결정한다.":"관할이 아닌 사안은 곧바로 관할 행정청에 넘기고 신청인에게 알리며 관할이 불분명하면 공통 상급 행정청이 정합니다.","행정청이 당사자의 신청에 대하여 상당한 기간 내에 일정한 처분을 하여야 할 법률상 의무가 있는데도 처분을 하지 아니하는 것.":"부작위는 신청을 받고 상당한 기간 안에 처분할 법률상 의무가 있는데도 아무 처분을 하지 않는 것을 말합니다.","행정청이 대집행의 방법으로 건물철거의무의 이행을 실현할 수 있는 경우, 건물철거 대집행 과정에서 부수적으로 건물 점유자들에 대한 퇴거 조치를 할 수 있다.":"건물철거 대집행을 실현하는 과정에서 부수적으로 건물 점유자를 내보내는 퇴거 조치도 할 수 있습니다.","행정청이 심판청구 기간을 90일보다 긴 기간으로 잘못 알린 경우 그 잘못 알린 기간에 청구가 있으면 90일 이내에 청구된 것으로 본다.":"행정청이 90일보다 길게 잘못 알려 줬다면 그 기간 안에 청구해도 90일 안에 청구한 것으로 인정합니다.","행정청이 심판청구 기간을 알리지 아니한 경우에는 처분이 있었던 날부터 180일 이내에 심판청구를 할 수 있다.":"청구 기간을 알리지 않았다면 처분이 있었던 날부터 180일까지 청구할 수 있습니다.","행정청이 제재처분 양정을 하면서 이익형량을 하였더라도 양정에 정당성·객관성이 결여된 경우에는 재량권 일탈·남용으로 위법하다.":"이익형량을 했더라도 제재의 정도를 정한 과정이 정당하지 않거나 객관성이 없다면 재량 일탈과 남용으로 위법합니다.","행정청이 청문이 필요하다고 인정하는 경우에는 법령등에 청문 규정이 없더라도 청문을 할 수 있다.":"법령에 청문 규정이 없더라도 행정청이 필요하다고 판단하면 스스로 청문을 열 수 있습니다.","행정청이 행하는 구체적 사실에 관한 법집행으로서의 공권력의 행사 또는 그 거부와 그 밖에 이에 준하는 행정작용 및 행정심판에 대한 재결.":"처분등은 구체적 사실에 관한 공권력 행사나 그 거부와 이에 준하는 행정작용과 행정심판의 재결을 모두 가리킵니다.","행정행위의 상대방이나 이해관계인에 대한 구속력으로, 법령에 의한 불복기간이 경과하면 그 처분의 효력을 다툴 수 없다.":"불가쟁력은 불복 기간이 지나면 상대방이 더는 쟁송으로 처분을 다투지 못하게 되는 효력입니다.","행정행위의 취소는 일단 유효하게 성립한 행정행위를 성립 당시 존재하던 하자를 사유로 소급하여 효력을 소멸시키는 행정처분이다.":"취소는 성립 당시에 있던 하자를 이유로 처분의 효력을 소급해서 없애는 행정처분입니다.","행정형벌: 행정법상 의무 위반에 대해 형법상 형명(사형·징역·금고·벌금·구류·과료·몰수)이 있는 벌을 과하는 것. 행정질서벌: 과태료를 과하는 것.":"행정형벌은 의무 위반에 징역이나 벌금 같은 형법상 형벌을 주는 것이고 행정질서벌은 과태료를 부과하는 것입니다.","행정형벌에는 원칙적으로 형법총칙이 적용되고, 형사소송절차에 따라 법원이 부과한다. 과태료는 질서위반행위규제법과 비송사건절차에 따른다.":"행정형벌은 형법총칙과 형사소송절차에 따라 법원이 과하고 과태료는 질서위반행위규제법과 비송사건절차로 처리합니다.","헌법, 법률, 조약·국제법규, 명령(대통령령·총리령·부령), 자치법규(조례·규칙), 대법원규칙·헌법재판소규칙·국회규칙·중앙선거관리위원회규칙.":"문서로 된 성문법원에는 헌법과 법률, 조약, 명령, 자치법규, 각 기관의 규칙이 모두 들어갑니다.","헌법이 인정하고 있는 위임입법의 형식은 예시적인 것이다.":"헌법에 열거된 위임입법 형식은 예시에 불과해 그 밖의 형식으로 위임하는 것도 가능합니다.","현장에 파견되는 집행책임자는 집행책임자라는 것을 표시한 증표를 휴대하여 대집행시에 이해관계인에게 제시하여야 한다.":"현장에 나가는 집행책임자는 신분을 보여 주는 증표를 지니고 있다가 이해관계인에게 제시해야 합니다.","현재의 급박한 행정상의 장해를 제거하기 위한 경우로서 행정청이 미리 의무 이행을 명할 시간적 여유가 없거나, 그 성질상 의무 이행을 명하는 것만으로는 행정목적 달성이 곤란한 경우에 곧바로 국민의 신체 또는 재산에 실력을 행사하여 행정목적을 달성하는 것.":"즉시강제는 급박한 장해 때문에 미리 명령할 틈이 없거나 명령만으로 목적을 이룰 수 없을 때 바로 실력을 행사하는 수단입니다.","협의가 된 사항에 대해서는 주된 인허가를 받았을 때 관련 인허가를 받은 것으로 본다. 협의가 되었다는 사실만으로 받은 것으로 보지 않는다. 인허가의제의 효과는 주된 인허가의 해당 법률에 규정된 관련 인허가에 한정된다.":"협의된 사항은 주된 인허가를 받는 때 관련 인허가를 받은 것이 되고 협의 사실만으로는 안 되며 해당 법률에 열거된 것에 한정됩니다.","협의가 성립되지 아니하거나 협의를 할 수 없을 때 사업시행자는 사업인정고시가 된 날부터 1년 이내에 관할 토지수용위원회에 재결을 신청할 수 있다.":"협의가 안 될 때 사업시행자는 사업인정고시일부터 1년 안에 관할 토지수용위원회에 재결을 신청할 수 있습니다.","협의를 요청받은 관련 인허가 행정청은 해당 법령을 위반하여 협의에 응해서는 아니 된다.":"관련 행정청은 협의에 응하더라도 자신이 맡은 법령의 기준을 어기면서까지 동의해 줄 수는 없습니다.","형사, 행형 및 보안처분 관계 법령에 따라 행하는 사항.":"형사와 행형과 보안처분은 별도 법령의 절차가 있어서 행정절차법 적용 대상에서 제외됩니다.","형사, 행형 및 보안처분 관계 법령에 따라 행하는 사항이나 외국인의 출입국·난민인정·귀화·국적회복에 관한 사항에는 행정상 강제 규정(행정기본법 제5절)을 적용하지 아니한다.":"형사 관련 사항과 외국인의 출입국과 귀화에 관한 사항에는 행정기본법의 행정상 강제 규정이 적용되지 않습니다.","확약은 문서로 하여야 한다.":"확약은 내용을 분명히 남기기 위해 말이 아니라 문서의 형식을 갖춰야 합니다.","확약은 일방적 행위라는 점에서 복수당사자의 의사의 합치인 공법상 계약과는 구분된다.":"확약은 행정청 혼자 하는 일방적 의사표시이고 공법상 계약은 양쪽의 합의라서 구분됩니다.","확약은 정당한 권한을 가진 행정청에 의해서 그 권한의 범위 내에서만 발해질 수 있다.":"확약은 그 처분을 할 권한이 있는 행정청이 자기 권한 범위 안에서만 할 수 있습니다.","확약은 종국적 규율이 아니라는 점에서 종국적 규율을 하는 사전결정이나 부분허가와 구분된다.":"확약은 최종적으로 정하는 것이 아니라 장래 처분의 약속이라서 종국적인 사전결정이나 부분허가와 다릅니다.","확약을 이행할 수 없는 경우 행정청은 지체 없이 당사자에게 그 사실을 통지하여야 한다.":"확약을 지킬 수 없게 되면 행정청은 곧바로 당사자에게 그 사실을 알려야 합니다.","확약 후 내용을 이행할 수 없을 정도로 법령등이나 사정이 변경된 경우, 확약이 위법한 경우. 이때 행정청의 별도의 의사표시가 있어야 구속력이 상실되는 것은 아니다.":"법령이나 사정이 크게 바뀌거나 확약이 위법하면 별도 의사표시 없이도 행정청은 확약에 구속되지 않습니다.","후행행위는 하자가 없이 적법해야 한다.":"하자 승계는 뒤따르는 행위 자체는 적법한데 앞선 행위의 하자만 문제 삼는 경우를 전제로 합니다.","훈령·예규·고시·지침 등은 고시·공고 등의 방법으로 발령한 날을 공포한 날로 본다.":"훈령이나 고시처럼 공포 절차가 없는 규범은 고시하거나 공고해 발령한 날을 공포한 날로 칩니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
